(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,17477,e=>{e.v(JSON.parse('[{"id":"q001","tier":"free","category":"tactical","scenario":{"ja":"暗闘の廃墟。銃声が止んだ。\\n味方は2人ダウン。敵は1人、どこかに潜んでいる。\\n弾は残り5発。\\n静寂の中、お前の次の一手が全てを決める。","en":"A ruined building, shrouded in darkness. Gunfire has ceased.\\nTwo allies are down. One enemy lurks somewhere.\\nFive rounds left.\\nIn the silence, your next move decides everything."},"options":[{"id":"a","text":{"ja":"走り込む。奇襲で仕留める。","en":"Rush in. Take them by surprise."},"scores":{"aggression":15,"altruism":-5,"cooperation":-10,"intuition":10,"mastery":-5}},{"id":"b","text":{"ja":"味方を蘇生しに行く。数の有利を取る。","en":"Revive allies first. Gain numerical advantage."},"scores":{"aggression":-10,"altruism":15,"cooperation":15,"intuition":-5,"mastery":5}},{"id":"c","text":{"ja":"音を聞く。敵の位置を特定してから動く。","en":"Listen. Locate the enemy before moving."},"scores":{"aggression":-15,"altruism":0,"cooperation":0,"intuition":-10,"mastery":15}},{"id":"d","text":{"ja":"撤退する。生き残ることが最優先。","en":"Retreat. Survival is the priority."},"scores":{"aggression":-10,"altruism":-10,"cooperation":-5,"intuition":5,"mastery":-10}}]},{"id":"q002","tier":"free","category":"social","scenario":{"ja":"ランクマッチ。味方のひとりがVCで暴言を吐き続けている。\\n「お前のせいで負けたんだよ」\\nチーム全体の士気が下がっていく。\\nお前はどうする。","en":"Ranked match. One teammate won\'t stop flaming on voice chat.\\n\\"We lost because of you.\\"\\nTeam morale is plummeting.\\nWhat do you do."},"options":[{"id":"a","text":{"ja":"正面から言い返す。間違いは正す。","en":"Call them out directly. Wrong is wrong."},"scores":{"aggression":10,"altruism":5,"cooperation":-5,"intuition":10,"mastery":10}},{"id":"b","text":{"ja":"ミュートして無視。自分のプレイに集中する。","en":"Mute and ignore. Focus on your own play."},"scores":{"aggression":-5,"altruism":-10,"cooperation":-15,"intuition":-5,"mastery":10}},{"id":"c","text":{"ja":"チームを落ち着かせようとする。空気を変える。","en":"Try to calm the team. Change the mood."},"scores":{"aggression":-10,"altruism":15,"cooperation":15,"intuition":5,"mastery":-5}},{"id":"d","text":{"ja":"黙って実力で黙らせる。結果が全て。","en":"Say nothing. Let your performance speak."},"scores":{"aggression":5,"altruism":-5,"cooperation":-10,"intuition":-10,"mastery":15}}]},{"id":"q003","tier":"free","category":"meta","scenario":{"ja":"新作ゲームが2本、同時に発売された。\\nひとつは、誰もが話題にしている超大作。もうひとつは、知る人ぞ知るインディーの傑作。\\nお金は1本分しかない。\\nどちらを手に取る。","en":"Two new games released on the same day.\\nOne is the blockbuster everyone\'s talking about. The other is a critically acclaimed indie gem.\\nYou can only afford one.\\nWhich do you pick up."},"options":[{"id":"a","text":{"ja":"超大作。みんなとプレイしたい。","en":"The blockbuster. I want to play with everyone."},"scores":{"aggression":0,"altruism":5,"cooperation":15,"intuition":-5,"mastery":-10}},{"id":"b","text":{"ja":"インディー。自分だけの体験が欲しい。","en":"The indie gem. I want my own unique experience."},"scores":{"aggression":0,"altruism":-5,"cooperation":-15,"intuition":10,"mastery":15}},{"id":"c","text":{"ja":"レビューを読み込んでから決める。","en":"Read reviews extensively, then decide."},"scores":{"aggression":-5,"altruism":0,"cooperation":0,"intuition":-15,"mastery":5}},{"id":"d","text":{"ja":"セール待ち。今は積みゲーを崩す。","en":"Wait for a sale. Clear the backlog first."},"scores":{"aggression":-10,"altruism":0,"cooperation":0,"intuition":-5,"mastery":-15}}]},{"id":"q004","tier":"free","category":"tactical","scenario":{"ja":"最終ラウンド。スコアは同点。\\n残り時間30秒。お前のチームは防衛側。\\n敵は一斉に攻めてくる気配がある。\\nお前はスナイパー。高台からエリア全体が見える。","en":"Final round. Score is tied.\\n30 seconds left. Your team is on defense.\\nThe enemy is about to rush.\\nYou\'re the sniper. You overlook the entire area from the high ground."},"options":[{"id":"a","text":{"ja":"高台を捨てて前に出る。敵の裏を取る。","en":"Leave the high ground. Flank the enemy."},"scores":{"aggression":15,"altruism":-5,"cooperation":-10,"intuition":15,"mastery":-5}},{"id":"b","text":{"ja":"高台に留まる。一発一発を確実に当てる。","en":"Hold position. Make every shot count."},"scores":{"aggression":-5,"altruism":0,"cooperation":5,"intuition":-15,"mastery":15}},{"id":"c","text":{"ja":"味方にカバーの指示を出しながら援護する。","en":"Call out positions and provide cover fire for allies."},"scores":{"aggression":-5,"altruism":10,"cooperation":15,"intuition":-5,"mastery":5}},{"id":"d","text":{"ja":"武器を持ち替える。近距離戦に備える。","en":"Switch weapons. Prepare for close combat."},"scores":{"aggression":10,"altruism":-5,"cooperation":-5,"intuition":10,"mastery":-10}}]},{"id":"q005","tier":"free","category":"social","scenario":{"ja":"チームの仲間が、大事な大会の前に脱退を告げてきた。\\n「リアルが忙しくて、もう続けられない」\\nお前はチームリーダーだ。大会まであと3日。\\n代わりのメンバーを探す時間はギリギリある。","en":"A clan member announces they\'re leaving, right before a major tournament.\\n\\"Real life got too busy. I can\'t continue.\\"\\nYou\'re the clan leader. Three days until the tournament.\\nThere\'s barely enough time to find a replacement."},"options":[{"id":"a","text":{"ja":"引き止める。最後まで責任を果たせ。","en":"Convince them to stay. Finish what you started."},"scores":{"aggression":10,"altruism":-5,"cooperation":10,"intuition":5,"mastery":10}},{"id":"b","text":{"ja":"快く送り出す。人生の方が大事だ。","en":"Let them go gracefully. Life comes first."},"scores":{"aggression":-15,"altruism":15,"cooperation":5,"intuition":5,"mastery":-10}},{"id":"c","text":{"ja":"すぐに代わりを探し始める。感情は後。","en":"Immediately start looking for a replacement. Emotions later."},"scores":{"aggression":5,"altruism":-10,"cooperation":5,"intuition":-10,"mastery":-5}},{"id":"d","text":{"ja":"4人で出る。少数精鋭で戦う。","en":"Enter with 4. Fight as an elite few."},"scores":{"aggression":10,"altruism":0,"cooperation":-15,"intuition":15,"mastery":15}}]},{"id":"q010","tier":"free","category":"meta","scenario":{"ja":"深夜3時。明日は大事な用事がある。\\nでも今、ゲームが最高に楽しい。\\n「あと1試合だけ」を3回言った。\\n画面の光だけが、暗い部屋を照らしている。","en":"3 AM. You have something important tomorrow.\\nBut the game is hitting different right now.\\nYou\'ve said \'just one more match\' three times.\\nThe screen\'s glow is the only light in the dark room."},"options":[{"id":"a","text":{"ja":"もう1試合。後悔は明日の俺に任せる。","en":"One more. Future me can deal with the consequences."},"scores":{"aggression":10,"altruism":-10,"cooperation":0,"intuition":15,"mastery":-15}},{"id":"b","text":{"ja":"やめる。自制心がプレイヤーとしての格。","en":"Stop. Self-discipline defines a true player."},"scores":{"aggression":-15,"altruism":5,"cooperation":0,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"アラームをセットして、あと30分だけ。","en":"Set an alarm. 30 more minutes, no exceptions."},"scores":{"aggression":0,"altruism":0,"cooperation":0,"intuition":-5,"mastery":5}},{"id":"d","text":{"ja":"明日の用事をキャンセルする。今この瞬間が大事。","en":"Cancel tomorrow\'s plans. This moment matters more."},"scores":{"aggression":15,"altruism":-15,"cooperation":-5,"intuition":15,"mastery":-10}}]},{"id":"q012","tier":"free","category":"tactical","scenario":{"ja":"チーム戦。序盤から優勢。\\n自分の担当エリアでは敵を圧倒している。\\nだが隣のエリアの味方がボコボコにされている。\\n助けに行けば自分のエリアが手薄になる。","en":"MOBA. Early laning phase.\\nYou\'ve scored two kills and have a level advantage.\\nYour teammate in the next lane is getting destroyed.\\nBut if you roam now, you might lose your own tower."},"options":[{"id":"a","text":{"ja":"助けに行く。チーム全体が大事。","en":"Roam and help. The team matters most."},"scores":{"aggression":0,"altruism":15,"cooperation":15,"intuition":15,"mastery":0}},{"id":"b","text":{"ja":"自分のエリアを攻め続ける。ここを制圧する方が価値がある。","en":"Keep pushing your lane. Taking the tower is worth more."},"scores":{"aggression":-15,"altruism":-5,"cooperation":-15,"intuition":-15,"mastery":-15}},{"id":"c","text":{"ja":"警告だけ出す。判断は味方に任せる。","en":"Ping a warning. Whether they listen is on them."},"scores":{"aggression":0,"altruism":-5,"cooperation":5,"intuition":-15,"mastery":-5}},{"id":"d","text":{"ja":"敵の裏側に回り込む。別の角度から圧力をかける。","en":"Invade their jungle. Apply pressure from behind."},"scores":{"aggression":-5,"altruism":-15,"cooperation":0,"intuition":15,"mastery":-10}}]},{"id":"q013","tier":"free","category":"tactical","scenario":{"ja":"サバイバルホラー。弾薬はショットガン2発だけ。\\n暗い廊下の先に、セーブルームがある。\\nでもその途中に、何かがいる気配がする。\\n迂回路はある。ただし3倍の距離。","en":"Survival horror. Two shotgun shells left.\\nA save room lies at the end of this dark corridor.\\nBut something lurks between you and it.\\nThere\'s a detour. Three times the distance."},"options":[{"id":"a","text":{"ja":"直進する。2発あれば十分。","en":"Go straight. Two shells is enough."},"scores":{"aggression":15,"altruism":-10,"cooperation":0,"intuition":10,"mastery":-15}},{"id":"b","text":{"ja":"迂回する。弾薬は温存すべき。","en":"Take the detour. Conserve ammunition."},"scores":{"aggression":-5,"altruism":15,"cooperation":10,"intuition":-10,"mastery":-5}},{"id":"c","text":{"ja":"ナイフに切り替える。弾は最後の手段。","en":"Switch to the knife. Save bullets for emergencies."},"scores":{"aggression":5,"altruism":-5,"cooperation":0,"intuition":-10,"mastery":15}},{"id":"d","text":{"ja":"物を投げて様子を見る。敵の数を確認する。","en":"Throw something. Scout how many are out there."},"scores":{"aggression":-5,"altruism":15,"cooperation":-5,"intuition":-15,"mastery":10}}]},{"id":"q014","tier":"free","category":"tactical","scenario":{"ja":"ステルスゲーム。潜入ミッション。\\n目標の部屋まであと少し。だが警備員が2人、巡回ルートを変えた。\\nこのまま行けば見つかる確率が高い。\\n屋上からのルートがあるが、時間がかかる。","en":"Stealth game. Infiltration mission.\\nAlmost at the target room. But two guards just changed their patrol route.\\nGoing forward means high chance of detection.\\nThere\'s a rooftop route, but it\'ll cost time."},"options":[{"id":"a","text":{"ja":"2人とも倒す。見つかっても構わない。","en":"Take them both out. Detection doesn\'t matter."},"scores":{"aggression":15,"altruism":0,"cooperation":0,"intuition":10,"mastery":-10}},{"id":"b","text":{"ja":"タイミングを計って間をすり抜ける。","en":"Time their patterns and slip through the gap."},"scores":{"aggression":0,"altruism":5,"cooperation":15,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"屋上ルートを取る。確実性が全て。","en":"Take the rooftop. Certainty above all."},"scores":{"aggression":-15,"altruism":5,"cooperation":5,"intuition":-10,"mastery":10}},{"id":"d","text":{"ja":"陽動を仕掛ける。注意を逸らして突破する。","en":"Create a distraction. Draw their attention, then move."},"scores":{"aggression":-10,"altruism":0,"cooperation":-5,"intuition":15,"mastery":-5}}]},{"id":"q016","tier":"free","category":"tactical","scenario":{"ja":"大人数のボス戦。8人のチーム。ボスの体力は残り5%。\\nチームの盾役（敵の攻撃を引き受ける役）が倒れた。控えの盾役も体力半分。\\nお前は回復役。味方を復活させるのに3秒かかる。\\nその3秒で、控えの盾役も倒れるかもしれない。","en":"MMO raid. Eight-player party. Boss at 5% HP.\\nMain tank is down. Off-tank at half health.\\nYou\'re the healer. Resurrection takes 3 seconds.\\nIn those 3 seconds, the off-tank might fall too."},"options":[{"id":"a","text":{"ja":"盾役を復活させる。正攻法で行く。","en":"Resurrect the main tank. Do it by the book."},"scores":{"aggression":-15,"altruism":15,"cooperation":-15,"intuition":-15,"mastery":5}},{"id":"b","text":{"ja":"控えの盾役を全力回復。今いる人を生かす。","en":"Full heal the off-tank. Keep the living alive."},"scores":{"aggression":-10,"altruism":0,"cooperation":5,"intuition":0,"mastery":-5}},{"id":"c","text":{"ja":"攻撃魔法に切り替える。残り5%なら押し切れる。","en":"Switch to damage spells. At 5%, just burn it down."},"scores":{"aggression":0,"altruism":-10,"cooperation":-15,"intuition":15,"mastery":10}},{"id":"d","text":{"ja":"全体にバリアを張る。時間を稼ぐ。","en":"Cast a party-wide shield. Buy time for everyone."},"scores":{"aggression":-15,"altruism":5,"cooperation":15,"intuition":-10,"mastery":10}}]},{"id":"q017","tier":"free","category":"tactical","scenario":{"ja":"レースゲーム。最終ラップ。2位。\\n1位との差は0.8秒。普通に走れば追いつけない。\\nショートカットがある。ただしミスれば崖に落ちる。\\n3位は遥か後方。最低でも表彰台は確定している。","en":"Racing game. Final lap. Second place.\\n0.8 seconds behind first. Normal driving won\'t close the gap.\\nThere\'s a shortcut. Miss it and you fly off a cliff.\\nThird place is far behind. A podium finish is guaranteed."},"options":[{"id":"a","text":{"ja":"ショートカットを攻める。1位以外に意味はない。","en":"Take the shortcut. First or nothing."},"scores":{"aggression":15,"altruism":-5,"cooperation":-15,"intuition":5,"mastery":-5}},{"id":"b","text":{"ja":"2位を守る。確実なポイントを取る。","en":"Secure second. Take the guaranteed points."},"scores":{"aggression":-15,"altruism":15,"cooperation":15,"intuition":-5,"mastery":-5}},{"id":"c","text":{"ja":"コーナーで限界まで攻める。技術で0.8秒を縮める。","en":"Push every corner to the limit. Close 0.8 seconds with pure skill."},"scores":{"aggression":15,"altruism":5,"cooperation":-15,"intuition":-15,"mastery":10}},{"id":"d","text":{"ja":"1位の後ろにぴったりつく。最終コーナーで勝負する。","en":"Draft behind first. Make your move at the final corner."},"scores":{"aggression":10,"altruism":10,"cooperation":-10,"intuition":15,"mastery":-15}}]},{"id":"q019","tier":"free","category":"tactical","scenario":{"ja":"FPS。爆弾解除ミッション。残り15秒。\\n爆弾の前に敵が1人張り付いている。\\n味方は後ろから来ているが、間に合うか微妙。\\nフラッシュバンが1個残っている。","en":"FPS. Bomb defusal. 15 seconds left.\\nOne enemy is planted on the bomb.\\nYour teammate is rotating in, but might not make it.\\nYou have one flashbang left."},"options":[{"id":"a","text":{"ja":"フラッシュバンを投げて突入。一人で解決する。","en":"Flash and push. Handle it alone."},"scores":{"aggression":0,"altruism":-10,"cooperation":-10,"intuition":15,"mastery":15}},{"id":"b","text":{"ja":"味方を待つ。2人で挟む。","en":"Wait for backup. Pinch them from both sides."},"scores":{"aggression":-10,"altruism":15,"cooperation":5,"intuition":-15,"mastery":0}},{"id":"c","text":{"ja":"フェイクを入れる。敵に反応させてから撃つ。","en":"Fake a peek. Bait their reaction, then fire."},"scores":{"aggression":-5,"altruism":-10,"cooperation":5,"intuition":5,"mastery":-5}},{"id":"d","text":{"ja":"別角度から回り込む。予想外の方向から仕掛ける。","en":"Rotate to an unexpected angle. Hit them where they don\'t expect."},"scores":{"aggression":5,"altruism":5,"cooperation":0,"intuition":0,"mastery":0}}]},{"id":"q021","tier":"free","category":"tactical","scenario":{"ja":"サバイバルゲーム。3日目の夜。\\n拠点の壁が一部壊れている。敵の襲撃は今夜来る。\\n修理する資材はあるが、武器の弾薬製造にも使える。\\n両方に十分な量はない。","en":"Survival game. Night three.\\nPart of your base wall is broken. An enemy raid is coming tonight.\\nYou have materials to repair it—or to craft ammunition.\\nNot enough for both."},"options":[{"id":"a","text":{"ja":"弾薬を作る。攻撃が最大の防御。","en":"Craft ammo. Offense is the best defense."},"scores":{"aggression":15,"altruism":10,"cooperation":-15,"intuition":15,"mastery":0}},{"id":"b","text":{"ja":"壁を修理する。拠点を守ることが最優先。","en":"Repair the wall. Protecting the base comes first."},"scores":{"aggression":-15,"altruism":10,"cooperation":15,"intuition":-5,"mastery":10}},{"id":"c","text":{"ja":"壊れた壁をトラップに変える。侵入させて罠にかける。","en":"Turn the breach into a kill zone. Let them in—into a trap."},"scores":{"aggression":15,"altruism":-10,"cooperation":0,"intuition":10,"mastery":-5}},{"id":"d","text":{"ja":"拠点を捨てて移動する。執着しない。","en":"Abandon the base and relocate. Don\'t get attached."},"scores":{"aggression":-15,"altruism":-10,"cooperation":-15,"intuition":0,"mastery":-5}}]},{"id":"q022","tier":"free","category":"tactical","scenario":{"ja":"チーム戦。5対5の総力戦。\\nお前の必殺技は全体に大ダメージを与えるが、発動に2秒かかる。\\n味方の防御役が敵を引きつけている。でも持って3秒。\\n使うなら今しかない。でも最高のタイミングはまだ先かもしれない。","en":"MOBA. Full 5v5 teamfight.\\nYour ultimate deals massive AoE damage but takes 2 seconds to charge.\\nYour tank is holding the enemy. They\'ll last maybe 3 seconds.\\nUse it now, or wait for the perfect moment that may never come."},"options":[{"id":"a","text":{"ja":"今すぐ撃つ。迷ったら負ける。","en":"Fire now. Hesitation is defeat."},"scores":{"aggression":10,"altruism":-5,"cooperation":5,"intuition":-5,"mastery":-10}},{"id":"b","text":{"ja":"1秒だけ待つ。敵が固まった瞬間を狙う。","en":"Wait one second. Aim for the moment they cluster."},"scores":{"aggression":5,"altruism":5,"cooperation":0,"intuition":-5,"mastery":15}},{"id":"c","text":{"ja":"味方に「あいつを集中攻撃」と指示してから撃つ。","en":"Call the target first, then fire."},"scores":{"aggression":-10,"altruism":15,"cooperation":10,"intuition":5,"mastery":10}},{"id":"d","text":{"ja":"温存する。この集団戦は味方に任せて次に備える。","en":"Hold it. Let the team handle this one—save it for next."},"scores":{"aggression":-15,"altruism":-10,"cooperation":-5,"intuition":-10,"mastery":0}}]},{"id":"q024","tier":"free","category":"tactical","scenario":{"ja":"ダンジョンRPG。パーティで迷宮を探索中。\\n分かれ道。左は宝箱のマーク。右はボスの気配。\\nMPが半分しか残っていない。帰還アイテムは1個。\\n宝箱にはレアアイテムがあるかもしれない。","en":"Dungeon RPG. Exploring with your party.\\nA fork in the road. Left shows a treasure marker. Right feels like a boss.\\nMP at half. One return item remaining.\\nThe chest might hold something rare."},"options":[{"id":"a","text":{"ja":"ボスに直行。宝は後で取りに来る。","en":"Head for the boss. Come back for treasure later."},"scores":{"aggression":15,"altruism":-15,"cooperation":-10,"intuition":5,"mastery":15}},{"id":"b","text":{"ja":"宝箱を先に開ける。装備次第でボスが楽になる。","en":"Open the chest first. Better gear might make the boss easier."},"scores":{"aggression":-5,"altruism":10,"cooperation":5,"intuition":-15,"mastery":-15}},{"id":"c","text":{"ja":"一度帰還する。万全の状態で両方攻略する。","en":"Return to town. Clear both at full strength."},"scores":{"aggression":-15,"altruism":15,"cooperation":10,"intuition":-10,"mastery":0}},{"id":"d","text":{"ja":"パーティを2つに分ける。同時に攻略する。","en":"Split the party. Tackle both at once."},"scores":{"aggression":15,"altruism":-15,"cooperation":-5,"intuition":15,"mastery":-10}}]},{"id":"q025","tier":"free","category":"tactical","scenario":{"ja":"バトロワ。ストームが迫っている。\\n目の前に物資が大量に落ちている建物。\\nだが建物の中に敵がいるのは確実。\\nストームに飲まれるまで40秒。迂回すれば安全だが手ぶら。","en":"Battle royale. The storm is closing.\\nA building stuffed with loot sits ahead.\\nEnemies are definitely inside.\\n40 seconds before the storm swallows you. Detour is safe but you\'ll have nothing."},"options":[{"id":"a","text":{"ja":"突入する。物資も敵のキルも全部取る。","en":"Storm the building. Take the loot and the kills."},"scores":{"aggression":5,"altruism":0,"cooperation":0,"intuition":-10,"mastery":5}},{"id":"b","text":{"ja":"迂回する。装備は道中で拾う。","en":"Take the detour. Scavenge on the way."},"scores":{"aggression":-10,"altruism":5,"cooperation":0,"intuition":-10,"mastery":-15}},{"id":"c","text":{"ja":"建物の外から投げ物で炙り出す。","en":"Flush them out with grenades from outside."},"scores":{"aggression":15,"altruism":-5,"cooperation":15,"intuition":-5,"mastery":15}},{"id":"d","text":{"ja":"ストームのギリギリを走って、出てきた敵を狩る。","en":"Ride the storm edge and pick off anyone who flees."},"scores":{"aggression":-15,"altruism":-10,"cooperation":0,"intuition":15,"mastery":-5}}]},{"id":"q027","tier":"free","category":"social","scenario":{"ja":"ゲームコミュニティの幹部ミーティング。方針で意見が割れている。\\n攻略重視派と交流重視派。どちらも正しい。\\nお前は副リーダー。最終判断を求められている。\\nどちらを選んでも、誰かが不満を持つ。","en":"Guild officers\' meeting. The guild is split.\\nHardcore raiders vs. casual community builders. Both have a point.\\nYou\'re the vice guild master. The final call falls on you.\\nEither way, someone will be unhappy."},"options":[{"id":"a","text":{"ja":"攻略重視。結果がなければ人は離れる。","en":"Prioritize progression. Without results, people leave anyway."},"scores":{"aggression":10,"altruism":-15,"cooperation":-5,"intuition":-10,"mastery":15}},{"id":"b","text":{"ja":"交流重視。居心地のいい場所が長続きする。","en":"Prioritize community. A welcoming place lasts longer."},"scores":{"aggression":-15,"altruism":10,"cooperation":15,"intuition":5,"mastery":-15}},{"id":"c","text":{"ja":"両立させる仕組みを提案する。グループ分けする。","en":"Propose a system for both. Create separate groups."},"scores":{"aggression":0,"altruism":5,"cooperation":15,"intuition":-5,"mastery":15}},{"id":"d","text":{"ja":"投票にかける。みんなで決めるのが民主主義。","en":"Put it to a vote. Let democracy decide."},"scores":{"aggression":-5,"altruism":5,"cooperation":15,"intuition":0,"mastery":-15}}]},{"id":"q029","tier":"free","category":"social","scenario":{"ja":"配信をしていたら、視聴者が「そのプレイ下手すぎ」とコメントした。\\n同時視聴者は200人。みんなが反応を見ている。\\nコメントした相手はチャットの常連。\\n普段は応援してくれている人だ。","en":"You\'re streaming. A viewer comments: \\"That play was terrible.\\"\\n200 concurrent viewers. Everyone is watching your reaction.\\nThe commenter is a regular in your chat.\\nUsually, they\'re supportive."},"options":[{"id":"a","text":{"ja":"笑い飛ばす。「確かにひどかったw」","en":"Laugh it off. \\"Yeah, that was pretty bad lol.\\""},"scores":{"aggression":15,"altruism":10,"cooperation":15,"intuition":0,"mastery":-15}},{"id":"b","text":{"ja":"スルーする。いちいち反応しない。","en":"Ignore it. Don\'t give it attention."},"scores":{"aggression":10,"altruism":-5,"cooperation":-15,"intuition":10,"mastery":15}},{"id":"c","text":{"ja":"「じゃあ見せてみろ」と返す。","en":"Clap back: \\"Let\'s see you do better then.\\""},"scores":{"aggression":15,"altruism":-10,"cooperation":0,"intuition":-5,"mastery":-5}},{"id":"d","text":{"ja":"「何が悪かった？」と聞いて改善点を探る。","en":"Ask \\"What did I do wrong?\\" and look for improvement."},"scores":{"aggression":-15,"altruism":10,"cooperation":15,"intuition":-15,"mastery":10}}]},{"id":"q031","tier":"free","category":"social","scenario":{"ja":"リアルの友達が「ランク上げてほしい」と頼んできた。\\nお前のアカウントで代わりにプレイしてくれ、と。\\n友達は純粋に上のランクで遊びたいだけ。\\nだがブースティングは規約違反。バレたらアカウント停止される。","en":"A real-life friend asks you to boost their rank.\\n\\"Just play a few games on my account.\\"\\nThey just want to play at a higher level. No ill intent.\\nBut boosting violates TOS. If caught, both accounts get banned."},"options":[{"id":"a","text":{"ja":"断る。ルールはルール。","en":"Decline. Rules are rules."},"scores":{"aggression":-5,"altruism":0,"cooperation":-5,"intuition":-15,"mastery":15}},{"id":"b","text":{"ja":"一緒にプレイして教える。自力で上がれるようにする。","en":"Play together and coach them. Help them climb on their own."},"scores":{"aggression":-5,"altruism":15,"cooperation":0,"intuition":5,"mastery":-10}},{"id":"c","text":{"ja":"やってあげる。友達だから。","en":"Do it. That\'s what friends are for."},"scores":{"aggression":15,"altruism":5,"cooperation":15,"intuition":0,"mastery":-15}},{"id":"d","text":{"ja":"別アカウントを作って一緒にやる。グレーだけど楽しい。","en":"Make a smurf and play together. Gray area, but fun."},"scores":{"aggression":-10,"altruism":-15,"cooperation":10,"intuition":10,"mastery":-5}}]},{"id":"q035","tier":"free","category":"social","scenario":{"ja":"クランに加入希望者が来た。腕前は超一流。\\nだが前のクランで態度が悪くて追い出された噂がある。\\n今のクランは雰囲気がいい。実力不足は否めないが、仲がいい。\\nこいつが入れば大会で結果が出る。","en":"Someone wants to join your clan. Their skill level is elite.\\nBut rumor has it they were kicked from their last clan for toxicity.\\nYour current clan has great vibes. Not the strongest, but tight-knit.\\nWith this player, tournament results are guaranteed."},"options":[{"id":"a","text":{"ja":"入れる。実力が全て。雰囲気は後から作れる。","en":"Accept them. Skill is everything. Vibes can be fixed later."},"scores":{"aggression":0,"altruism":-10,"cooperation":-5,"intuition":-10,"mastery":5}},{"id":"b","text":{"ja":"断る。雰囲気を壊すリスクは取れない。","en":"Decline. Can\'t risk the team chemistry."},"scores":{"aggression":-10,"altruism":0,"cooperation":0,"intuition":10,"mastery":-10}},{"id":"c","text":{"ja":"試用期間を設ける。1ヶ月様子を見る。","en":"Set a trial period. One month to prove themselves."},"scores":{"aggression":10,"altruism":-10,"cooperation":5,"intuition":-5,"mastery":15}},{"id":"d","text":{"ja":"メンバー全員に聞く。俺一人じゃ決められない。","en":"Ask the whole team. This isn\'t my decision alone."},"scores":{"aggression":-5,"altruism":10,"cooperation":15,"intuition":-5,"mastery":-5}}]},{"id":"q036","tier":"free","category":"social","scenario":{"ja":"MMOで仲良くなった人がいる。毎日一緒に遊ぶ仲。\\nある日、その人が「リアルで会わない？」と言ってきた。\\n共通の話題も多い。きっと楽しい。\\nでもネット上の関係とリアルは別物かもしれない。","en":"You\'ve grown close to someone in an MMO. You play together every day.\\nOne day, they ask: \\"Want to meet up in real life?\\"\\nYou have tons in common. It\'d probably be great.\\nBut online friendships and real life might be different."},"options":[{"id":"a","text":{"ja":"会う。ネットもリアルも同じ人間。","en":"Meet up. Online or offline, they\'re the same person."},"scores":{"aggression":5,"altruism":15,"cooperation":5,"intuition":10,"mastery":-15}},{"id":"b","text":{"ja":"断る。ゲームの中だけの関係がちょうどいい。","en":"Decline. The game is where this friendship lives."},"scores":{"aggression":-10,"altruism":-5,"cooperation":-10,"intuition":10,"mastery":15}},{"id":"c","text":{"ja":"まずは通話から始めよう、と提案する。","en":"Suggest starting with a voice call first."},"scores":{"aggression":5,"altruism":15,"cooperation":10,"intuition":-10,"mastery":10}},{"id":"d","text":{"ja":"グループで会おう、と提案する。2人きりは気まずい。","en":"Suggest a group meetup. One-on-one might be awkward."},"scores":{"aggression":-15,"altruism":5,"cooperation":15,"intuition":5,"mastery":-10}}]},{"id":"q037","tier":"free","category":"social","scenario":{"ja":"オンラインゲームで、相手チームの1人が回線落ちした。\\n4対5になった。お前のチームが明らかに有利。\\nそのまま押し切れば楽勝。\\n抜けた人が戻ってくるかはわからない。","en":"Online match. One enemy disconnects.\\n4v5 now. Your team has a clear advantage.\\nPush through for an easy win.\\nNo telling if the disconnected player will return."},"options":[{"id":"a","text":{"ja":"容赦なく攻める。運も実力のうち。","en":"Push hard. Luck is part of the game."},"scores":{"aggression":15,"altruism":-10,"cooperation":5,"intuition":-5,"mastery":-10}},{"id":"b","text":{"ja":"少し待つ。戻ってくるかもしれない。","en":"Wait a bit. They might reconnect."},"scores":{"aggression":-10,"altruism":10,"cooperation":5,"intuition":5,"mastery":-15}},{"id":"c","text":{"ja":"普通にプレイする。特に手加減もしないし急がない。","en":"Play normally. No mercy, but no rush either."},"scores":{"aggression":-10,"altruism":-15,"cooperation":-10,"intuition":-10,"mastery":10}},{"id":"d","text":{"ja":"味方1人を待機させて4対4にする。フェアにやる。","en":"Bench one of your own. Make it 4v4. Play fair."},"scores":{"aggression":-15,"altruism":10,"cooperation":-5,"intuition":10,"mastery":-10}}]},{"id":"q038","tier":"free","category":"social","scenario":{"ja":"オンラインの友達がゲームの成績を自慢してきた。\\n「俺、ついに最高ランクに到達したわ」\\n正直、お前の方が長く、真剣にやっている。でもランクは相手の方が上。\\n素直に「すごい」と言えるか。それとも。","en":"Your online friend brags about their rank.\\n\\"I finally hit Predator.\\"\\nHonestly, you\'ve been grinding longer and harder. But their rank is higher.\\nCan you say \\"congrats\\" and mean it?"},"options":[{"id":"a","text":{"ja":"素直に祝う。仲間の成功は嬉しい。","en":"Genuinely congratulate them. A friend\'s success is your joy."},"scores":{"aggression":-10,"altruism":15,"cooperation":0,"intuition":-5,"mastery":-5}},{"id":"b","text":{"ja":"「次は俺が追い抜く」と宣言する。","en":"\\"I\'m catching up next.\\" Use it as fuel."},"scores":{"aggression":-10,"altruism":0,"cooperation":-5,"intuition":-5,"mastery":15}},{"id":"c","text":{"ja":"軽く流す。「へー、すごいね」","en":"Play it cool. \\"Oh nice, cool.\\""},"scores":{"aggression":-10,"altruism":-15,"cooperation":-10,"intuition":5,"mastery":-15}},{"id":"d","text":{"ja":"1対1を申し込む。ランクじゃなくて直接勝負。","en":"Challenge them to a 1v1. Rank doesn\'t mean everything."},"scores":{"aggression":15,"altruism":10,"cooperation":-15,"intuition":0,"mastery":0}}]},{"id":"q039","tier":"free","category":"meta","scenario":{"ja":"積みゲーが30本を超えた。\\n新作の予約が始まった。PVを見た。絶対面白い。\\nでも手をつけていないゲームの中にも名作がある。\\n時間は有限。お前の選択は。","en":"Your backlog is over 30 games.\\nA new title just opened for pre-order. The trailer looks incredible.\\nBut hidden in your backlog are masterpieces you haven\'t touched.\\nTime is finite. What\'s your call."},"options":[{"id":"a","text":{"ja":"予約する。最新の体験は今しかできない。","en":"Pre-order. The hype is part of the experience."},"scores":{"aggression":0,"altruism":-5,"cooperation":-5,"intuition":5,"mastery":-15}},{"id":"b","text":{"ja":"積みゲーを1本クリアしてからにする。","en":"Finish one from the backlog first."},"scores":{"aggression":5,"altruism":15,"cooperation":-10,"intuition":-15,"mastery":10}},{"id":"c","text":{"ja":"積みゲーリストを整理する。本当にやりたいものだけ残す。","en":"Organize the backlog. Keep only what you truly want."},"scores":{"aggression":5,"altruism":-5,"cooperation":5,"intuition":0,"mastery":5}},{"id":"d","text":{"ja":"両方やる。睡眠時間を削ればいい。","en":"Play both. Just sleep less."},"scores":{"aggression":10,"altruism":-10,"cooperation":0,"intuition":10,"mastery":-5}}]},{"id":"q040","tier":"free","category":"meta","scenario":{"ja":"新しいゲームを始める。難易度選択画面。\\n「ストーリーを楽しむ」「ノーマル」「ハード」「ナイトメア」\\n攻略情報はまだネットにほぼない。\\n初見プレイ。お前はどれを選ぶ。","en":"Starting a new game. Difficulty selection screen.\\n\\"Story Mode\\" / \\"Normal\\" / \\"Hard\\" / \\"Nightmare\\"\\nAlmost no guides exist online yet.\\nThis is your blind playthrough. What do you pick."},"options":[{"id":"a","text":{"ja":"ナイトメア。最初から最高難度。","en":"Nightmare. Highest difficulty from the start."},"scores":{"aggression":15,"altruism":15,"cooperation":-5,"intuition":0,"mastery":15}},{"id":"b","text":{"ja":"ノーマル。まずはゲームを理解する。","en":"Normal. Understand the game first."},"scores":{"aggression":-15,"altruism":0,"cooperation":0,"intuition":-10,"mastery":-5}},{"id":"c","text":{"ja":"ハード。やりごたえは欲しいが無謀はしない。","en":"Hard. I want challenge, not masochism."},"scores":{"aggression":5,"altruism":-5,"cooperation":0,"intuition":0,"mastery":10}},{"id":"d","text":{"ja":"ストーリーモード。物語を味わいたい。","en":"Story Mode. I\'m here for the narrative."},"scores":{"aggression":-15,"altruism":5,"cooperation":15,"intuition":15,"mastery":-10}}]},{"id":"q045","tier":"free","category":"meta","scenario":{"ja":"友達に「お前、何のゲーマー？」と聞かれた。\\n色々やっている。でも1つに絞れと言われたら。\\nFPS、RPG、格ゲー、MOBA、サバイバル。\\nお前のアイデンティティはどこにある。","en":"A friend asks: \\"What kind of gamer are you?\\"\\nYou play a lot of genres. But if you had to pick one.\\nFPS, RPG, Fighting, MOBA, Survival.\\nWhere does your identity lie."},"options":[{"id":"a","text":{"ja":"FPS。反射神経と判断力で勝つのが快感。","en":"FPS. Nothing beats winning with reflexes and decisions."},"scores":{"aggression":15,"altruism":-10,"cooperation":-10,"intuition":5,"mastery":0}},{"id":"b","text":{"ja":"RPG。物語の中に生きるのが好き。","en":"RPG. I love living inside a story."},"scores":{"aggression":-5,"altruism":15,"cooperation":0,"intuition":5,"mastery":-15}},{"id":"c","text":{"ja":"1つに絞れない。全ジャンルに俺がいる。","en":"Can\'t pick one. I exist in every genre."},"scores":{"aggression":10,"altruism":5,"cooperation":0,"intuition":10,"mastery":-15}},{"id":"d","text":{"ja":"対戦ゲーム全般。人と競いたい。","en":"Competitive games. I want to test myself against others."},"scores":{"aggression":10,"altruism":-5,"cooperation":-15,"intuition":10,"mastery":15}}]},{"id":"q046","tier":"free","category":"meta","scenario":{"ja":"基本無料ゲーム。ガチャが実装された。\\n推しキャラの限定スキンが出た。排出率0.5%。\\n天井まであと80連。約24,000円。\\nそのスキンはもう二度と復刻しないと公式が言っている。","en":"Free-to-play game. A gacha banner drops.\\nYour favorite character\'s limited skin is here. 0.5% drop rate.\\n80 pulls to pity. About $160.\\nThe developer says this skin will never return."},"options":[{"id":"a","text":{"ja":"天井まで回す。推しに金を惜しまない。","en":"Hit pity. Never skimp on your favorite."},"scores":{"aggression":5,"altruism":-10,"cooperation":-5,"intuition":15,"mastery":-10}},{"id":"b","text":{"ja":"無料石だけ使う。課金は絶対にしない。","en":"Use free currency only. Never spend real money."},"scores":{"aggression":-10,"altruism":5,"cooperation":-5,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"予算を決めて引く。5,000円まで。","en":"Set a budget. $30 max, then stop."},"scores":{"aggression":15,"altruism":10,"cooperation":0,"intuition":0,"mastery":10}},{"id":"d","text":{"ja":"ゲームをやめる。ガチャに金を使う仕組み自体が嫌い。","en":"Quit the game. The gacha system itself is the problem."},"scores":{"aggression":0,"altruism":10,"cooperation":-5,"intuition":0,"mastery":-5}}]},{"id":"q047","tier":"free","category":"meta","scenario":{"ja":"ゲームのエンディングが賛否両論だった。\\nお前は感動した。でもネットは「駄作」「期待外れ」の嵐。\\n自分の感想と世間の評価が真逆。\\nSNSでネタバレ込みの議論が始まっている。","en":"A game\'s ending divided the community.\\nYou were deeply moved. But the internet calls it \\"garbage\\" and \\"disappointing.\\"\\nYour feelings and public opinion are polar opposites.\\nSpoiler-filled debates are erupting on social media."},"options":[{"id":"a","text":{"ja":"自分の感想を書く。世間なんて関係ない。","en":"Post your take. The crowd doesn\'t define your experience."},"scores":{"aggression":-10,"altruism":0,"cooperation":-5,"intuition":15,"mastery":-10}},{"id":"b","text":{"ja":"議論に参加する。なぜ良かったか論理的に説明する。","en":"Join the debate. Explain logically why it worked."},"scores":{"aggression":0,"altruism":15,"cooperation":15,"intuition":-10,"mastery":5}},{"id":"c","text":{"ja":"何も言わない。自分の中で大事にする。","en":"Say nothing. Keep it precious in your heart."},"scores":{"aggression":-15,"altruism":5,"cooperation":-5,"intuition":5,"mastery":10}},{"id":"d","text":{"ja":"批判も読む。他の視点で見直すと発見があるかも。","en":"Read the criticism. A new perspective might reveal something."},"scores":{"aggression":-10,"altruism":-15,"cooperation":15,"intuition":-5,"mastery":5}}]},{"id":"q048","tier":"free","category":"meta","scenario":{"ja":"スピードランに挑戦している。世界記録に30秒届かない。\\n同じ区間を200回以上やり直した。\\n目をつぶってもルートが浮かぶ。手が勝手に動く。\\nでもあと30秒は、もう技術じゃなく運の領域かもしれない。","en":"You\'re attempting a speedrun. 30 seconds off the world record.\\nYou\'ve reset the same segment over 200 times.\\nYou can see the route with your eyes closed. Muscle memory handles the rest.\\nBut those last 30 seconds might be luck, not skill."},"options":[{"id":"a","text":{"ja":"続ける。200回やった。あと200回やれる。","en":"Keep going. 200 resets down, 200 more to go."},"scores":{"aggression":0,"altruism":5,"cooperation":-10,"intuition":5,"mastery":10}},{"id":"b","text":{"ja":"別のルートを開拓する。今のルートに限界がある。","en":"Pioneer a new route. The current one has hit its ceiling."},"scores":{"aggression":15,"altruism":5,"cooperation":0,"intuition":10,"mastery":5}},{"id":"c","text":{"ja":"自己ベストで満足する。世界記録にこだわりすぎない。","en":"Be satisfied with your personal best. Don\'t obsess over the WR."},"scores":{"aggression":-10,"altruism":0,"cooperation":-10,"intuition":-5,"mastery":-10}},{"id":"d","text":{"ja":"世界記録保持者の配信を研究する。差を分析する。","en":"Study the world record holder\'s stream. Analyze the gap."},"scores":{"aggression":-10,"altruism":-15,"cooperation":15,"intuition":-15,"mastery":10}}]},{"id":"q050","tier":"free","category":"meta","scenario":{"ja":"もしもう一度、全てのゲームを初見でプレイできるとしたら。\\n記憶を消して、もう一度あの衝撃を味わえる。\\nでもその代わり、今まで築いたスキルも全てリセットされる。\\n初心者に戻る。全てがゼロから。","en":"What if you could play every game again for the first time?\\nMemory wiped. Every twist, every reveal—brand new.\\nBut in exchange, all your skills reset to zero.\\nBack to being a complete beginner. Everything from scratch."},"options":[{"id":"a","text":{"ja":"記憶を消す。あの感動にはスキルでは届かない。","en":"Wipe it. No amount of skill matches that first-time feeling."},"scores":{"aggression":10,"altruism":5,"cooperation":15,"intuition":10,"mastery":-15}},{"id":"b","text":{"ja":"消さない。積み上げたものは俺そのもの。","en":"Keep it all. What I\'ve built is who I am."},"scores":{"aggression":-10,"altruism":-10,"cooperation":-10,"intuition":-10,"mastery":15}},{"id":"c","text":{"ja":"1本だけ選んで消す。全部じゃなくていい。","en":"Erase just one game. Not all—just the one."},"scores":{"aggression":10,"altruism":-5,"cooperation":5,"intuition":-15,"mastery":-5}},{"id":"d","text":{"ja":"消す必要はない。新しいゲームを探せばいい。","en":"No need to erase. There are always new games to discover."},"scores":{"aggression":0,"altruism":5,"cooperation":-5,"intuition":0,"mastery":-5}}]}]'))},78645,e=>{e.v(JSON.parse('[{"id":"HHHHH","name":{"ja":"覇王の咆哮","en":"Roar of the Conqueror"},"character":"クレイトス","characterGame":"God of War","characterUrl":"https://dic.nicovideo.jp/a/クレイトス","additionalCharacters":[{"name":"ザックス","game":"FF7 Crisis Core","description":{"ja":"ソルジャーとしての誇りを胸に、最後の一人になっても仲間のために戦い続けた英雄。直感と熱血と求道心が三位一体。その笑顔が戦場を変えた。","en":"A hero who kept fighting to the very last man, sword raised for his comrades with a SOLDIER\'s pride burning in his chest. Pure instinct, burning passion, and relentless self-improvement fused into one radiant smile."},"reasoning":{"ja":"仲間のために命を懸け（高利他）、クラウドを守るためSOLDIERと戦い（高攻撃・高チームプレイ）、直感でバトルに挑みながら一流を目指し鍛え続けた（高直感・高求道）。","en":"Zack lays down his life for Cloud and his friends (high altruism), charges into battle on pure instinct as part of SOLDIER\'s brotherhood (high intuition + high cooperation + high aggression), and pushes himself relentlessly toward the top rank (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ザックス・フェア"},{"name":"ゼシカ","game":"ドラゴンクエスト8","description":{"ja":"貴族令嬢の肩書きを捨て、兄の仇を討つために仲間と共に旅立つ魔法使い。派手で攻撃的なスタイルの中に、揺るぎない仲間愛と戦士の美学が宿る。","en":"A noble-born sorceress who abandoned her title to avenge her brother, fighting alongside companions with flamboyant, hard-hitting magic. Beneath the flashy exterior burns unwavering loyalty and a warrior\'s aesthetic."},"reasoning":{"ja":"感情先行の直感的な戦闘スタイル（高直感）、仲間のために自らを鍛え（高利他・高求道）、チームの連携を重視しながら（高チームプレイ）、迷わず前に出て攻撃を選ぶ（高攻撃）。","en":"Jessica fights with emotion-first magic on instinct (high intuition), constantly hones her craft for the sake of companions (high altruism + high mastery), operates as a core pillar of the party (high cooperation), and always steps forward aggressively (high aggression)."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストVIII"},{"name":"ワタル","game":"ポケモン金銀","description":{"ja":"最強のドラゴントレーナーにして、後進を育て導くチャンピオン。力の美学を追い求めながら、若い才能が自分を超えることを心から願う求道者。","en":"The strongest Dragon-type Trainer and a Champion who genuinely nurtures rivals to surpass him. He pursues the aesthetics of raw power while sincerely wishing the next generation will exceed him."},"reasoning":{"ja":"ドラゴンポケモンの力を極める求道精神（高求道）、後輩の成長を願う利他性（高利他）、直感でバトルスタイルを磨き（高直感）、チームとしてのポケモンバトルを体現し（高チームプレイ）、圧倒的な攻撃力（高攻撃）。","en":"His path toward ultimate Dragon mastery is his core drive (high mastery), he guides younger trainers toward their potential altruistically (high altruism), his instinctive Dragon battle style reflects high intuition (high intuition + high aggression), and he treats Pokémon battles as a cooperative art form (high cooperation)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_金・銀"},{"name":"アイリス","game":"ポケモンBW2","description":{"ja":"ドラゴン使いの少女からジムリーダー、そしてチャンピオンへと駆け上がった天才。直感と熱量でドラゴンたちと心をつなぎ、仲間と共に頂点を目指す。","en":"A prodigy who rose from Dragon-village girl to Gym Leader, then Champion through sheer intuition and passion. She bonds with her Dragons on a soul level and charges toward the summit with her companions."},"reasoning":{"ja":"ドラゴンポケモンとの直感的なつながりを力にし（高直感）、仲間のトレーナーを励ます利他性（高利他）、チャンピオンとしてチームを引っ張り（高チームプレイ）、ドラゴン使いの頂点を目指す求道心と攻撃性（高求道・高攻撃）。","en":"Iris draws power from her intuitive bond with Dragon Pokémon (high intuition), uplifts fellow trainers around her (high altruism), leads as a cooperative Champion (high cooperation), and relentlessly pursues Dragon mastery with aggressive battling (high mastery + high aggression)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_ブラック2・ホワイト2"},{"name":"ダンデ","game":"ポケモン剣盾","description":{"ja":"全力で戦うことを美学とし、挑戦者に最高の舞台を提供するチャンピオン。負けを認め、若い才能を全力で応援できる圧倒的な器。","en":"A Champion who treats every battle as a grand spectacle and gladly gives challengers the stage they deserve. He accepts defeat with grace and cheers on younger talents with his whole heart."},"reasoning":{"ja":"ダイマックスバトルへの全力投球（高攻撃）、主人公の成長を誰よりも喜ぶ利他性（高利他）、チームとしてのポケモンバトルへの信頼（高チームプレイ）、直感的なバトルスタイルとチャンピオンとしての求道心（高直感・高求道）。","en":"Leon gives his absolute all in every Dynamax battle (high aggression), celebrates the hero\'s growth more than anyone (high altruism), embodies cooperative Pokémon sport at its finest (high cooperation), and relentlessly perfects his craft through instinctive battling (high intuition + high mastery)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_ソード・シールド"},{"name":"ウルボザ","game":"ゼルダの伝説 BotW","description":{"ja":"ゲルドの女王にして神獣ヴァ・ナボリスの戦士。仲間のために雷を振るい、ゼルダを守ることに人生を捧げた。強さと優しさが共存する完璧な戦士。","en":"Queen of the Gerudo and pilot of Divine Beast Vah Naboris. She wields lightning for her companions and devoted her life to protecting Zelda — a perfect warrior in whom strength and tenderness coexist."},"reasoning":{"ja":"雷撃という攻撃的な力を仲間のために振るい（高攻撃・高利他）、ゼルダ姫の守護者として誓いを果たし（高チームプレイ）、ゲルドの戦士としての美学を磨き、直感の指揮官として戦場を制する（高求道・高直感）。","en":"Urbosa channels fearsome lightning for her allies (high aggression + high altruism), fulfills her oath as Zelda\'s sworn guardian within the Champions\' pact (high cooperation), and constantly refines the Gerudo warrior\'s art through instinctive battlefield command (high mastery + high intuition)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_ブレス_オブ_ザ_ワイルド"}],"description":{"ja":"全てにおいて全力。攻撃的でありながら仲間を守り、直感と美学に従って戦場を支配する。お前は戦いそのものに意味を見出す者だ。勝利は結果でしかない。その過程の熱量が、お前の人生そのものだ。","en":"All-out in everything. Aggressive yet protective, you dominate the battlefield through intuition and aesthetics. You find meaning in the fight itself. Victory is just a byproduct — the intensity of the process is your life."},"deepDescription":{"ja":"ニーチェの超人思想を体現する存在。既存の価値観を破壊し、自らの意志で新しい価値を創造する。","en":"You embody Nietzsche\'s Übermensch — destroying existing values and creating new ones through sheer will."},"recommendedGames":["God of War Ragnarok","Devil May Cry 5","FF7 Crisis Core"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"high","mastery":"high"},"characterDescription":{"ja":"神を殺し、息子を守り、戦場を支配する。怒りと愛と美学が一体化した北欧最強の父。どんな戦いにも全力で、仲間を守るためなら神ですら叩き潰す。","en":"A god-slayer who protects his son and dominates every battlefield. Rage, love, and warrior\'s pride fused into one. He gives everything in every fight and will crush gods themselves to protect those he cares for."},"characterReasoning":{"ja":"神話の神々を直感と本能で圧倒し（高直感）、アトレウスのためにすべてを捧げる（高利他）、息子と共に戦場を制する（高チームプレイ）、戦士としての美学を極め続ける（高求道・高攻撃）姿がこのタイプを完璧に体現する。","en":"Kratos defeats divine enemies through primal instinct (high intuition), sacrifices everything for Atreus (high altruism), fights as a unified front alongside his son (high cooperation), and relentlessly pursues the pinnacle of warrior craft with savage force (high mastery + high aggression)."}},{"id":"HHHHL","name":{"ja":"熱血の先導者","en":"The Blazing Vanguard"},"character":"ネロ","characterGame":"Devil May Cry 5","characterUrl":"https://ja.wikipedia.org/wiki/%E3%83%87%E3%83%93%E3%83%AB%E3%83%A1%E3%82%A4%E3%82%AF%E3%83%A9%E3%82%A44","additionalCharacters":[{"name":"ジタン","game":"FF9","description":{"ja":"軽口と笑顔で仲間を引っ張る天衣無縫の盗賊。自分が何者かより「今ここにいる人を助けること」が全て。孤独な出自を知っても、誰かのために手を伸ばすことをやめない。","en":"A carefree thief who leads with a grin and a quip. His identity crisis never stops him from reaching out to others — helping people is just what he does, no reason required."},"reasoning":{"ja":"「お前を一人にしない」と言いながら絶望の渦中でも仲間の手を引くジタンは、協調性と利他性の象徴。盗賊という即興職業が示すように、計画より感覚で動く低求道心の直感人間。","en":"Pulling his friends forward through despair with \'You don\'t need a reason to help someone\' is pure altruism and cooperation. As a thief who improvises everything, he embodies intuition over any crafted mastery."},"url":"https://dic.nicovideo.jp/a/%E3%82%B8%E3%82%BF%E3%83%B3%E3%83%BB%E3%83%88%E3%83%A9%E3%82%A4%E3%83%90%E3%83%AB"},{"name":"ティーダ","game":"FF10","description":{"ja":"ざっくばらんで感情的、でも誰よりもユウナの笑顔を守ろうとした青年。理屈よりも感情で突っ走り、その真っ直ぐさで世界の運命を変えた。","en":"Loud, emotional, and impulsive — but no one fought harder for Yuna\'s smile. He stumbled through a world he didn\'t understand and changed its fate through sheer force of feeling."},"reasoning":{"ja":"召喚士を死なせるシステムに「じゃあ変えればいい」と直感で反発し、泣きながら戦い続ける姿は攻撃性と利他性の暴走。ブリッツボール選手としての肉体反射頼みのスタイルが低い求道心を体現する。","en":"His gut-level rejection of \'Summoners must die\' — followed by screaming and charging — is raw aggression and altruism unfiltered by strategy. A blitzball player who runs on muscle memory, not mastery."},"url":"https://ja.wikipedia.org/wiki/%E3%83%86%E3%82%A3%E3%83%BC%E3%83%80_(%E3%83%95%E3%82%A1%E3%82%A4%E3%83%8A%E3%83%AB%E3%83%95%E3%82%A1%E3%83%B3%E3%82%BF%E3%82%B8%E3%83%BC)"},{"name":"春日一番","game":"龍が如く7","description":{"ja":"ドラゴンクエストをやりすぎた男が、現実でもヒーローになろうとした話。裏切られても信じ続け、ドブに落ちても仲間のために立ち上がる。バカで不器用で、だから最強。","en":"A man who played too much Dragon Quest and decided to live like the hero. Betrayed, homeless, and broken — he still gets up swinging for the people who need him."},"reasoning":{"ja":"18年服役した相手を庇う冒頭から、ラスボスに素手で挑む結末まで、一貫して感情と直感で動く。RPG愛好家ゆえの即興戦略（テーブルひっくり返して武器にする等）は計画ゼロの低求道心の戦法そのもの。","en":"From taking the fall for his boss at the start to charging the final boss on raw emotion, every decision is intuition-first. His improvised \'RPG combat\' — using street trash as weapons — is low mastery weaponized into a style."},"url":"https://ja.wikipedia.org/wiki/%E6%98%A5%E6%97%A5%E4%B8%80%E7%95%AA"},{"name":"ソラ","game":"Kingdom Hearts","description":{"ja":"「友達を取り戻す」ただそれだけで、何度でも立ち上がる少年。複雑な世界の理屈より、目の前の誰かを守る気持ちを優先する。その純粋さが世界を救う。","en":"A boy who fights across worlds for one reason: his friends. He doesn\'t understand the lore, the prophecies, or the politics — he just knows who he needs to protect."},"reasoning":{"ja":"「友達のためなら何でも」という動機が全行動の根幹で、利他性と協調性が突出している。闇の仕組みを理解せず感情だけでKeybladeを振る姿は、求道心より本能で戦う直感型の極点。","en":"His motivation never evolves beyond \'my friends\' — which is pure altruism and cooperation maxed out. He barely understands the Keyblade\'s mechanics and relies entirely on heart over skill, making him a textbook low-mastery intuition fighter."},"url":"https://ja.wikipedia.org/wiki/%E3%82%BD%E3%83%A9_(%E3%82%AD%E3%83%B3%E3%82%B0%E3%83%80%E3%83%A0_%E3%83%8F%E3%83%BC%E3%83%84)"},{"name":"ホムラ/ヒカリ","game":"ゼノブレイド2","description":{"ja":"世界を滅ぼす力を持ちながら、レックスと共に笑いながら戦うことを選んだ剣。自分の存在意義より、今隣にいる人との時間を大切にする。","en":"A living weapon capable of destroying the world who chose instead to fight alongside Rex — laughing the whole way. She values the person beside her over any grand cosmic purpose."},"reasoning":{"ja":"自らの消滅と引き換えにレックスを救う決断は、計算ではなく感情の爆発。ホムラとして「強くなりたい」と戦う姿は直感的な意志の強さであり、技術的洗練よりも絆への衝動が全てを上回る。","en":"Choosing to sacrifice herself for Rex without hesitation is emotion over calculation — maximum altruism. Her drive to grow stronger is pure instinct and will, with personal bonds consistently overriding any tactical refinement."},"url":"https://dic.nicovideo.jp/a/%E3%83%9B%E3%83%A0%E3%83%A9(%E3%82%BC%E3%83%8E%E3%83%96%E3%83%AC%E3%82%A4%E3%83%892)"},{"name":"キャプテン・ファルコン","game":"F-Zero","description":{"ja":"賞金稼ぎにして最速のレーサー。「Show me ya moves!」の一言に人生哲学が詰まっている。語らず、説明せず、ただ全力で突っ込む。","en":"Bounty hunter. Race champion. A man whose entire philosophy fits in four words: \'Show me ya moves.\' He doesn\'t explain — he just goes full throttle."},"reasoning":{"ja":"ブレーキなしで壁に突っ込む走りと、素手でブラックシャドウを粉砕するファルコンパンチは攻撃性の純粋結晶。操縦技術より「速さと気合」で勝負するスタイルが低求道心・高直感を完璧に示す。","en":"The Falcon Punch is a direct expression of aggression over technique — no setup, no strategy, just explosive force. His racing style prioritizes raw speed and instinct over any crafted skill, making him pure low-mastery intuition."},"url":"https://ja.wikipedia.org/wiki/%E3%82%AD%E3%83%A3%E3%83%97%E3%83%86%E3%83%B3%E3%83%BB%E3%83%95%E3%82%A1%E3%83%AB%E3%82%B3%E3%83%B3"},{"name":"ソニック","game":"ソニック・ザ・ヘッジホッグ","description":{"ja":"止まれないし、止まらない。困っている誰かがいれば、考える前に走り出している。シリアスになり切れない軽さが、逆に最大の強みになる。","en":"Can\'t stop, won\'t stop. If someone\'s in trouble, he\'s already running before the thought fully forms. His refusal to take anything too seriously is somehow his greatest strength."},"reasoning":{"ja":"エッグマンを誰より憎みながら、困っている誰でも助ける行動半径の広さは攻撃性と利他性の高速循環。「とりあえず走る」という思考ゼロの行動様式が低求道心・超高直感の象徴。","en":"Hating Eggman with maximum intensity while rescuing anyone in his path is aggression and altruism in constant high-speed rotation. His entire decision-making process is \'just run\' — zero planning, maximum instinct."},"url":"https://ja.wikipedia.org/wiki/%E3%82%BD%E3%83%8B%E3%83%83%E3%82%AF%E3%83%BB%E3%82%B6%E3%83%BB%E3%83%98%E3%83%83%E3%82%B8%E3%83%9B%E3%83%83%E3%82%B0"},{"name":"ユーリ・ローウェル","game":"テイルズ オブ ヴェスペリア","description":{"ja":"法が守れない民を守るため、法を超えた選択をした男。冷静に見えて、根っこは誰よりも感情的。その怒りは常に弱者への共感から生まれる。","en":"A man who took justice into his own hands when the law failed the powerless. He looks cool and collected, but underneath is someone who feels injustice more deeply than anyone."},"reasoning":{"ja":"民を見殺しにする貴族を独断で粛清する決断は、倫理より感情・直感が先行する証拠。「法より人」という行動原理は協調性と利他性のぶつかり合いで動いており、精緻な戦術より身体で覚えた剣技が低求道心を示す。","en":"Executing corrupt nobles without deliberation — trusting his gut over any legal or moral framework — is intuition and aggression fused. His \'people over systems\' principle is cooperation and altruism in direct conflict with mastery-driven thinking."},"url":"https://dic.nicovideo.jp/a/%E3%83%A6%E3%83%BC%E3%83%AA%E3%83%BB%E3%83%AD%E3%83%BC%E3%82%A6%E3%82%A7%E3%83%AB"},{"name":"トリッシュ","game":"Devil May Cry","description":{"ja":"悪魔として作られ、人間として生きることを選んだ女。感情を持たないはずの存在が、ダンテとの戦いの中で本物の絆を知る。クールな外見の奥に、驚くほど熱い芯がある。","en":"Created as a demon, chose to live as something more. She was built without feelings — and then Dante happened. Beneath the lightning and attitude is a core that burns hotter than she\'d ever admit."},"reasoning":{"ja":"ダンテを裏切る任務を与えられながら、最後には命がけで彼を守るトリッシュの転換は、計算でなく感情の爆発。戦闘スタイルが技巧より電撃の直撃頼みである点も、求道心より本能で戦う姿勢を示す。","en":"Betraying her mission to save Dante at the cost of her own life is emotion overriding every calculated directive — pure altruism igniting in a single moment. Her combat style favors raw lightning strikes over technical finesse, instinct over mastery."},"url":"https://dic.nicovideo.jp/a/%E3%83%88%E3%83%AA%E3%83%83%E3%82%B7%E3%83%A5(%E3%83%87%E3%83%93%E3%83%AB%E3%83%A1%E3%82%A4%E3%82%AF%E3%83%A9%E3%82%A4)"},{"name":"グズマ","game":"ポケモンSM","description":{"ja":"スカル団のボスとして弱者を集め、社会からはみ出した者たちの居場所を作った男。荒れた言動の裏に、誰かに認めてほしかった少年の叫びがある。","en":"Built Team Skull as a haven for outcasts and rejects — which says everything about him. The aggression and the bravado are armor; underneath is someone who just wanted to belong."},"reasoning":{"ja":"負け続けた者を拾い上げ組織を作る行動は、利他性と協調性の歪んだ発露。戦略よりパワーで押し切るバトルスタイルと、感情のまま動くリーダーシップが低求道心・高直感の典型。","en":"Building a gang of losers so they have somewhere to belong is altruism and cooperation expressed through chaos. His battle style is all brute force with no strategy, and his leadership runs entirely on raw feeling — classic low-mastery, high-intuition."},"url":"https://dic.nicovideo.jp/a/%E3%82%B0%E3%82%BA%E3%83%9E"},{"name":"ミドナ","game":"ゼルダの伝説 TP","description":{"ja":"最初は利用するつもりだったリンクのために、気づけば命を張っていた。クールを装った感情過多の女王。その孤独と怒りが、最終的に世界を救う力になった。","en":"She planned to use Link as a tool. Then she started risking her life for him. The most emotionally volatile character hiding behind the sharpest sarcasm in Zelda history."},"reasoning":{"ja":"ザントへの激しい憎悪と、リンクへの献身が共存するミドナは攻撃性と利他性の両極を体現する。一見冷静に見えるが行動は常に感情先行であり、策士より本能の女として低求道心・高直感の枠に収まる。","en":"Burning hatred for Zant and fierce devotion to Link existing simultaneously is aggression and altruism at their most intense. She appears calculating but always acts on feeling first — instinct-driven, not a tactician, placing her squarely in low-mastery, high-intuition."},"url":"https://dic.nicovideo.jp/a/%E3%83%9F%E3%83%89%E3%83%8A"}],"description":{"ja":"感情が爆発する。仲間のためなら腕一本失っても前に出る。直感で動き、考えるより先に体が動く。美学なんてどうでもいい、大切な人を守れればそれでいい。お前は不器用で真っ直ぐな、本物のヒーローだ。","en":"Emotions explode. You\'d lose an arm and still charge forward for your allies. Instinct drives you — your body moves before your mind. Forget aesthetics — protecting those you love is all that matters. You\'re a clumsy, honest, real hero."},"deepDescription":{"ja":"アリストテレスの友愛論。他者との絆こそが人間の本質。「今この瞬間」のために全力を出す、刹那的な利他主義。","en":"Aristotle\'s theory of philia — bonds with others define humanity. An impulsive altruism that gives everything for \'this very moment.\'"},"recommendedGames":["Devil May Cry 5","FF10","Kingdom Hearts III"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"high","mastery":"low"},"characterDescription":{"ja":"悪魔の血を引く若き剣士。粗削りな戦い方と口の悪さの裏に、仲間への揺るぎない献身がある。考えるより先に拳が出る、本能で生きる男。","en":"A rough-edged demon hunter with blood that burns hotter than hellfire. Behind the trash talk and reckless brawling is an unwavering loyalty to the people he loves. He doesn\'t think — he acts."},"characterReasoning":{"ja":"義手をもぎ取られても戦い続け、殺し合うダンテとバージルを止めるため単身乗り込む行動力は攻撃性と利他性の極致。技術より「ぶん殴れば何とかなる」の直感主義が低い求道心を示す。","en":"Charging solo into impossible odds to stop Dante and Vergil from killing each other — even after losing his arm — is peak aggression and altruism fused. His entire combat philosophy is \'hit it harder,\' which is intuition over mastery in its purest form."}},{"id":"HHHLH","name":{"ja":"孤高の策士","en":"The Lone Strategist"},"character":"ソリッド・スネーク","characterGame":"Metal Gear Solid","characterUrl":"https://ja.wikipedia.org/wiki/ソリッド・スネーク","additionalCharacters":[{"name":"マルティナ","game":"ドラゴンクエスト11","description":{"ja":"デルカダール王国の王女でありながら、幼少期に父と離散し16年間行方不明だった武闘家。華麗な蹴り技と冷静な知略で敵を翻弄し、仲間への深い愛情を行動で示す。感情を表に出さない凛とした強さの中に、揺るぎない絆への誓いが宿る。","en":"A martial artist princess of the Kingdom of Delcadar who was separated from her father as a child and went missing for sixteen years. She overwhelms enemies with elegant kicks and cold-blooded strategy, expressing her deep loyalty through action rather than words. Beneath her steely composure burns an unbreakable vow to her companions."},"reasoning":{"ja":"仲間と共に戦う強い協調性（高チームプレイ）、武道の極致を目指す求道心（高求道）、感情より経験と技術を重んじる計算された戦闘スタイル（低直感）、そして仲間のために自己を捧げる献身性（高利他）と攻撃性（高攻撃）を兼ね備える。","en":"She fights in lockstep with companions through thick and thin (high cooperation), pursues martial perfection as a core drive (high mastery), relies on technique and calculation over raw instinct (low intuition), and combines aggressive force with a fierce devotion to those she fights for (high aggression + high altruism)."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストXI"},{"name":"アイク","game":"FE蒼炎の軌跡","description":{"ja":"傭兵団グレイル傭兵団の若き隊長。貴族も平民も関係なく実力と誠実さで人を率い、仲間のためなら神すら斬ると言い切る男。言葉は少ないが、その背中が雄弁に語る不屈の魂。","en":"Young commander of the Greil Mercenaries who leads through merit and sincerity, indifferent to birth or rank. He\'ll cut down gods themselves for his comrades\' sake — a man of few words whose unyielding spirit speaks louder than any speech."},"reasoning":{"ja":"仲間のために迷わず剣を取る利他性と攻撃性（高利他・高攻撃）、傭兵団という組織の中で戦う強いチームプレイ精神（高チームプレイ）、師父グレイルの教えを超えるべく剣を磨く求道心（高求道）、感情より戦場の勘と経験を優先する冷静さ（低直感）。","en":"He draws his sword without hesitation for those he loves (high altruism + high aggression), operates as the backbone of an organized mercenary unit (high cooperation), relentlessly sharpens his blade to surpass even his father Greil (high mastery), and trusts battlefield experience over impulse (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ファイアーエムブレム_蒼炎の軌跡"}],"description":{"ja":"計算高く、仲間思いで、攻めるべき時に攻める。しかしその判断はデータと分析に基づく。美学を持ちながらも、冷徹な計算を手放さない。お前は戦場の知将だ。","en":"Calculated, caring, and aggressive when the moment demands it. But your decisions are data-driven. You hold aesthetics dear while never abandoning cold analysis. You are the battlefield\'s intellectual commander."},"deepDescription":{"ja":"孫子の兵法を体現する存在。「戦わずして勝つ」を理想としながらも、必要なら迷わず剣を取る。","en":"You embody Sun Tzu\'s Art of War — ideally winning without fighting, but never hesitating to draw the blade when necessary."},"recommendedGames":["Metal Gear Solid V","Hitman 3","FE蒼炎の軌跡"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"low","mastery":"high"},"characterDescription":{"ja":"感情より任務、本能より戦術。しかし仲間のためなら核戦争すら止める。計算された戦闘と冷静な判断が生み出す、孤独な英雄の美学。","en":"Mission over feelings, tactics over instinct. Yet he\'ll stop a nuclear war for his comrades\' sake. The aesthetics of a lonely hero forged from calculated combat and ice-cold judgment."},"characterReasoning":{"ja":"超人的な戦術思考と計算（低直感）、オタコンやメリルへの強い連帯感（高チームプレイ・高利他）、潜入技術と戦闘術の極限を追求し続ける（高求道）、敵への容赦ない攻撃性（高攻撃）が組み合わさる。","en":"Snake\'s legendary tactical genius marks him as deeply calculative (low intuition), his fierce loyalty to Otacon and Meryl drives cooperation and altruism (high cooperation + high altruism), his relentless pursuit of infiltration and combat mastery defines his craft (high mastery), and his no-hesitation aggression is unmistakable (high aggression)."}},{"id":"HHHLL","name":{"ja":"正義の鉄拳","en":"The Fist of Justice"},"character":"クリス・レッドフィールド","characterGame":"バイオハザード","characterUrl":"https://ja.wikipedia.org/wiki/クリス・レッドフィールド","additionalCharacters":[{"name":"春麗","game":"ストリートファイター","description":{"ja":"父の死の真相を追うインターポール捜査官にして世界最強の女格闘家。正義への信念と脚技の美しさを同時に体現する、ストリートファイター屈指の象徴的キャラクター。悪に対しては容赦がなく、仲間には温かい。","en":"An Interpol agent and the world\'s strongest female fighter, chasing the truth behind her father\'s death. She embodies both righteous conviction and the beauty of her signature kicking style — ruthless against evil, warm to those she protects."},"reasoning":{"ja":"正義のために戦う利他性と攻撃性（高利他・高攻撃）、インターポールという組織に属し法の秩序を守る高いチームプレイ精神（高チームプレイ）、結果よりプロセスを重んじる職人的鍛錬（高求道）、しかし行き当たりばったりな面もなく計画的に動く（低直感）。","en":"She fights with aggressive conviction for justice and the people she protects (high aggression + high altruism), operates within the structured framework of Interpol and cooperative law enforcement (high cooperation), hones her fighting craft with disciplined precision (high mastery), and acts on structured plans rather than gut impulse (low intuition)."},"url":"https://ja.wikipedia.org/wiki/春麗"},{"name":"勇者","game":"ドラゴンクエスト3","description":{"ja":"父オルテガの遺志を継ぎ、魔王バラモスを倒すべく旅立つ若き英雄。仲間と共に世界を救う王道の冒険者にして、アレフガルドの伝説「ロト」の起源となる存在。無言の主人公だが、その行動が全てを語る。","en":"A young hero who inherits his father Ortega\'s will and sets out to defeat the Archfiend Baramos. The archetypal adventurer who saves the world alongside companions — and the very origin of the legendary title \'Erdrick\'. His silence speaks volumes through his deeds."},"reasoning":{"ja":"魔王討伐という明確な使命への全力投球（高攻撃）、仲間のために世界を救う深い利他性（高利他）、パーティーとの連携を基本とする旅の構造（高チームプレイ）、しかし計画より役割に従って動く勇者らしい行動様式（低求道）と論理的な旅路（低直感）。","en":"Total commitment to the mission of defeating the Archfiend (high aggression), deep altruism in saving the world for humanity\'s sake (high altruism), a journey built entirely on party cooperation (high cooperation), but a hero who follows destiny\'s role rather than pursuing self-cultivation (low mastery) with a structured rather than improvisational approach (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストIII"},{"name":"ダルニア","game":"ゼルダの伝説 OoT","description":{"ja":"ゴロン族の族長にして、リンクを「兄弟」と呼ぶ熱血漢。族の者を守るためならどんな脅威にも立ち向かう男気あふれる指導者。炎竜ヴァルバジアの前でも怯まず、炎の力を全身で受け止める不屈のファイター。","en":"Chieftain of the Gorons who calls Link his brother. A hot-blooded leader who confronts any threat to protect his people without flinching — even before the inferno of Volvagia. He takes every hit full-force and never backs down."},"reasoning":{"ja":"族の者を守るための攻撃性と強い利他性（高攻撃・高利他）、ゴロン族という集団の長として仲間と共に戦う精神（高チームプレイ）、しかし武の道を極めるより仲間を守ることが目的で（低求道）、感情と直感より力で押す戦闘スタイル（低直感）。","en":"He charges forward aggressively to protect his tribe with fierce altruism (high aggression + high altruism), leads and fights as part of the Goron community (high cooperation), but his purpose is protecting his people rather than perfecting a craft (low mastery), with a straightforward power-over-finesse fighting style (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_時のオカリナ"},{"name":"ダルケル","game":"ゼルダの伝説 BotW","description":{"ja":"ゴロン族の英雄にして神獣ヴァ・ルーダニアの戦士。リンクを守るため盾となり、巨体に似合わぬ優しさで仲間思いの態度を見せる大岩の戦士。百年前の記憶の中でも、真っ先にリンクを庇い続けた。","en":"The Goron hero and Champion of Divine Beast Vah Rudania. He threw himself between Link and danger as a living shield — gentle warmth behind that colossal frame. Even in memories a century old, he was always the first to cover for Link."},"reasoning":{"ja":"仲間を守るために盾となる献身的な利他性と攻撃意欲（高利他・高攻撃）、勇者の盾としてチームを支えるプレイスタイル（高チームプレイ）、しかし武芸を磨くより「守る」ことに徹する実用的な姿勢（低求道）と感覚より体当たりの戦闘スタイル（低直感）。","en":"His defining trait is being a living shield — fierce altruism paired with protective aggression (high altruism + high aggression), he anchors the Champions as the party\'s defender (high cooperation), but he prioritizes protecting over perfecting any craft (low mastery) and fights through brute force rather than finesse (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_ブレス_オブ_ザ_ワイルド"}],"description":{"ja":"脅威は排除する。仲間は絶対に置いていかない。チームを率い、経験と判断力で最前線に立つ。美学や哲学は要らない。任務を完遂し、全員で生きて帰る。それだけだ。","en":"Threats are eliminated. No one gets left behind. You lead the team, standing on the front line with experience and judgment. No aesthetics, no philosophy needed. Complete the mission, everyone comes home alive. That\'s all."},"deepDescription":{"ja":"功利主義の体現者。「最大多数の最大幸福」を戦場に適用する。個人の犠牲も厭わない冷徹さと、誰も見捨てない矛盾を抱える。","en":"Utilitarian in action — applying \'the greatest good for the greatest number\' to the battlefield. Carrying the contradiction of cold pragmatism and refusing to abandon anyone."},"recommendedGames":["バイオハザード RE:4","Mass Effect","XCOM 2"],"axes":{"aggression":"high","altruism":"high","cooperation":"high","intuition":"low","mastery":"low"},"characterDescription":{"ja":"考えるより動く。でも必ず仲間のために。バイオテロに拳で立ち向かい続けるBSAAの鉄壁、人類の盾。","en":"Move first, think later — but always for his teammates. The BSAA\'s iron wall and humanity\'s shield, who punches through bioterrorism with bare fists."},"characterReasoning":{"ja":"岩をパンチで砕く直接的な行動力（高攻撃・低計算型）、パートナーを何度も救うチームプレイ（高チームプレイ・高利他）、武術の洗練より即座の結果を優先する（低求道）。","en":"Chris\'s famous boulder-punching directness exemplifies high aggression and non-analytical instinct (low intuition), his relentless rescue of Jill and others defines cooperation and altruism (high cooperation + high altruism), and his results-over-perfection approach marks him as pragmatic (low mastery)."}},{"id":"HHLHH","name":{"ja":"一匹狼の詩人","en":"The Poet Wolf"},"character":"V","characterGame":"Cyberpunk 2077","characterUrl":"https://ja.wikipedia.org/wiki/Cyberpunk_2077","additionalCharacters":[{"name":"ダンテ","game":"Devil May Cry","description":{"ja":"スタイリッシュに悪魔を狩り、飄々と世界を救う。孤独な使命感と美学の塊、半人半魔の最強猟師。","en":"He hunts demons in style and saves the world with a smirk. A half-demon hunter who is equal parts lonely mission and sheer aesthetic."},"reasoning":{"ja":"「スタイリッシュ」という概念そのものを体現し（高求道・高直感）、常に単独行動を好む（低チームプレイ）一方で困っている人間を放っておけない（高利他）、圧倒的な攻撃性を誇る（高攻撃）。","en":"Dante literally embodies the \'Stylish\' combat concept (high mastery + high intuition), consistently prefers to work alone (low cooperation), yet cannot leave humans in distress (high altruism), and dismembers demons with relentless, joyful aggression (high aggression)."},"url":"https://dic.nicovideo.jp/a/ダンテ(デビルメイクライ)"},{"name":"桐生一馬","game":"龍が如く","description":{"ja":"「堂島の龍」の異名を持つ元極道にして孤高の漢。誰にも頭を下げず、それでいて弱者のために拳を振るい続ける矛盾した不器用さが魅力。背負うものが増えるほど、孤独に強くなっていく。","en":"The \'Dragon of Dojima\' — a lone wolf ex-yakuza who bows to no one, yet cannot stop throwing his fists for the weak. His awkward contradiction of fierce independence and bottomless protectiveness is the whole point. The more he carries, the lonelier and stronger he becomes."},"reasoning":{"ja":"弱者のために戦う強い利他性と攻撃性（高利他・高攻撃）、組織ではなく個人として行動する徹底した孤独志向（低チームプレイ）、己の拳道を磨き続ける求道心（高求道）、そして場の空気と直感で状況を読む熱血の勘（高直感）。","en":"He fights ferociously for the powerless out of pure altruism (high altruism + high aggression), operates as a relentless lone wolf outside any organization (low cooperation), hones his fistfighting craft as a way of life (high mastery), and reads every situation through hot-blooded instinct (high intuition)."},"url":"https://ja.wikipedia.org/wiki/桐生一馬"},{"name":"真島吾朗","game":"龍が如く","description":{"ja":"「嶋野の狂犬」の異名通り、予測不能な狂気と天才的な戦闘センスで戦場を支配する男。桐生への歪んだ愛情を燃料に生き続け、誰にも理解されないまま自分の美学を貫く。孤高と狂気の間で踊り続ける蛇使い。","en":"The \'Mad Dog of Shimano\' — a man of unpredictable madness and genius combat instinct who bends any battlefield to his will. He runs on a twisted obsession with Kiryu, pursuing his own uncompromising aesthetic without needing anyone to understand. A snake-wielding dancer between solitude and insanity."},"reasoning":{"ja":"己の美学に従って戦い続ける強い攻撃性（高攻撃）と利他を超えた独自の愛情表現（高利他の歪み）、組織の論理より自分の衝動で動く孤独主義（低チームプレイ）、型を持たない即興の天才的戦闘センス（高直感）、そして狂気の中に宿る独自の「道」への執着（高求道）。","en":"He fights on pure aggressive aesthetic principle (high aggression), expresses a warped but genuine form of altruistic devotion toward Kiryu (high altruism), operates entirely outside organizational logic as a pure lone actor (low cooperation), battles through improvised genius instinct (high intuition), and pursues his own twisted path with fanatical mastery (high mastery)."},"url":"https://ja.wikipedia.org/wiki/真島吾朗"},{"name":"クー・フーリン","game":"Fate/stay night","description":{"ja":"アイルランドの大英雄にして不屈のランサー。必ず死ぬと分かっていても戦いを選ぶ、己の誇りと戦士の美学に殉じる男。「死ぬのは怖くないが、逃げるのは嫌だ」という一言に全てが詰まっている。","en":"The great Irish hero reborn as Lancer — a man who chooses battle even knowing he\'ll die, loyal to nothing but his warrior\'s pride and aesthetics. Everything about him is captured in one line: \'Dying doesn\'t scare me — but running does.\'"},"reasoning":{"ja":"誇りのために戦い続ける強烈な攻撃性（高攻撃）、仲間のためより己の美学のために命を張る利他性の裏返し（高利他の変形）、組織の命令より自分の戦士道で動く孤独な戦い（低チームプレイ）、本能と直感で戦場を制する天才的な反射（高直感）、ゲイ・ボルクという必殺の槍を極め抜いた武芸の道（高求道）。","en":"He fights with ferocious aggression driven purely by warrior\'s pride (high aggression), his altruism manifests as dying for a cause rather than following orders (high altruism variant), he fights alone by his own warrior code outside any master\'s true loyalty (low cooperation), dominates through primal battlefield instinct (high intuition), and has mastered his Gáe Bolg to absolute perfection (high mastery)."},"url":"https://ja.wikipedia.org/wiki/クー・フーリン"},{"name":"フータオ","game":"原神","description":{"ja":"璃月の葬儀社「往生堂」第77代堂主にして、死と生の狭間を自在に行き来する奇才。いたずらと笑いで周囲を振り回しながら、魂の案内人としての重大な使命を独力で果たす。その底知れない瞳の奥には、誰も見通せない深淵がある。","en":"The 77th Director of the Wangsheng Funeral Parlor in Liyue — a singular talent who strides freely between life and death. She yanks the world around with pranks and laughter while single-handedly fulfilling her solemn duty as a guide of souls. Behind those inscrutable eyes lies a depth no one can fathom."},"reasoning":{"ja":"炎を操る攻撃的な戦闘スタイル（高攻撃）と使命への深い献身（高利他）、組織の枠を飛び越えて一人で動く気質（低チームプレイ）、死霊術という独自の道を極める異才（高求道）、霊感と本能で幽冥を渡り歩く直感型人格（高直感）。","en":"Aggressive pyro combat style backed by deep devotion to her solemn duty (high aggression + high altruism), a personality that leaps beyond organizational structure to act alone (low cooperation), a singular genius perfecting the art of ghost-walking necromancy (high mastery), and an intuitive soul who navigates the world of the dead through pure instinct (high intuition)."},"url":"https://ja.wikipedia.org/wiki/原神"},{"name":"ルト姫","game":"ゼルダの伝説 OoT","description":{"ja":"ゾーラ族の姫にして、守護神ジャブジャブ様に飲み込まれたところをリンクに救われた少女。リンクへの恋心を一方的に燃やしながらも、族の者を守るために水の賢者として覚醒する。傲慢さと純粋さが同居する、嵐のような姫。","en":"Princess of the Zoras who was swallowed by the guardian deity Lord Jabu-Jabu and rescued by Link. She channels a one-sided fire for Link while awakening as the Sage of Water to protect her people. A storm of a princess — arrogance and purity existing in the same breath."},"reasoning":{"ja":"族を守るための攻撃的な決意と強い利他性（高攻撃・高利他）、組織の命令より自分の感情と衝動で動く個性（低チームプレイ）、求道心より感情と直感で行動する姫君（高直感）、そして恋と使命への一途な執着の中に宿る「道」（高求道）。","en":"She acts on fierce protective aggression and self-sacrifice for her tribe (high aggression + high altruism), moves entirely on personal emotion and impulse rather than any collective strategy (low cooperation), driven by instinct and passion over deliberate cultivation (high intuition), yet pursues her singular obsessions — love and duty — with relentless intensity (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_時のオカリナ"},{"name":"ルザミーネ","game":"ポケモンSM","description":{"ja":"エーテル財団の代表にして、ウルトラビーストへの病的な愛に溺れた母親。美しさと狂気が表裏一体で、子どもたちへの愛情すら自分の執着に塗り替えてしまった孤高の支配者。その純白の衣装の下には、誰も止められない闇が広がっている。","en":"President of the Aether Foundation and a mother consumed by a pathological love for Ultra Beasts. Beauty and madness are two sides of the same coin in her — even the love for her children is overwritten by her obsession. Beneath those pristine white robes spreads a darkness no one can stop."},"reasoning":{"ja":"ウルトラビーストのためなら全てを犠牲にする歪んだ利他性（高利他の暗面）と支配的な攻撃性（高攻撃）、誰にも従わず孤高に振る舞う徹底した個人主義（低チームプレイ）、美の頂点を追い求める孤独な求道心（高求道）、そして本能と直感で愛と執着の間を揺れ動く感情型人格（高直感）。","en":"Her warped altruism sacrifices everything — including her children — for Ultra Beasts she loves (high altruism, darkened), paired with domineering aggression (high aggression), complete refusal to answer to anyone as a solitary power (low cooperation), a solitary pursuit of beauty\'s pinnacle as her master\'s path (high mastery), and an instinct-driven personality oscillating wildly between love and obsession (high intuition)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_サン・ムーン"}],"description":{"ja":"攻撃的で仲間思い。だが群れることは嫌いだ。直感と美学に従い、自分だけの道を切り開く。お前の戦いには常に物語がある。ただ勝つだけでは満足できない。","en":"Aggressive and caring, but hating to run in packs. Following intuition and aesthetics, you carve your own path. Your battles always have a story. Winning alone doesn\'t satisfy you."},"deepDescription":{"ja":"カミュの異邦人的存在。社会に属しながらも本質的に孤独。自分だけの意味を探し続ける反逆者。","en":"Camus\' Stranger incarnate — belonging to society yet fundamentally alone. A rebel forever searching for personal meaning."},"recommendedGames":["Cyberpunk 2077","Devil May Cry 5","龍が如く0"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"high","mastery":"high"},"characterDescription":{"ja":"ナイトシティの夜に消えていく、孤独な傭兵。世界を変えようとしながら、誰かのために戦う矛盾を抱えた存在。直感と美学で死線を駆け抜ける。","en":"A lone mercenary dissolving into Night City\'s neon darkness. A contradictory existence fighting for others while trying to reshape the world. Racing through death\'s edge on instinct and aesthetic."},"characterReasoning":{"ja":"グループよりも単独行動を選ぶ（低チームプレイ）一方、ジョニーやパナムなど縁ある者を守るために戦い（高利他）、直感とスタイルで戦場を支配し（高直感・高攻撃）、傭兵としての極致を目指す（高求道）。","en":"V operates alone rather than as part of any group (low cooperation), fights for Johnny, Panam, and those they\'re bonded to (high altruism), dominates the battlefield through instinct and personal style (high intuition + high aggression), and pursues the mercenary\'s pinnacle (high mastery)."}},{"id":"HHLHL","name":{"ja":"戦場の傭兵","en":"The Battlefield Mercenary"},"character":"ビッグボス","characterGame":"Metal Gear Solid 3","characterUrl":"https://ja.wikipedia.org/wiki/ビッグ・ボス","additionalCharacters":[{"name":"マリオ","game":"スーパーマリオ","description":{"ja":"いつでもどこでも飛び込んでいく永遠の冒険者。ピーチ姫を救うためならどんな危険も笑顔で駆け抜ける、純粋無垢な正義の体現者。複雑な動機も哲学もなく、ただ「やる」という行動力がアイデンティティ。","en":"The eternal adventurer who dives in anytime, anywhere. He races through any danger with a grin to save Princess Peach — a pure, uncomplicated embodiment of doing good. No complex motives or philosophy, just an identity built entirely on action."},"reasoning":{"ja":"ピーチ救出という使命への強い攻撃性と利他性（高攻撃・高利他）、状況に応じてキノコ王国の仲間と協力する場面もあるが基本は単独行動（低チームプレイ）、その場の感覚でジャンプしてクリアする直感的な行動（高直感）、しかし計画性や技の鍛錬より「とにかくやる」精神（低求道）。","en":"Fierce altruistic aggression toward his mission of saving Peach (high aggression + high altruism), cooperative in moments but fundamentally a solo hero (low cooperation), navigates levels through immediate instinct and feel (high intuition), but acts on \'just do it\' energy rather than deliberate mastery-building (low mastery)."},"url":"https://ja.wikipedia.org/wiki/マリオ_(キャラクター)"},{"name":"A2","game":"NieR: Automata","description":{"ja":"YoRHaを離反した古参戦闘アンドロイド。仲間の死に対する怒りを燃料に生き、命令も組織も信じない孤高の剣。荒削りだが、その戦闘力と意志の強さは2Bをも凌駕する。孤独の中に宿る、誰にも負けない反骨の魂。","en":"A rogue YoRHa android from the old guard. She runs on rage at the deaths of those she lost, trusting no orders and no organization — a solitary blade. Raw and unrefined, yet her combat power and sheer will surpass even 2B. An unbreakable rebel spirit that burns brightest in solitude."},"reasoning":{"ja":"仲間の死への怒りを源泉とした激しい攻撃性（高攻撃）と失った仲間への深い利他的愛情（高利他）、YoRHaを離反し一切の組織に属さない孤独な戦い（低チームプレイ）、場の状況と本能で戦う直感的な戦闘スタイル（高直感）、しかし計画より怒りに任せた行動様式（低求道）。","en":"Explosive aggression fueled by grief and rage at fallen comrades (high aggression), with deep altruistic love for those she lost as her core drive (high altruism), a fully solitary fighter who severed all ties with YoRHa (low cooperation), battles on raw instinct and battlefield reads (high intuition), but acts from anger and the moment rather than deliberate mastery (low mastery)."},"url":"https://ja.wikipedia.org/wiki/NieR:Automata"},{"name":"ナボール","game":"ゼルダの伝説 OoT","description":{"ja":"ゲルド族のNo.2にして、ガノンドロフの悪行に反旗を翻した反骨の女盗賊。砂漠の掟と己の誇りだけを信じ、弱者から奪うガノンドロフに従うことを拒んだ。魂の神殿で単独行動を試みるも、ツインローバに捕らえられ洗脳される悲劇の戦士。","en":"The second-in-command of the Gerudo who rebelled against Ganondorf\'s atrocities. Trusting only the desert\'s law and her own pride, she refused to follow a leader who steals from women and children. She tried to act alone in the Spirit Temple but was captured and brainwashed by Twinrova — a tragic warrior of conviction."},"reasoning":{"ja":"ガノンドロフに反旗を翻す攻撃性と弱者を守る利他性（高攻撃・高利他）、外部の組織や権威に従わない独自路線（低チームプレイ）、状況を瞬時に読む直感的な判断力（高直感）、しかし武の道より「正しいことをする」実利主義（低求道）。","en":"Aggressive rebellion against Ganondorf with fierce altruism for the weak (high aggression + high altruism), operates entirely outside external authority (low cooperation), instinctive judgment that reads situations instantly (high intuition), but pragmatism — doing what\'s right — over any refined warrior\'s path (low mastery)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_時のオカリナ"},{"name":"ローズ委員長","game":"ポケモン剣盾","description":{"ja":"ガラル地方のエネルギー問題を解決するため、独断で世界を危機に晒したポケモンリーグ委員長。善意と傲慢が融合した末に暴走した理想主義者。ダンデへの強い期待を歪んだ形で表現し続けた孤独な男。","en":"The Pokémon League Chairman who unilaterally plunged the world into crisis to solve Galar\'s energy problem. An idealist whose good intentions and arrogance fused into runaway action. A lonely man who expressed his twisted expectations of Leon in increasingly warped ways."},"reasoning":{"ja":"ガラルの未来のための圧倒的な利他的動機（高利他）と独断行動の攻撃性（高攻撃）、誰とも合意せず一人で決断を下す孤独な指導者（低チームプレイ）、状況を直感的に読みながら行動に移す即断型（高直感）、しかし緻密な計画性より感情に流された決断が目立つ（低求道）。","en":"Overwhelmingly altruistic motivation to solve Galar\'s future (high altruism), aggressive unilateral action in service of that goal (high aggression), a solitary decision-maker who builds no consensus (low cooperation), quick instinct-to-action with decisive reads on situations (high intuition), but emotion-driven decisions that undercut long-term strategic mastery (low mastery)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_ソード・シールド"}],"description":{"ja":"直感で動き、仲間を大切にするが、組織には縛られない。結果を重視し、美学より効率を取る。自由を求めて戦い続ける。国も思想も関係ない。お前だけのルールがある。","en":"Intuition-driven, valuing allies but unbounded by organizations. Results over aesthetics, efficiency over beauty. Fighting for freedom. No nation, no ideology — only your own rules."},"deepDescription":{"ja":"実存主義そのもの。サルトルの「自由の刑」を背負い、選択の重さを知りながらも、常に自分の意志で動く。","en":"Existentialism personified — bearing Sartre\'s \'condemned to be free,\' knowing the weight of choice yet always acting by your own will."},"recommendedGames":["Metal Gear Solid: Peace Walker","NieR: Automata","スーパーマリオ オデッセイ"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"high","mastery":"low"},"characterDescription":{"ja":"美学より生存、哲学より結果。それでも戦場の弱者を見捨てない「最高の兵士」の孤独な旅。国家でも誰でもない、ただ自分の信念のために戦う。","en":"Survival over aesthetics, results over philosophy. Yet the \'Greatest Soldier\' who never abandons the weak on the battlefield. Fighting for no nation and no one — only his own conviction."},"characterReasoning":{"ja":"THE BOSSから受け継いだ単独行動の哲学（低チームプレイ）、サバイバルのための実利的な戦闘スタイル（低求道）、弱者や部下を守ろうとする使命感（高利他）、本能と直感で戦場を支配し（高直感・高攻撃）。","en":"Big Boss inherited The Boss\'s philosophy of solitary operation (low cooperation), his CQC and survival-first combat is result-oriented rather than art-focused (low mastery), his fierce protection of soldiers and the weak defines his altruism (high altruism), and his battlefield instincts are legendary (high intuition + high aggression)."}},{"id":"HHLLH","name":{"ja":"鍛冶師の魂","en":"The Blacksmith\'s Soul"},"character":"2B","characterGame":"NieR: Automata","characterUrl":"https://dic.nicovideo.jp/a/2b(ニーアオートマタ)","additionalCharacters":[{"name":"ライトニング","game":"FF13","description":{"ja":"感情を封印して戦い続ける元ガーディアンコープス兵士。妹セラを救うために世界と戦い、誰にも頼らずひとりで全てを背負おうとする。その鋼の意志と冷酷な合理性の下に、激しい愛情が埋もれている。","en":"A former Guardian Corps soldier who sealed away her emotions to keep fighting. She takes on the entire world to save her sister Serah, refusing to rely on anyone and bearing everything alone. Beneath the steel will and cold rationality, an intense love lies buried."},"reasoning":{"ja":"妹のために全てを犠牲にする強烈な利他性と攻撃性（高利他・高攻撃）、仲間を拒絶して一人で戦おうとする孤高の行動様式（低チームプレイ）、感情より論理と鍛錬で動く高い求道心（高求道）、そして直感より分析と技術を信頼する冷静さ（低直感）。","en":"Fierce altruism and aggression — everything sacrificed for her sister (high altruism + high aggression), a solitary drive to reject companionship and carry every burden alone (low cooperation), fueled by analytical discipline and relentless training rather than emotion (high mastery), trusting cold calculation over gut instinct (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ライトニング_(ファイナルファンタジー)"},{"name":"リク","game":"Kingdom Hearts","description":{"ja":"闇に堕ちながらも自力で這い上がり、ソラを守る盾となった元ライバル。誰にも頼らず自分の弱さと向き合い続けた成長の軌跡が、このシリーズ最大の人間ドラマを作る。傷だらけの魂が、最終的に最も強い光になる。","en":"The former rival who fell into darkness and clawed back to become Sora\'s shield. His arc of facing his own weakness alone — without leaning on anyone — forms the greatest human drama in the series. A soul scarred by darkness that ultimately becomes the strongest light."},"reasoning":{"ja":"ソラを守るための深い利他性と攻撃的な意志（高利他・高攻撃）、闇の力すら己に取り込んで独りで道を切り拓く孤独な成長（低チームプレイ）、暗黒の剣技を極め自分の力にする求道者の姿勢（高求道）、しかし直感より厳しい自己訓練と意志の力で動く（低直感）。","en":"Deep altruism and aggressive will to protect Sora at any cost (high altruism + high aggression), a solitary growth arc where he absorbs even the power of darkness on his own terms (low cooperation), a mastery-seeker who integrates dark powers into his own disciplined fighting style (high mastery), driven by rigorous self-training rather than instinct (low intuition)."},"url":"https://ja.wikipedia.org/wiki/リク_(キングダムハーツ)"},{"name":"シャドウ","game":"ソニック・ザ・ヘッジホッグ","description":{"ja":"究極の生命体にして、マリアへの誓いを胸に秘めた孤高の黒い男。ソニックを自分と同等に認める唯一の存在でありながら、決して同じ側には立たない。感情を殺した冷酷さの奥に、誰よりも深い愛と悲しみが宿っている。","en":"The Ultimate Life Form — a solitary black hedgehog who carries a silent vow to Maria. The one being who acknowledges Sonic as an equal, yet never stands on the same side. Behind his emotionless cold front lies a grief and love deeper than anyone else carries."},"reasoning":{"ja":"マリアのための誓いを胸にした深い利他性（高利他）と暗黒の力を振るう攻撃性（高攻撃）、いかなる組織にも属さず孤独に行動する（低チームプレイ）、己の力の極限を追求する究極生命体の求道心（高求道）、しかし感情より計算と力による行動を信頼する（低直感）。","en":"Profound altruism behind the silent vow to Maria (high altruism), devastating aggressive power wielding Chaos energy (high aggression), operates in absolute solitude outside any faction (low cooperation), the Ultimate Life Form\'s relentless pursuit of his own limits (high mastery), trusting calculated power over gut instinct (low intuition)."},"url":"https://ja.wikipedia.org/wiki/シャドウ・ザ・ヘッジホッグ"},{"name":"インパ","game":"ゼルダの伝説 OoT","description":{"ja":"シーカー族の末裔にして、ゼルダ姫の乳母であり護衛。ガノンドロフの陰謀からゼルダを逃がし、リンクにゼルダの伝言と子守歌を託した。闇の神殿の賢者として覚醒し、影から世界を守り続ける忠義の戦士。","en":"The last of the Sheikah, serving as Zelda\'s nursemaid and bodyguard. She spirited Zelda away from Ganondorf\'s conspiracy and entrusted Link with Zelda\'s message and lullaby. Awakening as the Shadow Sage, she continues to protect the world from the darkness — a warrior of unwavering loyalty."},"reasoning":{"ja":"ゼルダへの絶対的な忠誠と利他性（高利他）と使命を遂行するための攻撃的意志（高攻撃）、しかし影から単独で動くシーカー族の行動様式はチームプレイとは程遠い（低チームプレイ）、シーカー族の奥義を極め尽くした求道者（高求道）、感情より冷静な判断を信頼する（低直感）。","en":"Absolute loyalty and altruism toward Zelda (high altruism), with aggressive will to complete the sacred mission (high aggression), yet the Sheikah way of operating alone from the shadows is far from cooperative (low cooperation), a master of Sheikah arts perfected through lifelong training (high mastery), and trust in calm calculation over emotional impulse (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_時のオカリナ"},{"name":"インパ","game":"ゼルダの伝説 SS","description":{"ja":"時を超えてゼルダを守り続けた老シーカー族の賢者。何百年もの時間をかけてゼルダの覚醒を待ち続け、リンクに使命を告げる。その静かな強さと深い忍耐の中に、永遠の忠誠心が宿っている。","en":"The ancient Sheikah sage who guarded Zelda across centuries. She waited hundreds of years for Zelda\'s awakening, then entrusted the mission to Link with quiet certainty. In her still strength and boundless patience lives an eternal loyalty."},"reasoning":{"ja":"ゼルダへの永遠の忠誠という圧倒的な利他性（高利他）と使命を遂行するための攻撃的意志（高攻撃）、しかし時を超えた孤独な見守りはチームプレイとは程遠い（低チームプレイ）、シーカー族の奥義を極め尽くした求道者（高求道）、感情より長い時間軸での冷静な判断を信頼する（低直感）。","en":"Overwhelming altruism — an eternal loyalty to Zelda that spans centuries (high altruism), with aggressive will to complete the sacred mission (high aggression), yet her solitary vigil across time is the furthest thing from cooperative action (low cooperation), a master of Sheikah arts perfected over uncountable years (high mastery), and trust in long-horizon calm calculation over any emotional impulse (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_スカイウォードソード"}],"description":{"ja":"攻めて、守って、でも一人で全てをやりたい。計算高く、美学を何より重んじる。お前は完璧を目指す職人だ。チームに頼るより、自分の腕を磨くことを選ぶ。","en":"Attack, defend, but do it all alone. Calculated and aesthetics-first. You\'re a craftsman pursuing perfection. You\'d rather sharpen your own skills than rely on a team."},"deepDescription":{"ja":"ヘーゲルの自己意識論。自分の限界と向き合い続けることで、弁証法的に成長していく存在。","en":"Hegelian self-consciousness — growing dialectically through constant confrontation with your own limits."},"recommendedGames":["NieR: Automata","FF13","Kingdom Hearts III"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"low","mastery":"high"},"characterDescription":{"ja":"「感情は不要」と言いながら、誰より深く傷つき、誰より強く9Sを守る。孤独に技を極め、仲間のために最後の一撃を振るう完璧な戦闘アンドロイド。","en":"She says \'emotions are unnecessary,\' yet is wounded deeper than anyone and protects 9S more fiercely than any. A perfect combat android who hones her craft in solitude and delivers the final blow for those she cares for."},"characterReasoning":{"ja":"単独行動を基本とし他者と距離を置く（低チームプレイ）、感情を否定しながらも9Sのために命を賭ける（高利他）、剣技の鍛錬と戦闘美学の徹底（高求道）、計算された精密戦闘（低直感）、圧倒的な攻撃力（高攻撃）。","en":"2B operates alone by design, keeping others at emotional distance (low cooperation), yet risks everything for 9S\'s sake (high altruism), her combat training is systematic and calculated rather than instinctive (high mastery + low intuition), and her devastating precision offensive style is iconic (high aggression)."}},{"id":"HHLLL","name":{"ja":"合理の刃","en":"The Rational Blade"},"character":"ロックマン","characterGame":"ロックマン","characterUrl":"https://dic.nicovideo.jp/a/ロックマン(キャラクター)","additionalCharacters":[{"name":"ルカリオ","game":"ポケモン","description":{"ja":"波導を操る鋼の意志を持つアウラポケモン。感情ではなく波導という理で世界を読み、孤高の戦士として己の力を極め続ける。その静謐な強さは、訓練と意志の結晶だ。","en":"The Aura Pokémon — a being of steel will who reads the world through Aura rather than emotion. He stands apart as a solitary warrior who relentlessly perfects his power. His quiet strength is the crystallization of training and unbreakable will."},"reasoning":{"ja":"戦闘への強い攻撃性とトレーナーへの深い利他的な絆（高攻撃・高利他）、単独で行動し波導を極める孤高の姿勢（低チームプレイ）、波動の道を極め続ける求道心（高求道）、感情より波導という法則で行動する合理性（低直感）。","en":"Fierce combat aggression paired with deep altruistic bonds to his Trainer (high aggression + high altruism), a solitary warrior who masters Aura outside any group structure (low cooperation), relentless pursuit of the path of Aura as his life\'s mastery (high mastery), reasoning through Aura\'s logic rather than emotional instinct (low intuition)."},"url":"https://ja.wikipedia.org/wiki/ルカリオ"},{"name":"レディ","game":"Devil May Cry 3","description":{"ja":"父スパーダの力を求めるアーカムを追い、単身悪魔の世界に飛び込んだ人間のハンター。感情的な怒りを冷静な射撃技術に昇華し、悪魔狩りを職業にしてしまった。涙は流せなくても、その魂は誰よりも燃えている。","en":"A human hunter who stormed the demon world alone to chase Arkham and his lust for Sparda\'s power. She sublimates emotional fury into cold shooting precision and made demon hunting her trade. Even if she can\'t shed tears, her soul burns brighter than anyone\'s."},"reasoning":{"ja":"父への怒りを原動力とした強い攻撃性と復讐の利他性（高攻撃・高利他）、悪魔ハンターとしての技術を独力で磨く孤独な姿勢（低チームプレイ）、冷静な狙撃技術を極める求道心（高求道）、感情を殺して計算で動くが直感より分析を信頼する（低直感）。","en":"Intense aggression driven by paternal rage, with a form of altruism rooted in vengeance and stopping greater harm (high aggression + high altruism), a solitary hunter who forged her skills entirely alone (low cooperation), precise marksmanship mastery refined to a razor\'s edge (high mastery), and cold analytical calculation trusted over raw instinct (low intuition)."},"url":"https://ja.wikipedia.org/wiki/Devil_May_Cry_3"}],"description":{"ja":"正義のために戦い、一人で、冷静に、効率的に任務を遂行する。美学や哲学は不要だ。Dr.ライトの意志を継ぎ、ロボットマスターを一体ずつ撃破する。敵の武器をコピーして使う合理性。お前は感情を持つ機械であり、それゆえに誰よりも人間的だ。","en":"Fighting for justice, alone, calmly, efficiently executing the mission. No need for aesthetics or philosophy. Carrying Dr. Light\'s will, destroying Robot Masters one by one. The rationality of copying enemy weapons. You\'re a machine with emotions — and that makes you more human than anyone."},"deepDescription":{"ja":"オッカムの剃刀を人格化した存在。必要最小限の手段で最大の結果を出す。しかしその心には「平和」という、最もシンプルで最も達成困難な願いがある。","en":"Occam\'s Razor personified — maximum results with minimum means. Yet in that heart lies \'peace\' — the simplest and most impossible wish."},"recommendedGames":["ロックマン11","Mega Man X","Azure Striker Gunvolt"],"axes":{"aggression":"high","altruism":"high","cooperation":"low","intuition":"low","mastery":"low"},"characterDescription":{"ja":"Dr.ライトに作られた戦いを望まない戦士。しかし人類を守るため、最効率で敵ロボットを倒し続ける。合理性と正義の塊、青の小英雄。","en":"A warrior created by Dr. Light who never desired to fight. Yet he keeps defeating enemy robots with maximum efficiency to protect humanity. A compact hero of rationality and justice, clad in blue."},"characterReasoning":{"ja":"ボスの能力を吸収して弱点を計算的に突く（低直感・低求道の実利主義）、単独ミッションで完結する（低チームプレイ）、人類を守るという純粋な利他性（高利他）、ひたすら前進し続ける攻撃性（高攻撃）。","en":"Rock copies boss weapons to exploit calculated weaknesses — pragmatic efficiency over artistic expression (low intuition + low mastery), his solo missions are entirely self-contained (low cooperation), his drive to protect humanity is purely altruistic (high altruism), and his relentless forward progression shows aggression (high aggression)."}},{"id":"HLHHH","name":{"ja":"闘姫の誇り","en":"The Warrior Princess"},"character":"アリーナ","characterGame":"ドラゴンクエスト4","characterUrl":"https://dic.nicovideo.jp/a/アリーナ(ドラゴンクエスト)","additionalCharacters":[{"name":"フラダリ","game":"ポケモンXY","description":{"ja":"究極の美を追い求めるフレア団ボス。世界を「美しい少数」のためにリセットするという狂気の理想を持ち、自分の美学だけを絶対的な基準とする孤高の哲学者。その端整な容姿と冷たい眼差しに、終末の美学が滲み出ている。","en":"The leader of Team Flare who pursues ultimate beauty. He holds a mad ideal of resetting the world for the sake of \'the beautiful few\', treating his own aesthetic as the only absolute standard. His refined appearance and cold gaze are saturated with the aesthetics of extinction."},"reasoning":{"ja":"「少数の美しい者のための世界」という歪んだ利他性（高利他の暗面）と世界を破壊する圧倒的な攻撃性（高攻撃）、誰とも協力しない孤高の独裁者（低チームプレイ）、美の究極を追い求める極端な求道心（高求道）、そして自らの美学という直感的な基準だけで行動する感覚型哲学者（高直感）。","en":"A warped altruism that sacrifices the world for \'the beautiful few\' (high altruism, darkened), paired with apocalyptic aggression (high aggression), an absolute solitary dictator who cooperates with no one (low cooperation), extreme mastery-seeking toward the pinnacle of beauty (high mastery), and an intuitive philosopher who acts entirely on the instinct of his own aesthetic absolute (high intuition)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_X・Y"}],"description":{"ja":"自分の力を試したい。その一心で城を飛び出す。チームを引っ張り、直感で駆け抜け、武術の頂を目指す。利他じゃない。お前は自分の強さを証明したいだけだ。その純粋な渇望が、周りを巻き込む嵐になる。","en":"You want to test your own strength. That alone drives you to leap from the castle. Leading the team, charging by instinct, aiming for the martial peak. It\'s not altruism — you just want to prove your power. That pure hunger becomes a storm that sweeps everyone along."},"deepDescription":{"ja":"ニーチェの「力への意志」。表面上の利他は、より強くなるための手段。自己超越こそが真の目的。","en":"Nietzsche\'s \'Will to Power\' — apparent altruism is a means to become stronger. Self-transcendence is the true goal."},"recommendedGames":["ドラゴンクエスト4","Apex Legends","Warframe"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"high","mastery":"high"},"characterDescription":{"ja":"王女の身分を捨てて武術を極めた格闘王女。自分の強さへの誇りが原動力、でもチームの中で輝くことが彼女の喜び。最強の姫にして最高の仲間。","en":"A princess who abandoned royal standing to master martial arts. Pride in her own strength is her fuel, but she finds her greatest joy in shining within a team. The strongest princess and the finest companion."},"characterReasoning":{"ja":"自己の強さを極める求道心（高求道）、チームの前衛として輝く誇り（高チームプレイ）、仲間と共に勝つことを楽しむ（高直感）、「自分が最強でありたい」という自己中心的動機（低利他）、圧倒的な物理攻撃力（高攻撃）。","en":"Alena\'s relentless pursuit of martial perfection drives her mastery (high mastery), she shines brightest as the party\'s vanguard and takes pride in that role (high cooperation + high intuition), her primary motivation is proving her own strength rather than others\' welfare (low altruism), and her physical attack stats define her as the most aggressive party member (high aggression)."}},{"id":"HLHHL","name":{"ja":"嵐の略奪者","en":"The Storm Raider"},"character":"レイス","characterGame":"Apex Legends","characterUrl":"https://ja.wikipedia.org/wiki/%E3%82%A8%E3%83%BC%E3%83%9A%E3%83%83%E3%82%AF%E3%82%B9%E3%83%AC%E3%82%B8%E3%82%A7%E3%83%B3%E3%82%BA%E3%81%AE%E7%99%BB%E5%A0%B4%E3%82%AD%E3%83%A3%E3%83%A9%E3%82%AF%E3%82%BF%E3%83%BC","additionalCharacters":[{"name":"クッパ","game":"スーパーマリオ","description":{"ja":"魔王にして父親。ピーチ姫への一途な想いとクッパ王国の支配欲を両立させる、最強のラスボス。子煩悩な一面もあり、子供たちへの愛情は本物。戦略より力押し、計画より気合で進む王者の本能を持つ。","en":"A demon king and devoted father. He balances an earnest obsession with Princess Peach and the drive to rule the Koopa Kingdom — the ultimate final boss. Genuinely affectionate toward the Koopalings. A king who trusts brute force over strategy and gut energy over plans."},"reasoning":{"ja":"ピーチへの愛と配下への支配欲に根差した攻撃性（高攻撃）、仲間よりも自己利益と執着を優先する低い利他性（低利他）、子供たちとある程度協力するが基本的に自己中心（高チームプレイ）、本能と気合で即断する直感型の王（高直感）、しかし長期戦略より力任せの行動様式（低求道）。","en":"Aggression rooted in devotion to Peach and drive to rule (high aggression), self-interest and obsession dominate over genuine altruism (low altruism), some coordination with his Koopalings but fundamentally self-centered (high cooperation), a king of instant gut decisions and raw instinct (high intuition), but brute force over long-term strategic mastery (low mastery)."},"url":"https://ja.wikipedia.org/wiki/クッパ_(ゲームキャラクター)"}],"description":{"ja":"チームで戦い、直感で動くが、勝利だけが目的。美学もこだわりもない。ただ勝つ。お前にとってゲームは勝負であり、それ以上でもそれ以下でもない。","en":"Fight with the team, move by instinct, but victory is the only purpose. No aesthetics, no attachments. Just win. For you, the game is competition — nothing more, nothing less."},"deepDescription":{"ja":"ホッブスの自然状態。「万人の万人に対する戦い」を受け入れ、その中で生き残ることだけを考える。","en":"Hobbes\' state of nature — accepting the \'war of all against all\' and focusing solely on survival within it."},"recommendedGames":["Apex Legends","Fortnite","スーパーマリオブラザーズ"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"high","mastery":"low"},"characterDescription":{"ja":"次元の狭間を駆け抜ける孤高の戦士。仲間のために戦うふりをしながら、本当は自分の真実を追い求めている。直感で動き、チームを道具として使うカリスマ的略奪者。","en":"A lone warrior who tears through dimensional rifts. She fights alongside teammates, but her real purpose is hunting her own buried truth. A charismatic predator who moves on instinct and uses others as tools."},"characterReasoning":{"ja":"チームと行動しながら（高協調）、目的は完全に自己の記憶回復（低利他）。直感的な「声」に従い動く高直感型で、道を極めるより生き延びることを優先する低求道者。","en":"She operates with a squad (high cooperation) while her goals are entirely self-driven—recovering her lost memories (low altruism). She follows instinctive \'voices\' (high intuition) and prioritizes survival over mastery of any craft (low mastery)."}},{"id":"HLHLH","name":{"ja":"鋼鉄の参謀","en":"The Steel Tactician"},"character":"レオン・S・ケネディ","characterGame":"バイオハザード","characterUrl":"https://ja.wikipedia.org/wiki/%E3%83%AC%E3%82%AA%E3%83%B3%E3%83%BBS%E3%83%BB%E3%82%B1%E3%83%8D%E3%83%87%E3%82%A3","additionalCharacters":[{"name":"Dr.エッグマン","game":"ソニック・ザ・ヘッジホッグ","description":{"ja":"世界征服を夢見る天才科学者にして、自分の知性こそが世界を正しく導くと信じて疑わない独裁者。ロボット軍団と緻密な要塞を駆使し、何度倒されても再起する不屈の参謀。その野望は純粋なまでに揺るぎない。","en":"A genius scientist who dreams of world domination and genuinely believes his intellect is the rightful guide for all civilization. He deploys robot armies and elaborate fortresses, bouncing back from every defeat — a strategist whose ambition never wavers."},"reasoning":{"ja":"仲間を顧みない孤高の征服欲（低利他）、精密な作戦と組織運営（高チームプレイ＝自軍指揮）、感情より計算で動く（低直感）、技術的な完成を極める求道者（高求道）、そして誰よりも攻撃的に動く（高攻撃）。","en":"His conquest is purely self-serving (low altruism), he commands armies through meticulous planning rather than improvisation (high cooperation as a commander, low intuition), relentlessly perfects his technology (high mastery), and always strikes first and hardest (high aggression)."},"url":"https://ja.wikipedia.org/wiki/ドクター・エッグマン"},{"name":"リキッド・スネーク","game":"Metal Gear Solid","description":{"ja":"ビッグ・ボスの遺伝子を受け継ぎ、自らの運命への反逆を誓った傭兵の王。劣性遺伝子という呪縛を憎みながらも、FOXHOUNDを率いて核戦争すら手段に使う。知略と圧倒的なカリスマで部下を統率する生きた矛盾。","en":"A mercenary king who inherited Big Boss\'s genes and swore rebellion against his fate. He despises his \'inferior genes\' yet commands FOXHOUND with nuclear blackmail as a tool — a living contradiction of brilliant strategy and overwhelming charisma."},"reasoning":{"ja":"自分の野望のためだけに動く自己中心性（低利他）、FOXHOUNDを完璧に指揮する組織力（高チームプレイ）、本能より計算で動く（低直感）、戦術的な卓越を磨き続ける（高求道）、常に攻勢に出る攻撃性（高攻撃）。","en":"Driven entirely by his own destiny and ambition (low altruism), he commands FOXHOUND with calculated precision (high cooperation as leader), operates on strategy over instinct (low intuition), relentlessly hones tactical superiority (high mastery), and always takes the offensive (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%AA%E3%82%AD%E3%83%83%E3%83%89%E3%83%BB%E3%82%B9%E3%83%8D%E3%83%BC%E3%82%AF"}],"description":{"ja":"計算高く、チームで動き、攻撃的に前に出る。だが仲間への愛着より、自分のスキルへの誇りが行動原理だ。美学を持ちながら戦場を計算で支配する。","en":"Calculated, team-oriented, aggressively pushing forward. But pride in your own skills drives you more than attachment to allies. You dominate the battlefield through calculation while maintaining aesthetics."},"deepDescription":{"ja":"デカルトの方法的懐疑。全てを疑い、確かなもの（自分の実力）だけを信じる。「我思う、ゆえに我勝つ」。","en":"Cartesian methodical doubt — questioning everything, believing only in what\'s certain (your own ability). \'I think, therefore I win.\'"},"recommendedGames":["バイオハザード RE:4","The Division 2","Ghost Recon Breakpoint"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"low","mastery":"high"},"characterDescription":{"ja":"感情を殺し、ミッションを遂行する政府エージェント。ラクーンシティの地獄を生き抜いた経験が、感傷を許さない鋼の戦士を生んだ。チームを勝利に導くための冷静な計算が全て。","en":"A government agent who kills emotion to complete the mission. Surviving Raccoon City forged a steel warrior who cannot afford sentimentality. Cold calculation in service of getting the team out alive—that\'s everything."},"characterReasoning":{"ja":"仲間を護衛・指揮しながら（高協調）、生き残るための徹底した戦術計算（低直感）で戦う。アシュレーやエイダのために命を張るが（高攻撃）、それは任務であり利他心ではない（低利他）。バイオ訓練を極める求道者側面（高求道）も持つ。","en":"He commands and protects his squad (high cooperation) with meticulous tactical calculation rather than gut instinct (low intuition). He risks his life for Ashley and Ada (high aggression), but it\'s mission-driven, not selfless (low altruism). His relentless combat refinement marks him as a practitioner of mastery (high mastery)."}},{"id":"HLHLL","name":{"ja":"復讐の機械","en":"The Vengeance Engine"},"character":"9S","characterGame":"NieR: Automata","characterUrl":"https://dic.nicovideo.jp/a/9s","additionalCharacters":[{"name":"エーデルガルト","game":"FE風花雪月","description":{"ja":"幼少期に行われた凄惨な紋章実験の記憶を胸に、腐敗した貴族制度を打ち壊すために皇帝の座へ上り詰めた女傑。復讐と革命が彼女の燃料であり、手段を選ばぬ冷酷さと確固たる信念が同居する。","en":"A woman who clawed her way to the emperor\'s throne to dismantle a rotten nobility system — fueled by the trauma of brutal crest experiments in childhood. Ruthless pragmatism and unshakeable conviction coexist in her revolutionary fire."},"reasoning":{"ja":"他者を利用することも厭わない目的優先の姿（低利他）、孤独に革命を設計する非協調的な行動（低チームプレイ）、計算された戦略で動く（低直感）、復讐と革命の完成を極める意志（低求道→計画型）、何者にも屈しない攻撃的な先制（高攻撃）。","en":"She sacrifices others to achieve revolutionary ends (low altruism), engineers change alone outside of traditional alliances (low cooperation), acts on calculated strategy over instinct (low intuition), drives toward the singular perfection of her revolution (low mastery = plan-driven), and never backs down — always striking first (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%82%A8%E3%83%BC%E3%83%87%E3%83%AB%E3%82%AC%E3%83%AB%E3%83%88=%E3%83%95%E3%82%A9%E3%83%B3=%E3%83%95%E3%83%AC%E3%82%B9%E3%83%99%E3%83%AB%E3%82%B0"}],"description":{"ja":"普段は協力的で分析力に長けたスキャナー。だが大切なものを失った瞬間、お前は殺戮マシンに変わる。チームで動くが、その根底にあるのは自分だけの執着だ。美学なんてない。ただ、壊したい。","en":"Normally cooperative with sharp analytical skills. But the moment you lose what matters, you become a killing machine. You work with the team, but underneath lies a deeply personal obsession. No aesthetics. Just destruction."},"deepDescription":{"ja":"カントの義務論が崩壊した後の世界。義務に従っていた者が、喪失によって純粋な感情の奴隷になる悲劇。","en":"A world after Kantian duty collapses — the tragedy of one who followed duty becoming a slave to raw emotion after loss."},"recommendedGames":["NieR: Automata","The Last of Us Part II","FE風花雪月"],"axes":{"aggression":"high","altruism":"low","cooperation":"high","intuition":"low","mastery":"low"},"characterDescription":{"ja":"スキャナー型アンドロイドとして冷静に情報収集し、2Bとチームを組んで戦う。しかし2Bの死後、その計算された理性は崩壊し、純粋な復讐の機械へと変貌する。","en":"A Scanner-type android who coolly gathers intel and fights in tandem with 2B. But after 2B\'s death, his calculated rationality shatters—transforming into a pure machine of vengeance."},"characterReasoning":{"ja":"2Bとの連携行動（高協調）と、スキャナーとして情報を計算・分析する特性（低直感）が基盤。しかし復讐心が爆発すると、ヨルハへの献身より自己の痛みを優先し（低利他）、技を極めるより感情を爆発させる（低求道）方向に走る。","en":"Team coordination with 2B (high cooperation) and his Scanner designation\'s analytical, data-driven nature (low intuition) form his base. But when vengeance ignites, personal grief overrides loyalty to YoRHa (low altruism), and raw emotional explosion replaces disciplined mastery (low mastery)."}},{"id":"HLLHH","name":{"ja":"堕天の剣聖","en":"The Fallen Swordmaster"},"character":"セフィロス","characterGame":"Final Fantasy VII","characterUrl":"https://ja.wikipedia.org/wiki/%E3%82%BB%E3%83%95%E3%82%A3%E3%83%AD%E3%82%B9","additionalCharacters":[{"name":"テリー","game":"ドラゴンクエスト6","description":{"ja":"姉ミレーユを探す旅の果てに魔王軍の剣士となった孤高の剣客。誰にも頼らず、感情を封じ、己の剣だけで真実を切り開こうとする。その孤独な美学は剣の閃光のように鋭い。","en":"A lone swordsman who joined the demon lord\'s army while searching for his elder sister Milayou. He relies on no one, suppresses his emotions, and cuts through truth with his blade alone. His solitary aesthetic is as sharp as a blade\'s flash."},"reasoning":{"ja":"他者との協力を拒み孤独に戦う（低利他・低チームプレイ）、直感よりも独自の判断で動き（高直感＝直感的行動派）、誰にも属さない一匹狼（高攻撃）、剣の極みを追う求道者（高求道）。","en":"He refuses cooperation and fights in isolation (low altruism, low cooperation), moves on sharp personal instinct (high intuition), belongs to no faction as a lone wolf (high aggression), and relentlessly pursues the pinnacle of swordsmanship (high mastery)."},"url":"https://dic.nicovideo.jp/a/%E3%83%86%E3%83%AA%E3%83%BC(%E3%83%89%E3%83%A9%E3%82%B4%E3%83%B3%E3%82%AF%E3%82%A8%E3%82%B9%E3%83%886)"},{"name":"ロクサス","game":"Kingdom Hearts","description":{"ja":"ソラの「誰か」として生まれながら、自分が何者かを知らずに戦い続けたノーバディ。組織XIIIの中で静かに剣を磨き、感情の存在を否定される中でも自分の意志で行動を選び続けた。","en":"A Nobody born as Sora\'s \'someone,\' who kept fighting without ever knowing his own identity. He honed his Keyblades quietly within Organization XIII, and chose his own path even while being told he had no emotions to choose with."},"reasoning":{"ja":"組織への帰属より自分の感覚を優先（低チームプレイ）、誰かのためではなく自分の真実を求め（低利他）、直感で戦うキーブレード使い（高直感）、二刀流という極みを追う（高求道）、感情を閉ざした攻撃的な剣士（高攻撃）。","en":"He prioritizes his own sense of self over the Organization\'s goals (low cooperation), seeks his own truth rather than another\'s welfare (low altruism), fights with pure instinct dual-wielding Keyblades (high intuition), pursues dual-blade mastery relentlessly (high mastery), and is a cold, aggressive swordsman (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%AD%E3%82%AF%E3%82%B5%E3%82%B9"},{"name":"ファルコ","game":"スターフォックス","description":{"ja":"口は悪く自分勝手に見えるが、いざとなればスターフォックスのために命を張るパイロット。チームにいながら群れを嫌い、己のスタイルで空を制する。クールな反骨心の塊。","en":"Foul-mouthed and seemingly self-centered, yet when it counts, he puts his life on the line for Star Fox. He belongs to the team but despises being one of the pack — a pilot who owns the skies entirely on his own terms."},"reasoning":{"ja":"チームにいながらも協調を嫌う一匹狼気質（低チームプレイ）、自分本位な行動原理（低利他）、直感とセンスで空を飛ぶエース（高直感）、操縦技術の極みを追う（高求道）、先手を取って攻め続ける（高攻撃）。","en":"He bristles at cooperation despite being a teammate (low cooperation), operates on his own terms above others\' welfare (low altruism), aces combat on pure instinct (high intuition), endlessly refines his piloting craft (high mastery), and always hits first (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A1%E3%83%AB%E3%82%B3%E3%83%BB%E3%83%AD%E3%83%B3%E3%83%90%E3%83%AB%E3%83%87%E3%82%A3"},{"name":"エイダ・ウォン","game":"バイオハザード","description":{"ja":"特定の組織にも感情にも縛られない謎の女エージェント。どの陣営の命令にも従うようで、実は常に自分の論理で動いている。ウイルスも陰謀も、彼女の手の中では道具に過ぎない。","en":"A mysterious female agent bound by no organization and no emotion. She appears to follow every faction\'s orders, yet always operates on her own internal logic. Viruses and conspiracies alike are just tools in her hands."},"reasoning":{"ja":"誰にも尽くさない徹底した自律行動（低利他・低チームプレイ）、直感と状況判断で局面を切り抜ける（高直感）、スパイ技術の極みを体現（高求道）、積極的に危機に飛び込む攻撃性（高攻撃）。","en":"She serves no one but herself in all circumstances (low altruism, low cooperation), navigates crises through sharp situational instinct (high intuition), embodies the absolute pinnacle of espionage craft (high mastery), and aggressively throws herself into danger (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%A8%E3%82%A4%E3%83%80%E3%83%BB%E3%82%A6%E3%82%A9%E3%83%B3"},{"name":"ベヨネッタ","game":"ベヨネッタ","description":{"ja":"記憶を失いながらも天使を狩り続ける魔女。挑発的な笑みで戦場を舞台にし、神をも嘲笑うその美学は孤高の領域に達している。強さと色気と知性が融合した、唯一無二の存在。","en":"A witch who hunts angels even as she reclaims her lost memories. She turns every battlefield into a stage with a taunting smile, mocking gods themselves — her aesthetics of power and sensuality have reached a singular, untouchable domain."},"reasoning":{"ja":"誰の指図も受けず自分の美学で戦う（低チームプレイ・低利他）、感覚と身体の直感で戦闘を制する（高直感）、ウィッチタイム技術の完成を追い続ける（高求道）、神すら相手に先手を打つ圧倒的な攻撃性（高攻撃）。","en":"She fights entirely by her own aesthetic code, answering to no one (low cooperation, low altruism), dominates combat through embodied, physical intuition (high intuition), relentlessly refines Witch Time to perfection (high mastery), and takes the offensive against gods themselves (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%99%E3%83%A8%E3%83%8D%E3%83%83%E3%82%BF_(%E3%82%B2%E3%83%BC%E3%83%A0)"},{"name":"グリーン","game":"ポケモン赤緑","description":{"ja":"ライバルにして天才。常に主人公の一歩先を行き、チャンピオンの座を先に奪い取るほどの実力者。思いやりより結果を重視し、弱い絆より強い力を選んだ。","en":"A rival and a genius. Always one step ahead of the protagonist, talented enough to seize the Champion title first. He values results over compassion, and chooses raw strength over sentimental bonds."},"reasoning":{"ja":"仲間への温かみを持たず結果だけを追い求める（低利他）、単独で頂点を目指す一匹狼（低チームプレイ）、天才的な直感でバトルに挑む（高直感）、最強トレーナーへの求道（高求道）、常に先手を取るライバル心（高攻撃）。","en":"He shows no warmth toward others and pursues only results (low altruism), climbs to the top as a lone wolf (low cooperation), battles with brilliant innate instinct (high intuition), relentlessly pursues the title of strongest trainer (high mastery), and always strikes first with fierce rivalry (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%B0%E3%83%AA%E3%83%BC%E3%83%B3_(%E3%83%9D%E3%82%B1%E3%83%A2%E3%83%B3)"},{"name":"アオギリ","game":"ポケモンRSE","description":{"ja":"「海の拡大」という狂信的な野望のためにマグマ団と対立し、世界を海に沈めようとしたアクア団のリーダー。理念に殉じる姿は純粋な狂気であり、その目には他者への配慮は映らない。","en":"Leader of Team Aqua who clashed with Team Magma in a fanatical quest to expand the seas and submerge the world. His devotion to ideology reads as pure madness — other people simply don\'t register in his eyes."},"reasoning":{"ja":"世界のためと称しながら実は己の理念のみを追う（低利他）、共存より征服を選ぶ（低チームプレイ）、直感的な信念で突き進む（高直感）、カイオーガの力を極めようとする（高求道）、先制攻撃を厭わない過激な姿勢（高攻撃）。","en":"He claims to act for the world but serves only his own ideology (low altruism), chooses conquest over coexistence (low cooperation), charges forward on fervent, intuitive conviction (high intuition), seeks to harness Kyogre\'s ultimate power (high mastery), and takes radical preemptive action without hesitation (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%82%A2%E3%82%AA%E3%82%AE%E3%83%AA"},{"name":"ゲーチス","game":"ポケモンBW","description":{"ja":"ポケモン解放という崇高な理念を掲げながら、実は世界征服のために全てを操っていたプラズマ団の真の黒幕。息子Nすら道具として利用した冷酷な策謀家。","en":"The true mastermind of Team Plasma who wielded the noble banner of Pokémon liberation as cover for world domination. He used even his own son N as a tool — a cold schemer whose manipulation runs bone-deep."},"reasoning":{"ja":"息子すら道具に使う徹底した利己主義（低利他）、真の目的を共有しない欺瞞的行動（低チームプレイ）、直感より綿密な計算で動く計算型人格（低直感）、支配の完成を追い続ける（高求道）、世界征服という最大規模の攻撃性（高攻撃）。","en":"He treats his own son as a pawn — the apex of selfish manipulation (low altruism), never truly shares his goals with anyone (low cooperation), operates through meticulous calculation over instinct (low intuition), relentlessly pursues absolute dominion (high mastery), and wields the most sweeping aggressive ambition imaginable (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%B2%E3%83%BC%E3%83%81%E3%82%B9"},{"name":"ギラヒム","game":"ゼルダの伝説 SS","description":{"ja":"終焉の者の剣にして魔将軍。傲慢な美意識と残虐性を兼ね備え、主人公に対して個人的な執着と憎悪を燃やし続ける。舞うように戦うその姿は美しく、そして恐ろしい。","en":"The Demon Lord Demise\'s living sword and supreme commander. He combines arrogant aestheticism with pure cruelty, burning with personal obsession and hatred toward the hero. He dances through battle — beautiful and terrifying in equal measure."},"reasoning":{"ja":"他者を見下し自分の美学のみを崇拝（低利他）、誰とも真に連帯しない孤高（低チームプレイ）、感覚と直感で戦場を支配（高直感）、戦闘美学の極みを追い求める（高求道）、常に先手を取る圧倒的な攻撃性（高攻撃）。","en":"He scorns others and worships only his own aesthetic (low altruism), stands in haughty isolation forming no true alliances (low cooperation), commands the battlefield through pure sensory instinct (high intuition), relentlessly perfects his combat art (high mastery), and attacks with overwhelming dominance (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%AE%E3%83%A9%E3%83%92%E3%83%A0"},{"name":"オセロット","game":"Metal Gear Solid","description":{"ja":"どの陣営をも二重三重に欺き、自らの信念のためだけに生き続けた伝説のガンマン。ビッグ・ボスへの狂信的な忠義を核に、あらゆる陰謀を一人で編み上げた。その正体は永遠に謎めいている。","en":"A legendary gunfighter who double- and triple-crossed every faction he ever joined, living only for his own convictions. Fueled by fanatical loyalty to Big Boss, he wove every conspiracy alone — his true nature eternally enigmatic."},"reasoning":{"ja":"誰の味方でもなく自分の信念のみに従う（低利他）、連帯ではなく操作と欺瞞で動く（低チームプレイ）、直感と身体感覚で銃を極める（高直感）、回転式拳銃の技法を生涯磨き続ける（高求道）、陰謀という名の先手を常に打つ（高攻撃）。","en":"He follows only his own conviction, serving no faction truly (low altruism), operates through manipulation and deception rather than cooperation (low cooperation), hones his gunmanship through pure physical instinct (high intuition), spends his entire life perfecting revolver technique (high mastery), and always strikes first through preemptive conspiracy (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%AA%E3%83%B3%E3%83%88%E3%83%BB%E3%82%AA%E3%82%BB%E3%83%AD%E3%83%83%E3%83%88"}],"description":{"ja":"圧倒的な力で、孤独に、直感と美学で全てを蹂躙する。お前の動機は完全に自己中心的だ。孤独と怒りが原動力。だがその剣技には、誰も否定できない美がある。破壊こそがお前の芸術だ。","en":"With overwhelming power, alone, by intuition and aesthetics, you crush everything. Your motivation is entirely self-centered. Solitude and rage are your fuel. But your swordplay holds undeniable beauty. Destruction is your art."},"deepDescription":{"ja":"ディオニュソス的衝動。アポロン的理性を捨て、生命の狂騒に身を委ねる。破壊の中に創造を見出す。","en":"Dionysian impulse — abandoning Apollonian reason, surrendering to life\'s frenzy. Finding creation within destruction."},"recommendedGames":["FF7 Rebirth","Kingdom Hearts III","ベヨネッタ3"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"high","mastery":"high"},"characterDescription":{"ja":"かつてソルジャー最高位として君臨した完璧な剣士が、真実を知り「神」へと変貌した。一人で星を滅ぼすことを選ぶ孤高の美学。仲間も組織も、全ては過去の幻に過ぎない。","en":"Once the supreme SOLDIER, a perfect swordsman who discovered the truth and became something closer to a god. He chose to destroy the Planet alone. All companions, all organizations—mere ghosts of a past self."},"characterReasoning":{"ja":"「片翼の天使」として一人で星と戦う絶対的孤独（低協調）を体現し、直感的な「星の声」に従って動く（高直感）。神羅や人類への奉仕を完全に捨てた（低利他）が、剣の極致・魔法の完全習得という道を極める美学（高求道）を持つ。","en":"He embodies absolute solitude—fighting the entire Planet alone as the \'One-Winged Angel\' (low cooperation), guided by intuitive cosmic communion (high intuition). He utterly abandoned service to ShinRa or humanity (low altruism), yet maintains an aesthetic of perfected swordsmanship and complete magical mastery (high mastery)."}},{"id":"HLLHL","name":{"ja":"荒野のハイエナ","en":"The Desert Hyena"},"character":"トレバー","characterGame":"GTA V","characterUrl":"https://ja.wikipedia.org/wiki/%E3%83%88%E3%83%AC%E3%83%90%E3%83%BC%E3%83%BB%E3%83%95%E3%82%A3%E3%83%AA%E3%83%83%E3%83%97%E3%82%B9","additionalCharacters":[{"name":"ジェット","game":"Valorant","description":{"ja":"韓国出身の高速デュエリスト。風を操り誰よりも速く動き、己の直感と攻撃本能で戦場を切り裂く。誰かのためではなく、自分のスタイルを貫くために戦う孤高の刃。","en":"A high-speed Duelist from Korea who controls the wind and moves faster than anyone. She cuts through battlefields on pure instinct and attack impulse — fighting not for others, but to embody her own style as a solitary blade."},"reasoning":{"ja":"自分のプレイスタイルを最優先し仲間との連携より個人技（低チームプレイ・低利他）、感覚と反射で動くデュエリスト（高直感）、勝利より成長より今の瞬間を楽しむ（低求道）、誰よりも積極的に前線へ（高攻撃）。","en":"She prioritizes personal style over team synergy and fights for herself (low cooperation, low altruism), moves as a Duelist on pure reflex and instinct (high intuition), chases the thrill of the moment over structured growth (low mastery), and charges into the frontline more aggressively than anyone (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%82%B8%E3%82%A7%E3%83%83%E3%83%88(VALORANT)"},{"name":"オクタン","game":"Apex Legends","description":{"ja":"スリルと速度のためなら自分の足を吹き飛ばすことも厭わないサイボーグ兵士。勝利より「楽しいかどうか」が行動基準で、仲間も観客も自分のショーの脇役に過ぎない。","en":"A cyborg soldier who blew off his own legs just for the thrill and speed. His decision criterion is \'is this fun?\' rather than winning — teammates and audiences alike are just supporting cast in his personal show."},"reasoning":{"ja":"スリルのためなら仲間を危険にさらすことも（低利他・低チームプレイ）、直感と衝動で動く最前線のランナー（高直感）、技術を磨くより速さを楽しむ（低求道）、誰よりも先に突っ込む攻撃衝動（高攻撃）。","en":"He endangers teammates in pursuit of thrills (low altruism, low cooperation), charges the frontline on pure impulse and instinct (high intuition), chases speed for fun rather than disciplined skill growth (low mastery), and has the most aggressive forward charge of any legend (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%82%AA%E3%82%AF%E3%82%BF%E3%83%B3(Apex%20Legends)"},{"name":"ウルフ","game":"スターフォックス","description":{"ja":"スターフォックスの宿敵にして、等しく強い者だけを認めるスターウルフのリーダー。コーネリアへの義理もチームへの馴れ合いも捨て、ただ強さと戦いを求めて宇宙を飛ぶ。","en":"Star Fox\'s greatest rival and leader of Star Wolf — he only acknowledges those who match his strength. He\'s discarded all loyalty to Corneria and all camaraderie, soaring through space in pure pursuit of strength and battle."},"reasoning":{"ja":"強者のみを認め弱者を切り捨てる（低利他）、チームの論理より自分の流儀（低チームプレイ）、戦場の直感と反射で動くエースパイロット（高直感）、求道ではなく瞬間の戦いに生きる（低求道）、常に真正面から攻め続ける（高攻撃）。","en":"He only recognizes the strong and discards the weak (low altruism), operates by his own code over team loyalty (low cooperation), is an ace pilot driven by battlefield instinct and reflex (high intuition), lives for the moment\'s fight rather than long mastery (low mastery), and always charges head-on (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%A6%E3%83%AB%E3%83%95%E3%83%BB%E3%82%AA%E3%83%96%E3%83%8F%E3%82%A4%E3%82%A4%E3%83%A4%E3%83%BC"},{"name":"ククール","game":"ドラゴンクエスト8","description":{"ja":"修道院育ちでありながら信仰より自由を選び、女性への軽口と自由奔放な態度で旅を楽しむ放蕩者。でも仲間が追い詰められた時だけは本気を出す、底知れない実力者。","en":"Raised in an abbey yet choosing freedom over faith, sailing through his travels with a flirtatious mouth and free-spirited attitude. He saves his real power for when companions are cornered — a man of deeper ability than he ever lets on."},"reasoning":{"ja":"自分の楽しみを最優先し仲間のためには動きにくい（低利他）、修道院の規律に反発する自由人（低チームプレイ）、感覚と気分で戦う（高直感）、技術を真剣に磨かない享楽主義（低求道）、いざとなれば真っ先に動く攻撃本能（高攻撃）。","en":"He prioritizes his own enjoyment over companions\' welfare (low altruism), rebels against the abbey\'s discipline as a free spirit (low cooperation), fights on feeling and instinct (high intuition), approaches mastery with hedonistic half-commitment (low mastery), and when it counts, attacks with instinctive boldness (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%82%AF%E3%82%AF%E3%83%BC%E3%83%AB"},{"name":"りゅうおう","game":"ドラゴンクエスト1","description":{"ja":"世界征服を目論む竜王にして、勇者に「世界の半分をやる」と交渉を持ちかける傲慢な魔王。シンプルな支配欲と圧倒的な力の体現者。一対一の対決を求める古典的な悪の王。","en":"The Dragon Lord who schemes for world domination and arrogantly offers the hero \'half the world\' as a bargaining chip. A pure embodiment of domination instinct and overwhelming power — a classical evil king who seeks one-on-one confrontation."},"reasoning":{"ja":"他者への配慮ゼロの純粋な支配欲（低利他）、臣下を使うが真に連帯はしない（低チームプレイ）、衝動的な直感型の魔王（高直感）、技を磨くより本能の力（低求道）、世界征服という最大の攻撃性（高攻撃）。","en":"Pure domination with zero regard for others (low altruism), uses minions but forms no true alliance (low cooperation), acts on the instinctive impulse of a primordial evil (high intuition), relies on raw power over disciplined craft (low mastery), and pursues world conquest as the ultimate aggressive act (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E7%AB%9C%E7%8E%8B_(%E3%83%89%E3%83%A9%E3%82%B4%E3%83%B3%E3%82%AF%E3%82%A8%E3%82%B9%E3%83%88)"},{"name":"シドー","game":"ドラゴンクエスト2","description":{"ja":"破壊そのものを体現する邪神。言葉も意図も持たず、ただ世界を滅ぼすために存在する究極の悪。その圧倒的な存在感はシリーズ史上最も純粋な「破壊衝動」の結晶だ。","en":"A dark god who embodies destruction itself. He has no words, no intention — he simply exists to annihilate the world. His overwhelming presence is the purest crystallization of \'destructive impulse\' in the entire series."},"reasoning":{"ja":"他者への配慮など存在しない破壊の化身（低利他）、誰とも連帯せず単独で破滅をもたらす（低チームプレイ）、衝動のみで動く直感的な存在（高直感）、技術ではなく本能的な力の体現（低求道）、世界規模の攻撃性（高攻撃）。","en":"He is annihilation incarnate with zero consideration for any other existence (low altruism), brings destruction alone without any alliance (low cooperation), acts on pure destructive impulse with no strategic overlay (high intuition), embodies raw primal force over any craft (low mastery), and represents aggression at a world-ending scale (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%B7%E3%83%89%E3%83%BC_(%E3%83%89%E3%83%A9%E3%82%B4%E3%83%B3%E3%82%AF%E3%82%A8%E3%82%B9%E3%83%88)"},{"name":"デスピサロ","game":"ドラゴンクエスト4","description":{"ja":"人間に愛するエルフの少女ロザリーを奪われ、憎悪と悲嘆から進化の秘法で悪魔へと変貌した魔王。愛と復讐の境界を超えた存在であり、その悲劇性が全ての凶行を生む。","en":"A demon king who lost the elf girl Rosaly he loved to human hands and transformed into a devil through the secret art of evolution — driven by hatred and grief. He transcends the line between love and revenge, and that tragedy births all his atrocities."},"reasoning":{"ja":"ロザリー以外への配慮ゼロ（低利他）、自分の復讐のために全てを捧げる孤独な怪物（低チームプレイ）、憎悪の直感で行動（高直感）、力の完成より破壊衝動（低求道）、人間族への無差別な攻撃性（高攻撃）。","en":"Zero consideration for anyone outside of Rosaly (low altruism), a lonely monster who sacrifices everything to his revenge (low cooperation), acts on the pure instinct of his consuming hatred (high intuition), driven by destructive impulse over any disciplined growth (low mastery), and attacks humanity with indiscriminate aggression (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%87%E3%82%B9%E3%83%94%E3%82%B5%E3%83%AD"},{"name":"ラプソーン","game":"ドラゴンクエスト8","description":{"ja":"封印から解放されるために長年に渡り人間の宿主を操り続けた暗黒神。その知略は時間をかけて世界を蝕む蜘蛛の巣のように張り巡らされていた。しかし解放後の姿は純粋な凶暴性そのもの。","en":"A dark deity who spent centuries manipulating human hosts to engineer his own release from a seal. His cunning spread like a spider\'s web slowly corrupting the world — yet once freed, he is pure savage ferocity."},"reasoning":{"ja":"宿主を道具として使い捨てる（低利他）、他者との真の連帯なし（低チームプレイ）、封印解放への本能的な衝動（高直感）、力の蓄積より解放後の暴力（低求道）、世界への破壊衝動（高攻撃）。","en":"He uses and discards hosts as pure tools (low altruism), forms no genuine alliance with any being (low cooperation), driven by an instinctive primal drive toward his own release (high intuition), focused on unleashed violence over disciplined power-building (low mastery), and destroys the world with savage aggression (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%83%A9%E3%83%97%E3%82%BD%E3%83%BC%E3%83%B3"},{"name":"エルギオス","game":"ドラゴンクエスト9","description":{"ja":"人間への幻滅と傷心から堕天した大天使。かつては人間を愛していたが故に、裏切られた時の憎悪は誰よりも深い。その悲劇的な純粋さが最も危険な敵を生み出した。","en":"An archangel who fell from grace through disillusionment and heartbreak over humanity. His love for humans was once the deepest — which made his hatred upon betrayal the most dangerous of all. That tragic purity forged the most dangerous of foes."},"reasoning":{"ja":"傷ついた結果、他者への配慮を封印した（低利他）、孤独に世界に牙を剥く（低チームプレイ）、絶望と憎悪の直感で行動（高直感）、かつての求道心は失われ破壊衝動に変わった（低求道）、人類への宣戦布告（高攻撃）。","en":"His wounds led him to seal away all care for others (low altruism), he turns against the world in complete solitude (low cooperation), acts on the raw instinct of despair and hatred (high intuition), his former devotion to growth has curdled into destructive impulse (low mastery), and he declares war on all humanity (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%82%A8%E3%83%AB%E3%82%AE%E3%82%AA%E3%82%B9"},{"name":"バド","game":"ゼルダの伝説 SS","description":{"ja":"鳥乗りの儀でリンクのライバルとして立ちはだかる騎士学校の問題児。軽口と挑発が得意で、自分の実力を証明することだけを考えている。その素直な向上心が魅力でもある。","en":"A troublemaker at the Knight Academy who stands before Link as a rival in the Wing Ceremony. A master of provocation and trash talk, thinking only of proving his own ability — yet his honest drive to improve is what makes him charming."},"reasoning":{"ja":"自分の勝利のみを追い求める自己中心（低利他）、チームより個人戦を好む（低チームプレイ）、感覚と勢いで挑んでくる（高直感）、正式な修行より本能優先（低求道）、何度でも挑んでくる積極的な攻撃姿勢（高攻撃）。","en":"He pursues only his own victory with self-centered focus (low altruism), prefers individual combat over team play (low cooperation), challenges with instinct and raw momentum (high intuition), follows impulse over formal training discipline (low mastery), and keeps charging with persistent aggressive spirit (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%83%90%E3%83%89(%E3%82%BC%E3%83%AB%E3%83%80%E3%81%AE%E4%BC%9D%E8%AA%AC)"}],"description":{"ja":"単独行動、直感任せ、結果重視。美学なんて知らない。勝てばいい。お前は生存本能で動く獣だ。社会のルールなんて、お前には関係ない。","en":"Solo action, instinct-driven, results-focused. Aesthetics? Don\'t know her. Just win. You\'re a beast driven by survival instinct. Society\'s rules don\'t apply to you."},"deepDescription":{"ja":"マキャベリズムの極致。目的のためなら手段を選ばない。道徳は弱者の言い訳だと信じている。","en":"Peak Machiavellianism — any means for the end. Morality is an excuse for the weak, and you know it."},"recommendedGames":["GTA V","Apex Legends","Valorant"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"high","mastery":"low"},"characterDescription":{"ja":"道徳も計画も持たない純粋な暴力の化身。マイケルへの裏切りへの怒りも、隣人への突発的暴力も、全ては本能が命じるまま。「トレバー・フィリップス工業」は狂気の帝国。","en":"The pure embodiment of violence with no morality and no plan. Rage at Michael\'s betrayal, spontaneous brutality against neighbors—all of it follows wherever instinct commands. Trevor Phillips Industries is an empire of madness."},"characterReasoning":{"ja":"マイケルやフランクリンと行動するが（形式的協調）、本質は誰の指図も受けない暴力衝動（低協調）。直感と感情のまま行動（高直感）し、強盗の技術より感情爆発を優先（低求道）。「俺が欲しいものを取る」という純粋な自己中心性（低利他）が全て。","en":"He operates with Michael and Franklin (nominal cooperation) but his core is uncontrollable violent impulse answering to no one (low cooperation). Pure instinct and emotion drive every action (high intuition), with emotional explosions overriding any heist craft (low mastery). \'I take what I want\'—pure self-interest (low altruism)."}},{"id":"HLLLH","name":{"ja":"暗殺者の禅","en":"The Assassin\'s Zen"},"character":"隻狼","characterGame":"Sekiro: Shadows Die Twice","characterUrl":"https://dic.nicovideo.jp/a/sekiro:%20shadows%20die%20twice","additionalCharacters":[{"name":"バージル","game":"Devil May Cry","description":{"ja":"力こそが全ての美学である半魔の剣士。感情を排除し、弱さを憎み、剣の極致だけを追い求める。母を守れなかった過去への応答として、彼は「完璧な強さ」に自己を捧げた。","en":"A half-demon swordsman whose entire aesthetic is that power is everything. He eliminates emotion, despises weakness, and pursues only the ultimate pinnacle of the sword. As an answer to the past where he could not protect his mother, he devoted himself to \'perfect strength.\'"},"reasoning":{"ja":"他者への配慮を全て切り捨てた孤高（低利他）、誰とも真に連帯しない（低チームプレイ）、感情ではなく静謐な計算（低直感）、剣の絶対的な完成を追い求める（高求道）、常に先制し圧倒する戦闘美学（高攻撃）。","en":"He has severed all care for others in his solitary pursuit (low altruism), forms no genuine bond with anyone (low cooperation), operates through cold calculation rather than intuition (low intuition), relentlessly pursues absolute sword mastery (high mastery), and dominates through preemptive, aesthetically perfect aggression (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%90%E3%83%BC%E3%82%B8%E3%83%AB_(%E3%83%87%E3%83%93%E3%83%AB%20%E3%83%A1%E3%82%A4%20%E3%82%AF%E3%83%A9%E3%82%A4)"},{"name":"ウェスカー","game":"バイオハザード","description":{"ja":"S.T.A.R.S.の隊長として仲間を裏切り、自ら生物兵器の実験体となって神になろうとした男。完璧な肉体と知性を持ちながら、全ての人類を見下す冷徹な超越主義者。","en":"A man who betrayed his S.T.A.R.S. comrades as their captain, willingly made himself a biological weapon test subject, and sought to become a god. Possessing a perfect body and intellect, he is a cold transcendentalist who looks down on all humanity."},"reasoning":{"ja":"仲間すら実験の道具として処分（低利他）、誰とも真に連帯しない超然とした孤高（低チームプレイ）、感情ではなく緻密な知性で動く（低直感）、完璧な存在への到達を追い続ける（高求道）、人類全体を標的にした攻撃性（高攻撃）。","en":"He disposed of teammates as mere experimental tools (low altruism), stands in transcendent solitude forming no true alliance (low cooperation), operates through meticulous cold intellect over intuition (low intuition), relentlessly pursues evolution toward perfect existence (high mastery), and targets all of humanity with his aggression (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%AB%E3%83%90%E3%83%BC%E3%83%88%E3%83%BB%E3%82%A6%E3%82%A7%E3%82%B9%E3%82%AB%E3%83%BC"},{"name":"スコール","game":"FF8","description":{"ja":"「関わらなければ傷つかない」という鎧を身にまとい、感情を封印して孤独に生きてきたSeeD。誰よりも冷静で、誰よりも傷つきやすい矛盾した剣士。リノアと出会うまでは。","en":"A SeeD who armored himself in the creed \'if I don\'t get involved, I can\'t get hurt,\' sealing away his emotions to live in solitude. More cool-headed than anyone, more vulnerable than anyone — a contradictory swordsman. Until he met Rinoa."},"reasoning":{"ja":"他者との関わりを意図的に遮断（低利他）、仲間との連携を拒む孤高の戦士（低チームプレイ）、感情より冷静な判断（低直感）、ガンブレードの技術を磨き続ける求道者（高求道）、戦場では常に前に出る（高攻撃）。","en":"He deliberately shuts out connection with others (low altruism), stands alone refusing to synergize with teammates (low cooperation), operates through cold judgment over emotional intuition (low intuition), continuously refines his Gunblade technique (high mastery), and always advances to the frontline in battle (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%B9%E3%82%B3%E3%83%BC%E3%83%AB%E3%83%BB%E3%83%AC%E3%82%AA%E3%83%B3%E3%83%8F%E3%83%BC%E3%83%88"},{"name":"御剣怜侍","game":"逆転裁判","description":{"ja":"冷酷な完璧主義者として法廷に君臨した検察官にして、「自分が父を殺したのではないか」というDL-6事件のトラウマを一人で背負い続けた孤独な貴公子。勝訴記録への執着は、深い傷の代償行動だった。","en":"A prosecutor who reigned over the courtroom as a cold perfectionist, while silently carrying the trauma of the DL-6 Incident — the fear that he might have killed his own father. His obsession with a perfect win record was compensatory behavior for wounds cut deep."},"reasoning":{"ja":"他者への温情より正義の貫徹（低利他）、誰とも真に心を開かない孤独な戦士（低チームプレイ）、感情を封印した冷静な論理（低直感）、無敗記録という完璧さの追求（高求道）、法廷での圧倒的な攻撃的追求（高攻撃）。","en":"He pursues justice over mercy for individuals (low altruism), is a solitary warrior who opens his heart to no one (low cooperation), deploys sealed, cold logic over emotional intuition (low intuition), pursues the perfection of an unbroken win record (high mastery), and strikes with overwhelming aggressive prosecution in court (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E5%BE%A1%E5%89%A3%E6%80%9C%E4%BE%8D"},{"name":"ガノンドロフ","game":"ゼルダの伝説","description":{"ja":"力のトライフォースを求め、ハイラルを幾千年もの時をかけて繰り返し征服しようとしてきた大魔王。その執念は業のように深く、リンクとゼルダとの因縁は永遠に続く。","en":"The Demon King who has sought the Triforce of Power and repeatedly attempted to conquer Hyrule across thousands of years. His obsession runs deep as fate itself, and the karmic bond with Link and Zelda continues forever."},"reasoning":{"ja":"他者への配慮ゼロの支配欲（低利他）、臣下を持つが孤高の存在（低チームプレイ）、感情より計算された邪悪な知性（低直感）、力の完成を時を超えて追い続ける（高求道）、ハイラル征服という最大規模の攻撃性（高攻撃）。","en":"Pure domination with zero consideration for others (low altruism), rules through subjects but remains an absolutely solitary existence (low cooperation), wields calculated evil intellect over raw instinct (low intuition), pursues the perfection of power across eons (high mastery), and embodies aggression at the scale of conquering an entire kingdom (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%AC%E3%83%8E%E3%83%B3%E3%83%89%E3%83%AD%E3%83%95"},{"name":"ギルガメッシュ","game":"Fate/stay night","description":{"ja":"全ての宝具の原典を持つ英雄王にして、全ての人類を見下す傲岸不遜な存在。自分こそが世界の基準であり、認めた相手にのみ僅かな敬意を示す絶対的な孤高。","en":"The King of Heroes who possesses the original of every Noble Phantasm, an arrogant and imperious existence who looks down on all humanity. He is his own standard for the world, showing the barest flicker of respect only to those he deems worthy."},"reasoning":{"ja":"人類全体を見下す超越した孤高（低利他・低チームプレイ）、感情より自分の価値基準による冷徹な判断（低直感）、既に宝具の頂点を持つが更なる完成を欲しない（高求道的だが充足済）、何者にも屈しない圧倒的な攻撃性（高攻撃）。","en":"His transcendent solitude looks down on all humanity (low altruism, low cooperation), operates by cold personal value-judgment rather than emotional instinct (low intuition), already possesses the pinnacle of all power in his treasury (high mastery — already perfected), and strikes with absolute aggression that bows to nothing (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%AE%E3%83%AB%E3%82%AC%E3%83%A1%E3%83%83%E3%82%B7%E3%83%A5_(Fate%E3%82%B7%E3%83%AA%E3%83%BC%E3%82%BA)"},{"name":"明智吾郎","game":"ペルソナ5","description":{"ja":"完璧な探偵少年の仮面の下に、父への復讐と深い孤独を抱えた二重スパイ。誰にも心を開かず、笑顔で真実を隠し通した。その美しい仮面が最も残酷な武器だった。","en":"Behind the mask of a perfect detective prodigy, a double-agent carrying revenge against his father and bone-deep loneliness. He showed his truth to no one, concealing everything beneath a flawless smile. That beautiful mask was his most cruel weapon."},"reasoning":{"ja":"復讐のために他者を道具として利用（低利他）、真の協力者を持たない孤独な謀略家（低チームプレイ）、感情を演技で封印した計算的行動（低直感）、探偵技術と心理操作の完成を追う（高求道）、常に先手を取り罠を仕掛ける（高攻撃）。","en":"He uses others as tools for his revenge (low altruism), a lonely schemer with no true ally (low cooperation), seals his emotions behind performance and acts through calculated strategy (low intuition), relentlessly perfects his detective skills and psychological manipulation (high mastery), and always lays traps and strikes first (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E6%98%8E%E6%99%BA%E5%90%BE%E9%83%8E"},{"name":"ヨル","game":"Valorant","description":{"ja":"日本出身の孤高の工作員。次元の裂け目を操り、テレポートとデコイで敵を翻弄する能力を持つ。己の実力だけを信じて静かに戦場を制する。感情を表に出さず、ただ任務を完遂する暗殺者の美学。","en":"A solitary operative from Japan who tears through dimensional rifts, bamboozling enemies with teleportation and decoys. Trusting only in his own ability, he controls the battlefield in silence. The aesthetics of an assassin — no emotion displayed, only mission accomplished."},"reasoning":{"ja":"他者への配慮を持たない任務優先の工作員（低利他）、チームより孤独な潜入を好む（低チームプレイ）、感情より緻密な計算（低直感）、次元操作技術の完成を追い求める（高求道）、先手のテレポートと奇襲による攻撃性（高攻撃）。","en":"Mission-first operative with no consideration for others (low altruism), prefers solitary infiltration over team play (low cooperation), operates through meticulous calculation over intuition (low intuition), relentlessly perfects dimensional rift technique (high mastery), and attacks through preemptive teleportation and ambushes (high aggression)."},"url":"https://dic.nicovideo.jp/a/%E3%83%A8%E3%83%AB(VALORANT)"},{"name":"雷電将軍","game":"原神","description":{"ja":"「永恒」を追い求め、変化を拒んだ雷の神。自らの心を刀に封じ込め、感情を切り離して国を統治した孤独な女神。その鉄の意志の奥には、失われた仲間への深い悲嘆が眠る。","en":"A god of lightning who pursued \'eternity\' and rejected all change. She sealed her own heart inside her sword, governing her nation with emotion severed — a solitary goddess. Deep beneath that iron will sleeps profound grief for those she lost."},"reasoning":{"ja":"感情を封じた孤高の統治（低利他・低チームプレイ）、計算された原則に従う（低直感）、永恒という絶対の完成を追い求める（高求道）、異を唱える者を圧倒する支配的な攻撃性（高攻撃）。","en":"She governs in solitude with sealed emotions (low altruism, low cooperation), acts according to calculated principles over intuition (low intuition), relentlessly pursues the absolute perfection of eternity (high mastery), and dominates those who challenge her with overwhelming aggressive authority (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E9%9B%B7%E9%9B%BB%E5%B0%86%E8%BB%8D"},{"name":"メタナイト","game":"星のカービィ","description":{"ja":"騎士道を体現する謎の仮面の剣士。カービィの最大のライバルにして、真の危機には最初に剣を抜く守護者。誰とも群れず、自分のコードに従ってのみ生きる。","en":"A mysterious masked swordsman who embodies chivalry. Kirby\'s greatest rival, yet the first to draw his blade in true crisis. He runs with no one, living only by his own code."},"reasoning":{"ja":"孤高の騎士として誰とも深く連帯しない（低利他・低チームプレイ）、感情より武士道的な原則（低直感）、剣の完璧な技術を極める求道者（高求道）、常に先制して相手に剣を授け正々堂々戦う攻撃の美学（高攻撃）。","en":"A solitary knight who forms no deep bond with anyone (low altruism, low cooperation), operates by chivalric principle rather than emotional instinct (low intuition), relentlessly hones his perfect swordsmanship to its limit (high mastery), and embodies an aesthetic of aggression — always striking first, then handing the foe a sword for a fair fight (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%A1%E3%82%BF%E3%83%8A%E3%82%A4%E3%83%88"},{"name":"カズヤ","game":"鉄拳","description":{"ja":"父ヘイハチに崖から投げ落とされた過去を持ち、悪魔遺伝子を力の源に復讐と支配を追い続ける鉄拳の帝王。怒りと冷酷さが完璧に融合した、鉄拳シリーズ最大の闇。","en":"Thrown off a cliff by his father Heihachi in childhood, the emperor of Tekken who uses Devil Gene as his power source to pursue revenge and dominion. Rage and cold cruelty fused to perfection — the greatest darkness in the Tekken series."},"reasoning":{"ja":"復讐以外への配慮ゼロ（低利他）、誰とも真に連帯しない孤独な覇者（低チームプレイ）、感情より冷徹な計算（低直感）、格闘技術と悪魔の力の完成（高求道）、父への復讐という最も個人的な攻撃性（高攻撃）。","en":"Zero consideration for anything beyond revenge (low altruism), a solitary tyrant who forms no true alliance (low cooperation), cold calculation over emotional impulse (low intuition), relentlessly perfects martial technique and Devil Gene mastery (high mastery), and embodies the most personal aggression — vengeance against his own father (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E4%B8%89%E5%B3%B6%E4%B8%80%E5%B9%B3"},{"name":"レッド","game":"ポケモン赤緑","description":{"ja":"言葉少なく孤高の山頂に立つ、ポケモン世界最強のトレーナー。主人公として世界を救いながら、その後は誰とも語らず孤独に自分を磨き続ける。その沈黙が全てを語る。","en":"The strongest Pokémon Trainer in the world, standing alone at the summit in silence. He saved the world as the protagonist, then sought no one — continuing to hone himself in solitude. That silence says everything."},"reasoning":{"ja":"孤独に山頂で修行を続ける（低利他・低チームプレイ）、言葉ではなく感覚でポケモンと戦う（低直感＝実際は冷静）、最強への徹底した求道（高求道）、チャンピオンも退ける圧倒的な攻撃性（高攻撃）。","en":"He trains alone at the summit, connecting with no one (low altruism, low cooperation), communicates with his Pokémon through silent cold focus rather than emotional instinct (low intuition), pursues the absolute pinnacle with relentless discipline (high mastery), and overwhelms even Champions with unstoppable aggression (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%AC%E3%83%83%E3%83%89_(%E3%83%9D%E3%82%B1%E3%83%A2%E3%83%B3)"},{"name":"アカギ","game":"ポケモンDPt","description":{"ja":"ポケモン世界の神を呼び出し、存在の枠組みごと作り直そうとしたギンガ団のボス。虚無への渇望という形而上学的な動機は、シリーズ最も哲学的な悪役を生み出した。","en":"The boss of Team Galactic who summoned Pokémon\'s gods to reconstruct the very framework of existence. His metaphysical motive — a yearning for nothingness — produced the most philosophically complex villain in the series."},"reasoning":{"ja":"他者の存在ごと消去しようとする究極の利己主義（低利他）、部下を道具として使う孤高の哲学者（低チームプレイ）、感情を排除した冷徹な論理（低直感）、宇宙の完全な再構築という求道的野望（高求道）、創造神を手中に収める最大規模の攻撃性（高攻撃）。","en":"Ultimate selfishness — he seeks to erase the existence of others along with everything else (low altruism), a solitary philosopher who uses subordinates as tools (low cooperation), cold emotion-less logic (low intuition), a mastery-driven ambition to reconstruct the entire universe from scratch (high mastery), and the most sweeping aggression imaginable — controlling creator gods themselves (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%A2%E3%82%AB%E3%82%AE_(%E3%83%9D%E3%82%B1%E3%83%A2%E3%83%B3)"}],"description":{"ja":"一人で、計算し、美学を追求する。自分のスキルだけを信じ、完璧な一撃のために何百回も練習する。お前は孤独な職人であり、戦いは芸術だ。","en":"Alone, calculated, pursuing aesthetics. Trusting only your own skill, practicing hundreds of times for the perfect strike. You\'re a solitary artisan, and combat is art."},"deepDescription":{"ja":"禅の「一射入魂」。弓道のように、一つ一つの動作に全てを込める。結果ではなく、過程の完璧さを追い求める。","en":"Zen\'s \'one shot, whole soul\' — like kyudo, pouring everything into each single action. Pursuing perfection of process, not result."},"recommendedGames":["Sekiro","Devil May Cry 5 (Vergil)","Dark Souls III"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"low","mastery":"high"},"characterDescription":{"ja":"「死なずの御子を取り戻せ」という師の掟に従い、ただ一人で葦名の地獄を歩く隻腕の忍。感情も迷いも捨て、ただ義務だけで死を超える。それが忍の禅。","en":"A one-armed shinobi who walks the hell of Ashina alone, obeying his master\'s command: \'Reclaim the Divine Heir.\' He discards emotion and doubt, transcending death through pure duty. That is the zen of the shinobi."},"characterReasoning":{"ja":"御子を取り戻すという義務のみで動く孤独な忍（低協調）。計算された弾き返し・体幹崩しという技術の極限（高求道）を、感情なき戦闘計算（低直感）で実行する。仲間への愛着より主への忠誠（低利他）が全て。","en":"He\'s a lone shinobi driven solely by the duty of reclaiming the heir (low cooperation). The calculated mastery of deflection and posture-breaking pushed to its limits (high mastery) is executed through emotionless tactical calculation (low intuition). Loyalty to his master over personal attachment (low altruism) is everything."}},{"id":"HLLLL","name":{"ja":"孤独の狩人","en":"The Solitary Hunter"},"character":"サムス・アラン","characterGame":"メトロイド","characterUrl":"https://ja.wikipedia.org/wiki/%E3%82%B5%E3%83%A0%E3%82%B9%E3%83%BB%E3%82%A2%E3%83%A9%E3%83%B3","additionalCharacters":[{"name":"リドリー","game":"メトロイド","description":{"ja":"サムスの家族を殺した宇宙海賊の幹部にして、不死鳥のように何度でも復活するシリーズ最凶の強敵。知性と残虐性を兼ね備え、殺戮そのものを楽しむ怪物。","en":"The Space Pirate leader who murdered Samus\'s family and the series\' most brutal recurring enemy, resurrecting phoenix-like time after time. He combines intelligence with savagery, a monster who genuinely enjoys the act of killing."},"reasoning":{"ja":"殺戮を純粋に楽しむ無慈悲な捕食者（低利他）、宇宙海賊の一員だが真に連帯しない（低チームプレイ）、計算より本能的な暴力衝動（低直感）、技術より純粋な暴力の体現（低求道）、最も純粋な破壊の攻撃性（高攻撃）。","en":"A merciless predator who genuinely enjoys slaughter (low altruism), nominally part of Space Pirates but forms no true bond (low cooperation), driven by primal violent impulse over strategy (low intuition), embodies raw violence over disciplined craft (low mastery), and represents the purest destructive aggression in the series (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%AA%E3%83%89%E3%83%AA%E3%83%BC"},{"name":"サム・フィッシャー","game":"Splinter Cell","description":{"ja":"第三エシュロンのスパイとして、国家も仲間も知らない孤独な任務をこなし続ける影の工作員。感情を封じ、痕跡を残さず、どんな状況でも最適解を冷静に実行する。","en":"A shadow operative of Third Echelon who carries out solitary missions unknown to nation or comrades. He seals his emotions, leaves no trace, and calmly executes the optimal solution in any situation."},"reasoning":{"ja":"国家のために動くが個人的な絆は持たない（低利他）、孤独な潜入任務が本質（低チームプレイ）、感情より訓練された冷静な判断（低直感）、スパイ技術の完成を追うが派手さを求めない（低求道）、先手と奇襲の攻撃性（高攻撃）。","en":"Acts for the nation but carries no personal bonds (low altruism), solitary infiltration is his essence (low cooperation), trained cold judgment over emotional instinct (low intuition), refines spy craft without seeking recognition or glory (low mastery), and strikes through preemptive ambush aggression (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%B5%E3%83%A0%E3%83%BB%E3%83%95%E3%82%A3%E3%83%83%E3%82%B7%E3%83%A3%E3%83%BC"}],"description":{"ja":"一人で、計算し、効率的に、攻撃する。美学も仲間も必要ない。賞金稼ぎとして、任務を遂行するだけだ。感情は不要な変数。冷たい精密さと圧倒的火力が、お前の全てだ。","en":"Solo, calculated, efficient, aggressive. No aesthetics, no allies needed. As a bounty hunter, you simply execute the mission. Emotions are unnecessary variables. Cold precision and overwhelming firepower are everything."},"deepDescription":{"ja":"論理実証主義。検証可能なもの以外は無意味。感情も美学も、データに現れないものには価値がない。","en":"Logical positivism — anything unverifiable is meaningless. Emotions, aesthetics — if it doesn\'t show in the data, it has no value."},"recommendedGames":["メトロイド ドレッド","Metroid Prime Remastered","Alien: Isolation"],"axes":{"aggression":"high","altruism":"low","cooperation":"low","intuition":"low","mastery":"low"},"characterDescription":{"ja":"銀河系最強の賞金稼ぎ。感情も仲間も不要、宇宙の果ての危機を一人で解決する。パワードスーツに包まれた孤独な狩人は、最小限の行動で最大の結果を出す効率の体現。","en":"The galaxy\'s strongest bounty hunter. No emotions, no allies needed—she solves crises at the edge of the universe alone. The solitary hunter encased in Power Suit is the embodiment of efficiency: maximum results with minimum action."},"characterReasoning":{"ja":"単独でメトロイドやリドリーを狩る（低協調）賞金稼ぎ。直感より状況分析と経験則（低直感）、技を磨く求道より「任務を完遂する」実利（低求道）が特徴。銀河連邦への忠誠より個人的な賞金稼ぎの使命（低利他）。","en":"A bounty hunter who hunts Metroids and Ridley alone (low cooperation). Situational analysis and experience over gut instinct (low intuition), pragmatic mission completion over polishing martial craft (low mastery). Personal bounty-hunter mission over loyalty to the Galactic Federation (low altruism)."}},{"id":"LHHHH","name":{"ja":"星降る聖女","en":"The Starlit Saint"},"character":"エアリス","characterGame":"Final Fantasy VII","characterUrl":"https://ja.wikipedia.org/wiki/%E3%82%A8%E3%82%A2%E3%83%AA%E3%82%B9%E3%83%BB%E3%82%B2%E3%82%A4%E3%83%B3%E3%82%BA%E3%83%96%E3%83%BC%E3%83%AB","additionalCharacters":[{"name":"天照","game":"大神","description":{"ja":"白き狼の姿をまとった太陽の女神にして、日輪の化身。墨で世界を描き直す筆を持ち、人も動物も草花も、全てのいのちを慈しむ創造の神。その笑顔が世界を救う光そのもの。","en":"The goddess of the sun manifested as a white wolf — the embodiment of the solar disc. Armed with a brush that repaints the world in ink, she cherishes every life, human and animal and flower alike. Her smile is light itself saving the world."},"reasoning":{"ja":"全てのいのちを慈しむ究極の利他性（高利他）、人々と協力して世界を修復する（高チームプレイ）、芸術的な直感で世界を描き直す（高直感）、神の技として筆の力を極める（高求道）、悪に対して常に立ち向かう（高攻撃）。","en":"She cherishes all life with ultimate altruism (high altruism), works with all beings to restore the world (high cooperation), repaints reality through artistic divine instinct (high intuition), masters the celestial brush as a divine art (high mastery), and always confronts evil head-on (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E5%A4%A7%E7%A5%9E_(%E3%82%B2%E3%83%BC%E3%83%A0)"},{"name":"フローラ","game":"ドラゴンクエスト5","description":{"ja":"大富豪の令嬢として育ちながら、主人公の旅に自ら加わり共に歩む聡明な女性。主人公の幸せのためなら自分の恵まれた環境を全て捨てられる。その優しさは芯の通った愛だ。","en":"A brilliant woman raised as the daughter of a great magnate who joins the hero\'s journey of her own will. She can abandon all her privileged circumstances for the hero\'s happiness. Her gentleness is love with a solid core."},"reasoning":{"ja":"主人公とその家族のために全てを捧げる（高利他）、仲間と共に戦場を乗り越える（高チームプレイ）、状況を読む直感的な賢明さ（高直感）、魔法の技を磨き続ける（高求道）、仲間を守るための積極的な戦闘参加（高攻撃）。","en":"She offers everything for the hero and family (high altruism), overcomes every battlefield alongside companions (high cooperation), reads situations with intelligent intuition (high intuition), continuously hones her magical craft (high mastery), and actively joins the fight to protect her companions (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%89%E3%83%A9%E3%82%B4%E3%83%B3%E3%82%AF%E3%82%A8%E3%82%B9%E3%83%88V"},{"name":"カルネ","game":"ポケモンXY","description":{"ja":"カロス地方のチャンピオンにして有名な女優。優雅な佇まいの裏に圧倒的な実力を秘め、主人公の成長を見守りながら、メガシンカの謎に迫る。ポケモンへの深い愛と知性を兼ね備えた、カロスの至宝。","en":"The Champion of the Kalos region and a famous actress. Behind her elegant poise lies overwhelming strength, as she watches over the protagonist\'s growth while pursuing the mysteries of Mega Evolution. A treasure of Kalos who combines deep love for Pokémon with sharp intelligence."},"reasoning":{"ja":"主人公たちの成長を全力で支援する（高利他）、チャンピオンとしてカロスの秩序を守る（高チームプレイ）、直感的なバトルセンスと表現力（高直感）、女優とチャンピオンの二道を極める（高求道）、フレア団への毅然とした立ち向かい（高攻撃）。","en":"She supports the protagonists\' growth with everything she has (high altruism), protects Kalos\'s order as Champion (high cooperation), battles with intuitive sense and artistic expression (high intuition), pursues mastery in both acting and Champion-level battling (high mastery), and stands firmly against Team Flare (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%9D%E3%82%B1%E3%83%83%E3%83%88%E3%83%A2%E3%83%B3%E3%82%B9%E3%82%BF%E3%83%BCXY"},{"name":"ゼルダ","game":"ゼルダの伝説 SS","description":{"ja":"スカイロフトの騎士学校長ゲポラの娘にして、女神ハイリアの生まれ変わり。地上に降り立ち、封印の力を目覚めさせるための旅に出る。リンクへの深い信頼と、世界を守るための自己犠牲の覚悟が彼女の本質。","en":"Daughter of Gaepora, headmaster of the Knight Academy on Skyloft, and the mortal reincarnation of the Goddess Hylia. She descends to the surface to awaken the sealing power, embarking on a journey of her own. Her essence is deep trust in Link and the resolve to sacrifice herself to protect the world."},"reasoning":{"ja":"リンクを信じ共に戦う（高協調）。女神ハイリアの記憶という直感的な啓示（高直感）で終焉の者の脅威を察知する。世界を守るための自己犠牲の献身（高利他）と、封印の力を目覚めさせるための使命の遂行（高求道）が特徴。","en":"She trusts Link and fights alongside him (high cooperation). Intuitive revelation through Hylia\'s awakening memories (high intuition) lets her sense the threat of Demise. Devotion to self-sacrifice for the world\'s protection (high altruism) and the driven pursuit of awakening the sealing power (high mastery) define her."},"url":"https://ja.wikipedia.org/wiki/%E3%82%BC%E3%83%AB%E3%83%80_(%E3%82%B2%E3%83%BC%E3%83%A0%E3%82%AD%E3%83%A3%E3%83%A9%E3%82%AF%E3%82%BF%E3%83%BC)"},{"name":"ミファー","game":"ゼルダの伝説 BotW","description":{"ja":"ゾーラの姫にして神獣ヴァ・ルッタの英雄。水の力で仲間を癒す優しさと、百年越しのリンクへの思いを持つ。命を懸けてリンクを守り続けた愛は、時を超えて届く。","en":"Princess of Zora and Champion of Divine Beast Vah Ruta. Her gentleness heals companions with water\'s power, and she carries a century-spanning love for Link. The love with which she protected him at the cost of her life reaches across time."},"reasoning":{"ja":"仲間とリンクのために命を捧げる（高利他）、チャンピオンとして仲間と共に戦う（高チームプレイ）、水と癒しの直感的な感受性（高直感）、水の力の技術を磨き続ける（高求道）、ガノンへの毅然とした立ち向かい（高攻撃）。","en":"She lays down her life for Link and her companions (high altruism), fights alongside the Champions as one of their own (high cooperation), embodies intuitive sensitivity to water and healing (high intuition), continuously refines the art of water\'s power (high mastery), and confronts Ganon with quiet but unwavering resolve (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%9F%E3%83%95%E3%82%A1%E3%83%BC"},{"name":"ロイ","game":"FE封印の剣","description":{"ja":"フェレ侯爵の息子として義勇軍を率い、炎の剣とともにエレブ大陸を解放した若き英雄。仲間を信じて前に立ち続け、その純粋な熱さが最後の勝利を掴む。","en":"The young hero who led a volunteer army as the son of Marquess Pherae and liberated the continent of Elibe wielding the Sword of Seals. He stands at the front trusting in his companions, and that pure ardor seizes the final victory."},"reasoning":{"ja":"仲間を守るために先頭に立ち続ける（高利他・高攻撃）、義勇軍のリーダーとして全員と共に戦う（高チームプレイ）、直感と熱意で戦局を打開する（高直感）、英雄への道を諦めず磨き続ける（高求道）。","en":"He stands at the front to protect his companions above all (high altruism + high aggression), leads the volunteer army fighting as one with everyone (high cooperation), breaks through battles with instinct and ardor (high intuition), and never stops honing himself on the path to heroism (high mastery)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%95%E3%82%A1%E3%82%A4%E3%82%A2%E3%83%BC%E3%82%A8%E3%83%A0%E3%83%96%E3%83%AC%E3%83%A0_%E5%B0%81%E5%8D%B0%E3%81%AE%E5%89%A3"}],"description":{"ja":"慎重で包容力に満ち、チームの光であり、セトラの直感に導かれ、使命に生きる。お前は戦場の天使だ。究極の自己犠牲を厭わない。殺すことより生かすことに価値を見出す。その優しさが、世界を救う力になる。","en":"Cautious and compassionate, the team\'s light, guided by Cetra intuition, living for a mission. You\'re the battlefield\'s angel. You don\'t shy from the ultimate self-sacrifice. Saving matters more than slaying. That kindness becomes the power to save the world."},"deepDescription":{"ja":"レヴィナスの他者論。「他者の顔」に応答する倫理。自分より先に、目の前の他者のことを考える。","en":"Lévinas\' ethics of the Other — responding to \'the face of the Other.\' Always thinking of the person in front of you before yourself."},"recommendedGames":["FF7 Rebirth","大神","Journey"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"high","mastery":"high"},"characterDescription":{"ja":"最後の古代種として星の声を聞ける唯一の存在。戦わずして星を救う道を直感的に選び、自らを捧げることを笑顔で受け入れた。慈愛と直感と、完璧な献身の体現。","en":"The last Ancient, the only one who can hear the Planet\'s voice. She intuitively chose the path of saving the Planet without fighting and accepted self-sacrifice with a smile. The embodiment of love, intuition, and perfect devotion."},"characterReasoning":{"ja":"星と仲間を守るために命を捧げる究極の利他主義（高利他）。クラウドや仲間との絆（高協調）を大切にし、星の声という直感的な啓示（高直感）に従い行動する。白魔法と古代種の力の体系的習得（高求道）も持つ。","en":"Ultimate altruism in giving her life to protect the Planet and companions (high altruism). She treasures bonds with Cloud and allies (high cooperation), acts on the intuitive revelation of the Planet\'s voice (high intuition), and holds systematic mastery of white magic and Ancient powers (high mastery)."}},{"id":"LHHHL","name":{"ja":"心の羅針盤","en":"The Heart\'s Compass"},"character":"ティファ","characterGame":"Final Fantasy VII","characterUrl":"https://ja.wikipedia.org/wiki/ティファ・ロックハート","additionalCharacters":[{"name":"ノクティス","game":"FF15","description":{"ja":"クリスタルに選ばれた光の王にして、幼馴染たちと共に旅した若き王子。仲間の愛情の中で初めて本当の王に成長した。世界を救うために全てを捧げた時、彼は真の英雄だった。","en":"A young prince chosen by the Crystal as the King of Light, who journeyed with his childhood friends. He first grew into a true king surrounded by the love of companions. When he gave everything to save the world, he became a true hero."},"reasoning":{"ja":"仲間のために最後には命をも捧げる（高利他）、幼馴染4人との絆が全ての根幹（高チームプレイ）、直感と感情で局面を切り開く（高直感）、王としての成長より仲間との旅を優先（低求道）、最後の光の王として闘う（高攻撃→実際は低求道、高直感寄り）。","en":"He ultimately gives even his life for companions (high altruism), the bond with his four childhood friends is the core of everything (high cooperation), navigates crises through emotion and instinct (high intuition), prioritizes the journey with companions over disciplined kingly growth (low mastery), and fights as the final King of Light (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%8E%E3%82%AF%E3%83%86%E3%82%A3%E3%82%B9%E3%83%BB%E3%83%AB%E3%82%B7%E3%82%B9%E3%83%BB%E3%83%8E%E3%82%AF%E3%82%B9"},{"name":"ビアンカ","game":"ドラゴンクエスト5","description":{"ja":"幼馴染の主人公を誰よりも信じ、どんな困難の中でも笑顔を失わない芯の強い女性。貧しい環境の中でも前向きで、仲間への愛情が彼女の最大の武器だ。","en":"A strong-spirited woman who believes in her childhood friend the hero more than anyone, never losing her smile through any hardship. Positive even in poverty, her love for companions is her greatest weapon."},"reasoning":{"ja":"主人公への惜しみない愛情と支援（高利他）、仲間と一緒に旅し共に戦う（高チームプレイ）、感情と直感で人を信じ動く（高直感）、強くなることより一緒にいることを選ぶ（低求道）、仲間を守るための積極的な行動（高攻撃）。","en":"Boundless love and support for the hero (high altruism), travels and fights as one with her companions (high cooperation), believes in people and acts on feeling and intuition (high intuition), chooses being together over becoming stronger (low mastery), and acts boldly to protect her companions (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%83%89%E3%83%A9%E3%82%B4%E3%83%B3%E3%82%AF%E3%82%A8%E3%82%B9%E3%83%88V"},{"name":"成歩堂龍一","game":"逆転裁判","description":{"ja":"「異議あり!」の一声で法廷を変える正義の弁護士。どんな絶望的な状況でも仲間を信じ、直感と熱意で真実を掴み取る。論理より人間への信頼が彼の最強の武器。","en":"A justice-driven defense attorney who flips courtrooms with a single \'Objection!\' He trusts his companions through any desperate situation and seizes the truth with instinct and passion. His greatest weapon is not logic — it\'s his belief in people."},"reasoning":{"ja":"依頼人を全力で信じ守る（高利他）、法廷での仲間との連携（高チームプレイ）、証拠よりも直感で真相に辿り着く（高直感）、弁護士として成長するより今の依頼人を救うことを優先（低求道）、検察への果敢な立ち向かい（高攻撃）。","en":"He trusts and protects his clients with everything (high altruism), coordinates with courtroom allies (high cooperation), reaches the truth through instinct over evidence (high intuition), prioritizes saving today\'s client over disciplined growth as a lawyer (low mastery), and boldly confronts the prosecution head-on (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E6%88%90%E6%AD%A9%E5%A0%82%E9%BE%8D%E4%B8%80"},{"name":"N","game":"ポケモンBW","description":{"ja":"ポケモンの声が聞こえると言った少年。理想に向かって走り続けたが、その根っこは純粋な愛情だった。","en":"The boy who claimed he could hear Pokémon speak. He chased ideals relentlessly, but the root was always pure love."},"reasoning":{"ja":"ポケモンへの深い共感（高利他性）と直感的な理解力で動くが、計算や支配への欲求は持たない純粋な守護者。","en":"Driven by deep empathy for Pokémon (high altruism) and intuitive understanding, with no appetite for calculation or domination."},"url":"https://dic.nicovideo.jp/a/n%EF%BC%88%E3%83%9D%E3%82%B1%E3%83%83%E3%83%88%E3%83%A2%E3%83%B3%E3%82%B9%E3%82%BF%E3%83%BC%EF%BC%89"},{"name":"サリア","game":"ゼルダの伝説 OoT","description":{"ja":"コキリの森の賢者にして、リンクの最初の友人。リンクが旅立つ時、その背中を優しく押した少女。ハイラルを守るために賢者として眠り続けることを選んだ、永遠の友情の象徴。","en":"The Sage of the Kokiri Forest and Link\'s first true friend. The girl who gently pushed Link\'s back as he set off on his journey. She chose to sleep forever as a Sage to protect Hyrule — the symbol of an eternal friendship."},"reasoning":{"ja":"リンクとハイラルのために全てを捧げる（高利他）、賢者として世界と仲間を守るチームプレイ（高チームプレイ）、自然と音楽への直感的な感受性（高直感）、賢者の力を尽くす（低求道、使命に生きる）、ガノンへの毅然とした立ち向かい（高攻撃）。","en":"She offers everything for Link and Hyrule (high altruism), protects the world and companions through her role as Sage (high cooperation), has deep intuitive sensitivity to nature and music (high intuition), devotes the full power of the Sage to her mission (low mastery — lives for purpose), and stands firm against Ganon (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%B5%E3%83%AA%E3%82%A2_(%E3%82%BC%E3%83%AB%E3%83%80%E3%81%AE%E4%BC%9D%E8%AA%AC)"},{"name":"アデク","game":"ポケモンBW","description":{"ja":"イッシュ地方のチャンピオンにして、誰からの挑戦も笑顔で受け入れる太陽のような男。勝利より対戦相手の成長を喜び、自分の強さを惜しみなく次の世代に伝える。","en":"The Champion of the Unova region and a man like the sun who accepts any challenge with a smile. He rejoices in the growth of opponents over his own victories and generously passes on his strength to the next generation."},"reasoning":{"ja":"挑戦者の成長を心から喜ぶ（高利他）、ポケモンバトルを通じた人との繋がりを大切にする（高チームプレイ）、直感で相手の可能性を見抜く（高直感）、チャンピオンとしての強さより人々との交流を優先（低求道）、挑戦者に全力を尽くす（高攻撃）。","en":"He genuinely rejoices in challengers\' growth (high altruism), values connections with people through Pokémon battles (high cooperation), sees through a person\'s potential with intuitive insight (high intuition), prioritizes connection with people over disciplined pursuit of Championship strength (low mastery), and gives challengers absolutely everything he has (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%A2%E3%83%87%E3%82%AF"},{"name":"カイリ","game":"Kingdom Hearts","description":{"ja":"運命の島でソラとリクを待ち続けた光の心を持つ少女。心が繋がることを信じ、別れの痛みを越えて仲間のもとへ向かう。その純粋な愛が闇を照らす光そのものだ。","en":"A girl with a heart of pure light who waited for Sora and Riku on Destiny Islands. She believes in the connections between hearts, moving toward her companions through the pain of parting. That pure love is light itself illuminating the darkness."},"reasoning":{"ja":"ソラとリクへの深い愛情と献身（高利他）、仲間との絆を何よりも大切にする（高チームプレイ）、心の繋がりを直感で感じ取る（高直感）、戦士として成長するよりも仲間の元へ行くことを優先（低求道）、闇に立ち向かう積極性（高攻撃）。","en":"Deep love and devotion to Sora and Riku (high altruism), she treasures the bond with her companions above all (high cooperation), intuitively senses the connections between hearts (high intuition), prioritizes reaching her companions over disciplined growth as a fighter (low mastery), and actively confronts darkness (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E3%82%AB%E3%82%A4%E3%83%AA_(%E3%82%AD%E3%83%B3%E3%82%B0%E3%83%80%E3%83%A0_%E3%83%8F%E3%83%BC%E3%83%84)"},{"name":"衛宮士郎","game":"Fate/stay night","description":{"ja":"「正義の味方になりたい」という少年の夢を、矛盾と血の中でも諦めなかった男。自分を犠牲にすることを厭わず、目の前の誰かを救うためだけに戦い続ける。その理想は歪であり、しかし美しい。","en":"A man who never gave up on the boyhood dream of \'becoming a champion of justice,\' even through contradiction and blood. He doesn\'t hesitate to sacrifice himself and keeps fighting solely to save whoever stands before him. That ideal is distorted — and yet beautiful."},"reasoning":{"ja":"自己犠牲を厭わない究極の利他性（高利他）、セイバーとアーチャーとの連携（高チームプレイ）、感情と直感で状況を切り開く（高直感）、魔術師の修行より目の前の人を救うことを優先（低求道）、諦めず立ち向かい続ける（高攻撃）。","en":"Ultimate altruism with no hesitation toward self-sacrifice (high altruism), coordinates with Saber and Archer (high cooperation), cuts through situations on emotion and instinct (high intuition), prioritizes saving whoever is before him over disciplined magus training (low mastery), and never stops standing up to fight (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E8%A1%9B%E5%AE%AE%E5%A3%AB%E9%83%8E"},{"name":"藤丸立香","game":"Fate/Grand Order","description":{"ja":"唯一生き残ったマスターとして、人類史を守るために特異点へ旅立つ普通の少年/少女。特別な才能はなくても、英霊たちを信じ共に戦い抜く心の強さが世界を救う。","en":"The sole surviving Master who sets out to singularities to protect human history — an ordinary boy or girl. With no special talent, it\'s the strength of heart to believe in Heroic Spirits and fight alongside them all the way that saves the world."},"reasoning":{"ja":"英霊全員との絆と信頼（高利他・高チームプレイ）、状況への直感的な対応と人の心への共感（高直感）、マスターとして強くなるより絆を深めることを優先（低求道）、どんな特異点にも立ち向かう積極性（高攻撃）。","en":"Bonds and trust with every Heroic Spirit (high altruism + high cooperation), intuitive response to situations and empathy for people\'s hearts (high intuition), prioritizes deepening bonds over disciplined growth as a Master (low mastery), and actively confronts every singularity head-on (high aggression)."},"url":"https://ja.wikipedia.org/wiki/%E8%97%A4%E4%B8%B8%E7%AB%8B%E9%A6%99"},{"name":"マルス","game":"FE暗黒竜と光の剣","description":{"ja":"王としての義務より仲間との絆を信じた。剣の強さより、その背中についてくる人の多さが彼の本質。","en":"He trusted bonds over duties of kingship. His real strength isn\'t the blade—it\'s the people who follow his back."},"reasoning":{"ja":"直感で人を信じ、利他的に仲間を率いる。計算でも求道でもなく、「共にいる」ことで勝利を生む典型的なこのタイプ。","en":"He leads allies through intuitive trust and altruism. Not strategic, not a perfectionist—he wins by staying with his people."},"url":"https://ja.wikipedia.org/wiki/マルス_(ファイアーエムブレムシリーズ)"}],"description":{"ja":"穏やかで慎重。だがチームの精神的な接着剤であり、感覚で人の気持ちを察する。美学より結果を取る現実主義者。お前は派手な英雄ではない。だが、お前がいなければチームは崩壊する。","en":"Gentle and cautious. But you\'re the team\'s emotional glue, sensing others\' feelings by instinct. A realist who chooses results over aesthetics. You\'re no flashy hero — but without you, the team falls apart."},"deepDescription":{"ja":"プラグマティズムの体現者。「真理とは、うまくいくもの」。理想よりも現実に機能するものを選ぶ。","en":"Pragmatism embodied — \'Truth is what works.\' Choosing what functions in reality over lofty ideals."},"recommendedGames":["FF7 Rebirth","逆転裁判","Baldur\'s Gate 3"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"high","mastery":"low"},"characterDescription":{"ja":"強さで戦うより、隣にいることを選ぶ。クラウドの魂が折れそうなとき、彼女の存在が光になった。拳は硬くても、心はいつも開いている。","en":"She fights with her fists but leads with her heart. When Cloud\'s spirit was crumbling, Tifa\'s presence became his anchor. Hard-hitting on the surface, endlessly open within."},"characterReasoning":{"ja":"攻撃性は低く、仲間への献身と直感的な共感力で全体を支える。勝利より「誰も一人にしない」ことを優先する姿がこのタイプを体現する。","en":"Low aggression, high altruism—she supports the group through intuitive empathy rather than strategy. Her priority is never victory but ensuring no one stands alone."}},{"id":"LHHLH","name":{"ja":"鉄壁の参謀長","en":"The Iron Advisor"},"character":"アナ","characterGame":"Overwatch","characterUrl":"https://ja.wikipedia.org/wiki/オーバーウォッチ","additionalCharacters":[{"name":"ビビ","game":"FF9","description":{"ja":"黒魔道士として生まれ、自分の命の意味を問い続けた少年。仲間のために魔法を振るいながら、死の恐怖と向き合い静かに成長した。臆病だが、誰よりも深く「生きること」を考えた存在だ。","en":"A Black Mage who constantly questioned the meaning of his existence. He wielded magic for his companions while quietly confronting the fear of death. Timid, but no one thought more deeply about what it means to be alive."},"reasoning":{"ja":"戦いを好まず（低攻撃）、仲間のために勇気を振り絞り（高利他・高協調）、感情より思索で行動し（低直感）、黒魔道士としての力を極めようとした求道者（高求道）。","en":"He avoids combat instinctively (low aggression), summons courage entirely for his companions (high altruism + high cooperation), acts through reflection rather than impulse (low intuition), and relentlessly hones his black magic craft (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ファイナルファンタジーIX"},{"name":"ユウナ","game":"FF10","description":{"ja":"死を覚悟して召喚士の旅に出た少女。スピラの人々のために自らを犠牲にしようとしながら、仲間と共に正しい道を貫いた。その献身は揺るぎなく、しかし決して感情的ではない。","en":"A summoner who set out on her pilgrimage with death accepted. She sought to sacrifice herself for the people of Spira while holding to the right path alongside her companions. Utterly devoted, but never reckless."},"reasoning":{"ja":"攻撃性を持たず（低攻撃）、スピラの民のためだけに生きる利他の塊（高利他）で、ガードたちとの絆を軸に行動し（高協調）、直感より儀式・使命感で動き（低直感）、召喚士としての求道性を貫く（高求道）。","en":"No aggression whatsoever (low aggression), she lives entirely for others (high altruism), moves in lockstep with her guardians (high cooperation), acts through duty rather than instinct (low intuition), and relentlessly perfects the summoner\'s art (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ファイナルファンタジーX"},{"name":"V","game":"Devil May Cry 5","description":{"ja":"詩集を片手に使い魔を操る、謎めいた老いた青年。戦場に自ら立つことなく、知性と計算で全てを制御する。その身体は崩れゆいても、目的への意志は最後まで折れない。","en":"A mysterious, prematurely aged man who commands familiars with a poetry book in hand. He never fights directly, controlling everything through intellect and calculation. His body crumbles, but his will toward the goal never breaks."},"reasoning":{"ja":"自ら戦わず（低攻撃）、人類と仲間を守るために動き（高利他・高協調）、直感より知識と計算に頼り（低直感）、悪魔の詩を完全に体得しようとする求道的意志（高求道）。","en":"Never engages in direct combat (low aggression), acts to protect humanity and his allies (high altruism + high cooperation), relies on knowledge and calculation over instinct (low intuition), and carries the relentless drive to master the demonic verse (high mastery)."},"url":"https://ja.wikipedia.org/wiki/Devil_May_Cry_5"},{"name":"エックス","game":"ロックマンX","description":{"ja":"戦うことに苦悩しながら戦い続けるレプリロイド。自分が正しいかを常に問いながら、仲間と世界の平和のために戦場に立つ。その迷いこそが、他のロボットにはない人間性の証だ。","en":"A Reploid who agonizes over fighting yet continues to fight. He constantly questions whether he is doing the right thing while standing on the battlefield for his companions and world peace. That very hesitation is proof of a humanity no other robot possesses."},"reasoning":{"ja":"本来戦いを好まず（低攻撃）、ゼロや世界のために戦い続ける利他性（高利他）と協調性（高協調）を持ち、感情より自問自答で行動し（低直感）、最強のレプリロイドを目指す求道精神（高求道）がある。","en":"Fundamentally averse to combat (low aggression), fights on through high altruism for Zero and the world (high altruism + high cooperation), acts through self-reflection rather than instinct (low intuition), and embodies the relentless drive toward becoming the ultimate Reploid (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ロックマンX"},{"name":"ゼルダ姫","game":"ゼルダの伝説","description":{"ja":"ハイラルの命運を背負いながら、自らは表舞台に立てない姫。知恵と策略でリンクを導き、世界を救う計画を静かに実行する。その孤独な使命感が、このタイプの本質を体現する。","en":"A princess who bears the fate of Hyrule but cannot stand at the front herself. She guides Link through wisdom and strategy, quietly executing her plan to save the world. Her solitary sense of duty perfectly embodies this type."},"reasoning":{"ja":"直接戦わず（低攻撃）、ハイラルと民のために全てを捧げ（高利他）、リンクとの連携を軸に動き（高協調）、感情より予言と知恵で行動し（低直感）、賢者・王族としての使命を徹底して全うする（高求道）。","en":"Does not fight directly (low aggression), devotes everything for Hyrule and its people (high altruism), operates through her bond with Link (high cooperation), acts through prophecy and wisdom rather than instinct (low intuition), and fulfills her mission as sage and royal to the last (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ゼルダ姫"},{"name":"セイバー","game":"Fate/stay night","description":{"ja":"かつて王として国を守り続けた騎士王。誰よりも強く、誰よりも孤独で、誰よりも仲間のために戦った。感情を律し、理性と責任で剣を振るい続けた悲劇の英雄。","en":"The King of Knights who once protected her country as a sovereign. Stronger than anyone, lonelier than anyone, and fighting harder than anyone for her companions. A tragic hero who kept swinging her sword through reason and responsibility, holding emotion at bay."},"reasoning":{"ja":"自ら先陣を切るが攻撃欲求ではなく義務で戦い（低攻撃）、令呪の繋がりの中で士郎を守ることに徹し（高利他・高協調）、感情より騎士道の規律に従い（低直感）、騎士の道を極める求道性を体現する（高求道）。","en":"Fights at the front but from duty, not bloodlust (low aggression), dedicates herself entirely to protecting Shirou within their contract (high altruism + high cooperation), follows chivalric code over impulse (low intuition), and embodies total mastery of the knight\'s path (high mastery)."},"url":"https://ja.wikipedia.org/wiki/セイバー_(Fate/stay_night)"},{"name":"鍾離","game":"原神","description":{"ja":"数千年を生きた岩神・モラクスの化身。悠然とした佇まいで仲間を守り、契約と秩序を何より重んじる。激しさを見せないが、その意志の硬度は岩石を凌ぐ。","en":"The incarnation of the Geo Archon Morax, who has lived for thousands of years. He protects his companions with unshakeable composure, valuing contracts and order above all. He shows no intensity, yet his resolve is harder than any stone."},"reasoning":{"ja":"感情的な攻撃性は皆無（低攻撃）、旅人と仲間を守るために力を使い（高利他）、契約に基づいた秩序の中で動き（高協調）、直感より知識と原則に従い（低直感）、岩神としての力を究めた求道の体現者（高求道）。","en":"Zero emotional aggression (low aggression), uses his power to protect the Traveler and allies (high altruism), operates within contract-based order (high cooperation), follows knowledge and principle over instinct (low intuition), and embodies mastery as a perfected Geo Archon (high mastery)."},"url":"https://ja.wikipedia.org/wiki/原神"},{"name":"シロナ","game":"ポケモンDPt","description":{"ja":"ポケモンの遺跡や伝説を深く研究しながら、圧倒的な強さを持つシンオウ地方のチャンピオン。柔らかな笑顔と鋭い洞察を兼ね備え、プレイヤーの成長を静かに見守る。","en":"Champion of the Sinnoh region, combining overwhelming strength with deep research into Pokémon ruins and legends. Her gentle smile and sharp insight coexist perfectly as she quietly watches over the player\'s growth."},"reasoning":{"ja":"戦いに積極的ではなく（低攻撃）、チャンピオンとして次世代を育てる利他性と（高利他）、チームでの連携を重視し（高協調）、感情より知識と分析で行動し（低直感）、ポケモン研究と戦いの両面で極みを目指す（高求道）。","en":"Not driven by aggression (low aggression), nurtures the next generation as Champion (high altruism + high cooperation), acts through knowledge and analysis rather than gut instinct (low intuition), and pursues mastery in both Pokémon research and battle (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_ダイヤモンド・パール"},{"name":"シュルク","game":"ゼノブレイド","description":{"ja":"モナドを手にした少年は、仲間の死という悲劇から旅立った。未来を「見る力」を持ちながら、その運命を変えようと仲間と共に戦い続ける。知性と戦略で戦場を制する、稀有な剣士。","en":"A boy who set out on his journey from the tragedy of losing his companions after grasping the Monado. Despite having the power to \'see\' the future, he fights alongside his allies to change that fate. A rare swordsman who controls the battlefield through intellect and strategy."},"reasoning":{"ja":"冷静で計算的な戦い方（低攻撃・低直感）、仲間を守るために未来を変えようとする強い利他性（高利他）、チームで作戦を立て動く協調性（高協調）、モナドを使いこなす剣士の求道精神（高求道）。","en":"Calm, calculated fighting style (low aggression + low intuition), strong altruism that drives him to change the future to protect allies (high altruism + high cooperation), and the relentless drive to master the Monado as a swordsman (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ゼノブレイド"},{"name":"ダイゴ","game":"ポケモンRSE","description":{"ja":"石の研究者にしてホウエンのチャンピオン。ポケモンの美しさを「石」に見出し、強さより調和を重んじる異色の王者。穏やかで知的だが、その強さは本物だ。","en":"A stone researcher and Champion of Hoenn. He finds the beauty of Pokémon in \'stones,\' valuing harmony over raw strength — an unconventional champion. Calm and intellectual, but his power is the real thing."},"reasoning":{"ja":"直接的な攻撃性よりも共存を重んじ（低攻撃）、ポケモンと共にあることを生き方にする利他的な姿勢（高利他）、チャンピオンとしての責任感（高協調）、感情より美学と分析で動き（低直感）、チャンピオンと研究者の二道を極める（高求道）。","en":"Values coexistence over direct aggression (low aggression), treats living with Pokémon as his philosophy (high altruism + high cooperation), operates through aesthetics and analysis over instinct (low intuition), and pursues mastery as both Champion and researcher (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_ルビー・サファイア"},{"name":"オモダカ","game":"ポケモンSV","description":{"ja":"パルデア地方のポケモンリーグ委員長にしてトップチャンピオン。静かな口調の裏に巨大な意志を持ち、ポケモンリーグの秩序を守る。穏やかでありながら圧倒的な強さを秘めた、パルデアの頂点に立つ存在。","en":"The Pokémon League Chairwoman and Top Champion of the Paldea region. Behind a quiet demeanor lies an enormous will, maintaining the order of the Pokémon League. Gentle yet harboring overwhelming strength — the figure who stands at Paldea\'s summit."},"reasoning":{"ja":"暴力的な手段を選ばず（低攻撃）、ポケモンリーグの秩序を守るための強い意志（高利他的信念）、組織と他者を巻き込み計画する協調性（高協調）、感情より計算と確信で行動し（低直感）、委員長とトップチャンピオンの双方で極みを目指す（高求道）。","en":"Avoids violent means (low aggression), moves with strong conviction to protect the League\'s order (high altruism-aligned resolve), plans by drawing in others and organizations (high cooperation), acts through calculation and certainty over emotion (low intuition), and pursues mastery as both Chairwoman and Top Champion (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_スカーレット・バイオレット"},{"name":"ラウル","game":"ゼルダの伝説 OoT","description":{"ja":"光の賢者にして、聖地の光の神殿を守る古の賢者。7年の眠りから覚めたリンクに光のメダリオンを授け、ガノンドロフとの戦いへ導いた。自らは戦場に出ず、知恵と経験でリンクの旅を支える。静かな使命感の中に、深い愛情が宿っている。","en":"The Sage of Light who guards the Temple of Light within the Sacred Realm. He bestowed the Light Medallion upon Link after his seven-year slumber and guided him toward the battle against Ganondorf. He never takes the field himself, supporting Link\'s journey through wisdom and experience. Deep affection dwells within his quiet sense of mission."},"reasoning":{"ja":"自ら戦わず若者を支援する（低攻撃・高利他）、リンクと賢者たちの使命に協力する協調性（高協調）、感情より長年の知恵と経験で動き（低直感）、光の賢者としての使命を果たし続ける求道性（高求道）。","en":"Supports the young without fighting himself (low aggression + high altruism), cooperates in Link and the Sages\' mission (high cooperation), acts through accumulated wisdom and experience rather than emotion (low intuition), and fulfills his unbroken duty as the Sage of Light (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_時のオカリナ"},{"name":"オタコン","game":"Metal Gear Solid","description":{"ja":"オタクでエンジニアの天才、そして「フォックスハウンド」の良心。スネークに無制限の技術支援を与え、影から作戦を支え続ける。涙もろいが、その信念の強さは本物だ。","en":"An otaku engineering genius and the conscience of FOXHOUND. He provides Snake with unlimited technical support, sustaining operations from the shadows. Prone to tears, but the strength of his conviction is genuine."},"reasoning":{"ja":"戦闘を避け技術で支援し（低攻撃）、スネークや世界の平和のために全力を尽くす（高利他・高協調）、直感より徹底した技術分析と計算で動き（低直感）、エンジニアとしての技術を磨き続ける求道者（高求道）。","en":"Avoids combat and provides support through technology (low aggression), gives everything for Snake and world peace (high altruism + high cooperation), operates through meticulous technical analysis rather than gut feeling (low intuition), and embodies the relentless pursuit of engineering mastery (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ハル・エメリッヒ"},{"name":"カズヒラ・ミラー","game":"Metal Gear Solid V","description":{"ja":"マザーベースの参謀長として、スネークの傍らで戦略を司る男。復讐の炎を胸に秘めながら、ダイヤモンド・ドッグズのために計算し続ける。感情を見せないが、その憎悪は誰より深い。","en":"The XO of Mother Base, commanding strategy at Snake\'s side. He keeps a flame of vengeance burning in his chest while calculating relentlessly for Diamond Dogs. He shows no emotion, but his hatred runs deeper than anyone\'s."},"reasoning":{"ja":"前線に出ず後方から指揮し（低攻撃）、仲間の復讐のために全てを捧げ（高利他）、組織として動く協調性の体現者（高協調）、感情ではなく計算と戦略で全てを判断し（低直感）、傭兵組織のプロとして求道的に動く（高求道）。","en":"Commands from the rear without taking the front line (low aggression), devotes everything for the vengeance of his comrades (high altruism + high cooperation), embodies organizational cooperation (high cooperation), judges everything through calculation and strategy rather than feeling (low intuition), and operates with professional mastery as a mercenary commander (high mastery)."},"url":"https://ja.wikipedia.org/wiki/カズヒラ・ミラー"}],"description":{"ja":"慎重に、仲間のために、計算し、美学を持って戦う。お前は後方から全てを見通す指揮官だ。華やかな前線は任せる。お前の仕事は、誰よりも正確に判断を下すこと。","en":"Cautious, for your allies, calculated, with aesthetics. You\'re the commander who sees everything from the rear. Leave the flashy frontline to others. Your job is making the most accurate calls."},"deepDescription":{"ja":"ストア哲学の実践者。感情に流されず、理性によって状況を制御する。「変えられないものを受け入れ、変えられるものを変える」。","en":"Stoic philosopher in practice — controlling situations through reason, not emotion. \'Accept what you cannot change, change what you can.\'"},"recommendedGames":["Overwatch 2 (Ana)","FF10","Civilization VI"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"low","mastery":"high"},"characterDescription":{"ja":"元オーバーウォッチの精鋭スナイパーにして、娘ファラを持つ母。片目を失いながらも復帰し、後方から仲間を癒し敵を抑制する。慎重な狙撃と的確な判断で、チームの生命線となる鉄壁の参謀。","en":"A former elite sniper of Overwatch and mother to Pharah. Despite losing an eye, she returned to support her team from the backline — healing allies and suppressing enemies. Her cautious marksmanship and precise judgment make her the team\'s lifeline."},"characterReasoning":{"ja":"攻撃性は抑えられた後方支援型（低攻撃）、仲間を守り癒すことに全力を尽くす利他性（高利他）、チームの連携を重視する協調性（高協調）、感情より経験と計算に基づく冷静な狙撃（低直感）、スナイパーとしての技術の極みを追い続ける（高求道）。","en":"Restrained aggression as a backline support (low aggression), devotes everything to healing and protecting allies (high altruism + high cooperation), relies on experience and calculation over emotion (low intuition), and relentlessly hones her sniping craft to its peak (high mastery)."}},{"id":"LHHLL","name":{"ja":"盾の守人","en":"The Shield Bearer"},"character":"ジル・バレンタイン","characterGame":"バイオハザード","characterUrl":"https://en.wikipedia.org/wiki/Jill_Valentine","additionalCharacters":[{"name":"マシュ・キリエライト","game":"Fate/Grand Order","description":{"ja":"デミ・サーヴァントとして円卓の騎士ギャラハッドの霊基を宿した少女。主人公を守ることだけに全力を捧げ、自らの命の意味を問いながら前に進む。その純粋な献身は、誰の心にも刺さる。","en":"A girl who carries the Saint Graph of the Knight of the Round Table, Galahad, as a Demi-Servant. She devotes everything to protecting the protagonist while pressing forward, questioning the meaning of her own life. Her pure devotion pierces every heart."},"reasoning":{"ja":"攻撃より守護に特化し（低攻撃）、主人公と人類のために命を懸ける（高利他・高協調）、感情より使命感で動き（低直感）、求道より今この瞬間を守ることに徹する（低求道）。","en":"Specialized in protection over attack (low aggression), stakes her life for the protagonist and humanity (high altruism + high cooperation), acts from mission rather than instinct (low intuition), and dedicates herself to protecting this very moment rather than long-term mastery (low mastery)."},"url":"https://ja.wikipedia.org/wiki/マシュ・キリエライト"},{"name":"ピーチ姫","game":"スーパーマリオ","description":{"ja":"何度さらわれても、マリオたちへの信頼を失わないキノコ王国の姫。優しさと包容力でみんなを支え、パーティーを開いてはみんなを笑顔にする。その存在そのものが、仲間の力になる。","en":"The princess of the Mushroom Kingdom who never loses faith in Mario and her friends, no matter how many times she is captured. She supports everyone with kindness and warmth, throwing parties and filling faces with smiles. Her very presence empowers her companions."},"reasoning":{"ja":"戦闘を行わず人を包む存在（低攻撃）、マリオたちを支え続ける利他性（高利他）、仲間との絆を軸に行動する（高協調）、感情より優しさと直感的行動のバランス（低直感）、極みを目指すというより今を大切にする姿勢（低求道）。","en":"Exists to embrace others rather than fight (low aggression), sustains her companions with consistent altruism (high altruism + high cooperation), acts from warmth rather than strategic instinct (low intuition), and cherishes the present moment rather than pursuing mastery (low mastery)."},"url":"https://ja.wikipedia.org/wiki/ピーチ_(ゲームキャラクター)"},{"name":"ルイージ","game":"スーパーマリオ","description":{"ja":"兄の影に生きることに慣れた、心優しい緑の男。怖がりだけど、大切な人のためなら幽霊屋敷にだって飛び込んでいく。臆病と勇気が同居する、等身大のヒーローだ。","en":"The kind-hearted man in green, accustomed to living in his brother\'s shadow. Easily frightened, but he will plunge into a haunted mansion for those he loves. A relatable hero in whom timidity and courage coexist."},"reasoning":{"ja":"積極的な攻撃性はなく（低攻撃）、マリオや友人を助けるために立ち上がる強い利他性（高利他）、兄や仲間と共に行動する協調性（高協調）、計算より感情と優しさで動き（低直感）、熟達より誠実さを優先する（低求道）。","en":"No active aggression (low aggression), rises to help Mario and friends through strong altruism (high altruism + high cooperation), acts with kindness and feeling over calculation (low intuition), and prioritizes sincerity over relentless self-improvement (low mastery)."},"url":"https://ja.wikipedia.org/wiki/ルイージ"}],"description":{"ja":"冷静沈着。人を守ることに誇りを持ち、パートナーシップを重視する。分析力に優れ、効率的に動く。美学は求めない。ただ、秩序と安全を守ることが使命だ。","en":"Cool and composed. You take pride in protecting others and value partnership. Excellent analytical skills, efficient movement. No pursuit of aesthetics. Your mission is simply to maintain order and safety."},"deepDescription":{"ja":"社会契約論の実践者。個人の自由より、秩序と安全を重視する。ルソーの「一般意志」に従う。","en":"Social contract theorist in practice — valuing order and safety over individual freedom. Following Rousseau\'s \'general will.\'"},"recommendedGames":["バイオハザード RE:3","Fate/Grand Order","Rainbow Six Siege"],"axes":{"aggression":"low","altruism":"high","cooperation":"high","intuition":"low","mastery":"low"}},{"id":"LHLHH","name":{"ja":"放浪の賢者","en":"The Wandering Sage"},"character":"リンク","characterGame":"ゼルダの伝説: ブレスオブザワイルド","characterUrl":"https://ja.wikipedia.org/wiki/リンク_(ゲームキャラクター)","additionalCharacters":[{"name":"ワンダ","game":"ワンダと巨像","description":{"ja":"愛する少女を生き返らせるために、16体の巨像を一人で討つことを選んだ若者。言葉は少なく、ただ剣を握り馬を駆る。その孤独な旅に、最初から「正しさ」などない。","en":"A young man who chose to slay sixteen colossi alone to resurrect the girl he loved. Few words — he simply grips his sword and rides his horse. From the beginning, there is no \'righteousness\' in that solitary journey."},"reasoning":{"ja":"戦うことを望まないが愛のために戦い（低攻撃・高利他）、誰とも協力せず単独で旅し（低協調）、直感と感情だけを頼りに巨像に挑み（高直感）、剣士として究極の試練を乗り越え続ける（高求道）。","en":"Fights not out of desire but out of love (low aggression + high altruism), journeys entirely alone without allies (low cooperation), challenges each colossus on pure instinct and emotion (high intuition), and endures ultimate trials as a swordsman without relent (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ワンダと巨像"},{"name":"イコ","game":"ICO","description":{"ja":"角を持つ少年は、呪われた城に生贄として捧げられた。出会った少女ヨルダの手を放さず、言葉も通じないまま共に逃げ続ける。その純粋な守りたいという意志が全てだ。","en":"A boy with horns, offered as a sacrifice to a cursed castle. He never lets go of the girl Yorda\'s hand, fleeing together without even a common language. The pure will to protect is everything."},"reasoning":{"ja":"戦いを好まず必要最低限の防御のみ行い（低攻撃）、ヨルダを守ることだけのために全力を尽くす（高利他）、誰の助けも借りず二人きりで旅し（低協調）、直感と感情で動き（高直感）、限界を超えて強くなろうとする少年の気概（高求道）。","en":"Fights only defensively and as a last resort (low aggression), devotes everything solely to protecting Yorda (high altruism), travels as a pair without any outside help (low cooperation), moves on pure instinct and emotion (high intuition), and drives himself beyond his limits with a boy\'s fierce determination (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ICO"}],"description":{"ja":"慎重で仲間思い、でも一人で旅する。直感と美学に従い、世界を探索する。お前は答えを探しているのではない。問いそのものを楽しんでいるのだ。","en":"Cautious and caring, but traveling alone. Following intuition and aesthetics, exploring the world. You\'re not searching for answers — you\'re enjoying the questions themselves."},"deepDescription":{"ja":"ソクラテスの「無知の知」。知らないことを知っている者こそ最も賢い。探求の旅に終わりはない。","en":"Socratic \'knowing that you don\'t know\' — the wisest are those who know their own ignorance. The journey of inquiry never ends."},"recommendedGames":["ゼルダの伝説 TotK","Outer Wilds","Elden Ring"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"high","mastery":"high"},"characterDescription":{"ja":"記憶を失って、それでも正しいことをし続けた。一人で広大なハイラルを歩き、出会った全ての命を救う。","en":"Memory gone, yet he kept doing what was right. Alone across vast Hyrule, saving every life he encountered."},"characterReasoning":{"ja":"単独行動（低協調）で旅しながら、出会う全ての者を助ける高利他性と直感的行動力、剣士としての求道性がこのタイプの三軸。","en":"Solo travel (low cooperation) while helping every being he meets—high altruism, intuitive action, and swordsman\'s mastery form the three axes of this type."}},{"id":"LHLHL","name":{"ja":"夢見る旅人","en":"The Dreaming Traveler"},"character":"カービィ","characterGame":"星のカービィ","characterUrl":"https://ja.wikipedia.org/wiki/星のカービィ","additionalCharacters":[{"name":"クラウド","game":"FF7","description":{"ja":"傭兵として生きるふりをしていた、傷ついた少年の残影。仮面の下に正体不明の過去を抱えながら、気づけば仲間のために剣を抜いていた。ツンデレでも、その優しさは本物だ。","en":"The remnant of a wounded boy pretending to live as a mercenary. He carries an obscured past beneath his facade, and before he knows it, he is drawing his sword for his companions. Prickly on the surface, but the kindness underneath is real."},"reasoning":{"ja":"喧嘩腰に見えて本質的に攻撃的ではなく（低攻撃）、仲間を守るために戦う利他性（高利他）、組織より個人として動き（低協調）、直感と本能で動く戦闘スタイル（高直感）、強さにこだわらず「守れればいい」という姿勢（低求道）。","en":"Appears combative but is not fundamentally aggressive (low aggression), fights out of altruism to protect companions (high altruism), acts as an individual rather than part of a system (low cooperation), operates on instinct and gut feeling in battle (high intuition), and holds an attitude of \'protecting is enough\' rather than pursuing greater power (low mastery)."},"url":"https://ja.wikipedia.org/wiki/クラウド・ストライフ"}],"description":{"ja":"攻撃的ではない。友達を助けるために旅に出る。基本は一人。完全に直感と本能で動く。美学を追い求めることはない。ただ、目の前の大切なもののために、自然体で歩く。","en":"Not aggressive. You set out to help friends. Basically solo. Driven entirely by instinct and gut feeling. No pursuit of aesthetics. You simply walk naturally for what matters right in front of you."},"deepDescription":{"ja":"荘子の「逍遥遊」。何にも縛られず、あるがままに遊ぶ。無為自然こそが最高の生き方。","en":"Zhuangzi\'s \'Free and Easy Wandering\' — unbound by anything, playing as things are. Wu wei is the highest way of living."},"recommendedGames":["星のカービィ ディスカバリー","FF7 Rebirth","Sky: Children of the Light"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"high","mastery":"low"},"characterDescription":{"ja":"ふわふわ飛んで、何でも吸い込んで、気づいたら世界を救っていた。深く考えない、それが最大の強さ。","en":"Floating along, inhaling everything, and saving the world before he knows it. Not thinking too hard—that is the greatest strength."},"characterReasoning":{"ja":"低攻撃性・低求道性で純粋な直感のまま旅し、出会った者を自然に助ける高利他性がこのタイプの本質と完全に合致する。","en":"Low aggression and low mastery, traveling purely on instinct and naturally helping those he meets—his high altruism perfectly matches this type\'s essence."}},{"id":"LHLLH","name":{"ja":"理想の残骸","en":"The Remnant of Ideals"},"character":"エミヤ","characterGame":"Fate/stay night","characterUrl":"https://ja.wikipedia.org/wiki/衛宮士郎","additionalCharacters":[{"name":"アルカード","game":"悪魔城ドラキュラ","description":{"ja":"ドラキュラの息子でありながら、人類を守るために父に刃を向けた半人半吸血鬼。孤独を選び、誰とも深く関わらず、ただ人の世に害をなさないために戦う。その美学は、静寂の中の孤高だ。","en":"A half-human, half-vampire who turned his blade on his own father, Dracula, to protect humanity. He chooses solitude, avoids deep bonds with anyone, and fights solely to prevent harm to the human world. His aesthetic is solitary nobility within silence."},"reasoning":{"ja":"積極的に戦いを求めず（低攻撃）、人類のために父を倒す極限の利他性（高利他）、誰とも組まず孤独に行動し（低協調）、感情より冷静な計算で行動し（低直感）、剣と魔法を極めた求道の化身（高求道）。","en":"Does not seek combat proactively (low aggression), embodies ultimate altruism by killing his own father for humanity (high altruism), acts in complete solitude without allies (low cooperation), moves through cool calculation rather than passion (low intuition), and is the incarnation of mastery in sword and sorcery (high mastery)."},"url":"https://ja.wikipedia.org/wiki/アルカード_(悪魔城ドラキュラ)"}],"description":{"ja":"皮肉屋だが本質は優しい。「正義の味方」の理想を追い、一人で全てを背負い込む。冷静に分析し、経験に基づいて動く。理想の追求と、その挫折の痛みを知る者。お前の美学は、折れた剣にこそ宿る。","en":"Cynical but kind at heart. Chasing the ideal of \'a hero of justice,\' shouldering everything alone. Moving by cold analysis and experience. You know the pain of pursuing ideals and their collapse. Your aesthetics live in the broken blade."},"deepDescription":{"ja":"キルケゴールの実存的苦悩。「あれか、これか」の選択の中で、自分自身と向き合い続ける。","en":"Kierkegaard\'s existential anguish — continuously facing yourself within the \'Either/Or\' of choice."},"recommendedGames":["Fate/stay night","悪魔城ドラキュラX 月下の夜想曲","The Last of Us Part II"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"low","mastery":"high"},"characterDescription":{"ja":"英雄になりたかった少年が、理想を信じ続けた末に「道具」になった。全てを犠牲にして他者を守り続ける、壊れた守護者。","en":"A boy who wanted to be a hero, who believed in his ideal until he became a \'tool.\' A broken guardian who sacrificed everything to protect others forever."},"characterReasoning":{"ja":"高利他性のために孤独（低協調）を選び、計算的に自己を削りながら求道的に「正義の味方」を追い求めた悲劇的完璧主義者。","en":"He chose solitude (low cooperation) for high altruism, calculatingly eroding himself while pursuing \'hero of justice\' with mastery—a tragic perfectionist."}},{"id":"LHLLL","name":{"ja":"静かな番人","en":"The Quiet Warden"},"character":"ジョエル","characterGame":"The Last of Us","characterUrl":"https://dic.nicovideo.jp/a/%E3%82%B8%E3%83%A7%E3%82%A8%E3%83%AB%EF%BC%88The%20Last%20of%20Us%EF%BC%89","additionalCharacters":[{"name":"結城理","game":"ペルソナ3","description":{"ja":"10年前に両親を失った少年は、死に無関心なまま特別課外活動部に加わった。仲間と過ごすうちに何かが変わり始める。感情を表に出さないが、最後の選択が全てを語る。","en":"A boy who lost his parents ten years ago, joining SEES with an indifference toward death. Something begins to change as he spends time with his companions. He rarely shows emotion, but his final choice says everything."},"reasoning":{"ja":"戦いに感情的な熱意を持たず（低攻撃）、仲間のために命を捧げる利他性（高利他）、孤独に運命を背負い（低協調）、直感より諦観と静けさで動き（低直感）、「守護者」としての求道より静かな受容（低求道）。","en":"No emotional drive for combat (low aggression), sacrifices his life for his companions (high altruism), bears his fate in solitude (low cooperation), moves through resignation and stillness rather than instinct (low intuition), and quietly accepts rather than relentlessly pursuing mastery as a guardian (low mastery)."},"url":"https://ja.wikipedia.org/wiki/ペルソナ3"}],"description":{"ja":"慎重で、大切な人のためだけに動く。一人で、冷静に、効率的に。美学は持たない。ただ、守るべきものを守るために、必要なことだけをする。","en":"Cautious, moving only for those you cherish. Alone, calm, efficient. No aesthetics. Simply doing what\'s necessary to protect what matters."},"deepDescription":{"ja":"ショーペンハウアーの意志論。世界は苦しみに満ちている。その中で唯一の救いは、大切な者への無条件の愛。","en":"Schopenhauer\'s theory of will — the world is full of suffering. The only salvation is unconditional love for those dear to you."},"recommendedGames":["The Last of Us","God of War (2018)","ペルソナ3 Reload"],"axes":{"aggression":"low","altruism":"high","cooperation":"low","intuition":"low","mastery":"low"},"characterDescription":{"ja":"娘を失った男が、もう一人の娘を見つけた。言葉も武器も最小限に、ただそばにいることで守り続ける。","en":"A man who lost his daughter found another one. Minimal words, minimal weapons—he protects simply by staying close."},"characterReasoning":{"ja":"攻撃性・計算性・求道性のいずれも低く、孤独な守護者としての高利他性がエリーへの静かな献身に全て集約される。","en":"Low aggression, calculation, and mastery—all compressed into the high altruism of a solitary guardian, concentrated entirely in quiet devotion to Ellie."}},{"id":"LLHHH","name":{"ja":"影の指揮者","en":"The Shadow Conductor"},"character":"クロード","characterGame":"FE風花雪月","characterUrl":"https://ja.wikipedia.org/wiki/ファイアーエムブレム_風花雪月","additionalCharacters":[{"name":"リーバル","game":"ゼルダの伝説 BotW","description":{"ja":"リトの英傑にして、神獣ヴァ・メドーを操る弓の天才。プライドが高くリンクを目の敵にしながら、ゼルダとハイラルへの忠誠は本物だった。嫉妬と献身が混在した、複雑な英雄。","en":"Champion of the Rito and a genius archer who pilots Divine Beast Vah Medoh. He holds a proud rivalry with Link, yet his loyalty to Zelda and Hyrule is genuine. A complex hero in whom jealousy and devotion coexist."},"reasoning":{"ja":"直接的な攻撃性を好まない弓使い（低攻撃）、ゼルダとハイラルを守る使命に従い（低利他・使命感）、神獣操縦という組織的役割を担い（高協調）、直感と才能で戦況を読み（高直感）、弓の技術の頂点を目指す求道者（高求道）。","en":"An archer who prefers not to engage directly (low aggression), driven by mission to protect Zelda and Hyrule rather than purely selfless feeling (low altruism with duty), fulfills an organizational role as a Divine Beast pilot (high cooperation), reads the battlefield through instinct and innate talent (high intuition), and pursues the pinnacle of archery craft (high mastery)."},"url":"https://ja.wikipedia.org/wiki/ゼルダの伝説_ブレス_オブ_ザ_ワイルド"}],"description":{"ja":"正面から戦うなんて愚か者のすることだ。お前は裏で糸を引き、チームを使い、直感で人を読む。表の顔は気さくな弓使い、裏の顔は野望を秘めた策略家。その美学は、誰にも本心を見せないことだ。","en":"Only fools fight head-on. You pull strings from behind, use the team, and read people by instinct. Your public face: a friendly archer. Your hidden face: a schemer with ambitions. Your aesthetics lie in never showing your true self."},"deepDescription":{"ja":"プラトンの哲人王。真に賢い者が支配すべきという思想。民衆は知らなくていい。お前だけが全体像を見ている。","en":"Plato\'s Philosopher King — the truly wise should rule. The masses need not know. Only you see the full picture."},"recommendedGames":["FE風花雪月","Assassin\'s Creed","ゼルダの伝説 BotW"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"high","mastery":"high"},"characterDescription":{"ja":"笑顔で全員を操る知略家。チームを使って自分の夢を実現する——でも、その夢は意外と世界を救う方向を向いている。","en":"A tactician who moves everyone with a smile. He uses the team to realize his dream—but that dream, surprisingly, points toward saving the world."},"characterReasoning":{"ja":"低攻撃性で表舞台を避けながら、高い直感と求道的計略でチームを操る。利己的に見えても最終目標は共存という特異な低利他・高協調タイプ。","en":"Low aggression, avoiding the spotlight while orchestrating the team through intuition and masterful scheming. Appears selfish, but ultimate goal is coexistence—a unique low-altruism, high-cooperation type."}},{"id":"LLHHL","name":{"ja":"道化師の仮面","en":"The Jester\'s Mask"},"character":"ミラージュ","characterGame":"Apex Legends","characterUrl":"https://dic.nicovideo.jp/a/Apex%20Legends","additionalCharacters":[{"name":"ヴァン","game":"FF12","description":{"ja":"ラバナスタの街で生きる孤児の少年から時代の渦に巻き込まれた、ありふれた若者。英雄でも賢者でもないが、持ち前の直感と軽さで大国の謀略を潜り抜ける。自分が何者かを探しながら旅する、成長の物語の主人公。","en":"An orphaned street kid from Rabanastre swept into the currents of the age. Neither hero nor sage, he slips through the schemes of great powers on instinct and lightness. A protagonist still searching for who he is while the journey shapes him."},"reasoning":{"ja":"喧嘩っ早いが本質的に大きな攻撃性はなく（低攻撃）、仲間を利用するというより共に動く自己中心性（低利他）、バルフレアたちとの旅の中で協調して動き（高協調）、感情と直感で状況を乗り越え（高直感）、確たる目標も技術追求もなく流れに身を任せる（低求道）。","en":"Hot-headed but without fundamental aggression (low aggression), self-centered in moving alongside companions rather than for them (low altruism), cooperates within the journey with Balthier and others (high cooperation), overcomes situations on emotion and instinct (high intuition), and drifts without firm goals or technical ambition (low mastery)."},"url":"https://ja.wikipedia.org/wiki/ファイナルファンタジーXII"},{"name":"モルガナ","game":"ペルソナ5","description":{"ja":"自分を猫だと思い込むことを拒絶する謎の生き物。怪盗団のリーダー気取りで仕切りたがりながら、実は一番みんなのことを考えている。プライドと仲間愛が入り混じった、不思議な参謀だ。","en":"A mysterious creature who refuses to accept being called a cat. He acts as self-appointed leader of the Phantom Thieves while actually being the one who thinks most about everyone else. A peculiar strategist in whom pride and camaraderie intermingle."},"reasoning":{"ja":"直接戦闘より情報とサポートで貢献し（低攻撃）、自己利益優先に見えて怪盗団への貢献欲求は本物（低利他・チーム動機）、チームの連携を重視する高い協調性（高協調）、直感で状況を読み先を読む（高直感）、「怪盗の頭領」という目標はあっても具体的な求道性は低い（低求道）。","en":"Contributes through information and support rather than direct combat (low aggression), appears self-serving yet his drive to help the Phantom Thieves is genuine (low altruism + team motivation), highly values team coordination (high cooperation), reads situations and reads ahead on instinct (high intuition), and holds the aspiration of \'master thief\' without concrete commitment to disciplined mastery (low mastery)."},"url":"https://ja.wikipedia.org/wiki/モルガナ_(ペルソナ5)"}],"description":{"ja":"正面から勝負するより騙す。注目されたい欲求がお前を動かす。チームのムードメーカーだが、その裏には家族の喪失を埋めたい孤独がある。即興のホログラムのように、お前の本心は誰にも見せない。","en":"Rather than fight head-on, you deceive. The craving for attention drives you. Team\'s mood maker, but behind it lies loneliness from family loss. Like your improvised holograms, you never show your true self."},"deepDescription":{"ja":"アリストテレスの「人間は社会的動物」。ただし、お前の場合は社会を利用する動物。共同体の中で自己利益を最大化する知恵。","en":"Aristotle\'s \'man is a social animal\' — except in your case, an animal that exploits society. The wisdom of maximizing self-interest within the community."},"recommendedGames":["Apex Legends","Among Us","Dota 2"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"high","mastery":"low"},"characterDescription":{"ja":"ホログラムで敵を翻弄しながら、口から出まかせでチームを笑わせる男。道化のふりして、実は誰より状況を読んでいる。笑いは彼の鎧だ。","en":"He floods the map with decoys, runs his mouth to keep the squad laughing, and then reads the entire situation before anyone else. The clown act is armor — underneath is the sharpest eye in the room."},"characterReasoning":{"ja":"自分の命より「場の空気」を優先する低攻撃性と低利他性の絶妙なバランス。デコイ戦術という純粋な直感プレイが求道心のなさを体現し、チームのムードメーカーとして協調性は高い。","en":"His low aggression and low altruism create a character who fights for laughs more than glory. Decoy tactics are pure intuition — no calculated mastery, just vibes — yet he\'s fundamentally a team player who keeps the mood alive."}},{"id":"LLHLH","name":{"ja":"帝国の建設者","en":"The Empire Builder"},"character":"たぬきち","characterGame":"どうぶつの森","characterUrl":"https://dic.nicovideo.jp/a/%E3%81%9F%E3%81%AC%E3%81%8D%E3%81%A1","additionalCharacters":[{"name":"オルゴ・デミーラ","game":"ドラゴンクエスト7","description":{"ja":"神を欺き人間の信仰心そのものを消滅させることで世界を支配した魔王。直接手を下すより「神殿を石に変え、島ごと孤立させる」制度的支配を好む。感情的な怒りではなく、冷静な長期戦略で人類を絶望させる帝国設計者。","en":"A demon lord who conquered the world not through brute force but by erasing humanity\'s faith — turning temples to stone, isolating islands one by one. His dominion is architectural, not emotional: a cold long-game empire designed to reduce mankind to despair without a single unnecessary battle."},"reasoning":{"ja":"直接戦闘より制度と計画で世界を封じる低攻撃性・低利他性の支配者。魔族全体を組織化して動かす高協調性と、何十年もかけた帝国建設への高い求道心が「帝国の建設者」そのものだ。","en":"Controls the world through systemic isolation rather than direct combat — low aggression, zero altruism. His coordination of the entire demon hierarchy (high cooperation) combined with the decades-long architectural patience of his conquest (high mastery) defines the Empire Builder archetype."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストVII_エデンの戦士たち"},{"name":"ウルノーガ","game":"ドラゴンクエスト11","description":{"ja":"デルカダール王に取り憑き、国家を内部から掌握して世界征服の計画を着々と実行した暗黒の存在。王に成り代わって国家を支配し、世界樹を破壊するという計画を長年かけて完遂する。感情より計算、暴力より制度を選ぶ冷徹な帝国設計者。","en":"A dark entity who possessed the King of Delcadar, seizing the nation from within and patiently executing a world conquest plan across years. He usurped a kingdom from the shadows, orchestrated the World Tree\'s destruction, and bent civilization to his design — calculation over emotion, institution over brute force."},"reasoning":{"ja":"王に取り憑いて国家を乗っ取り長期計画を実行する手法は低攻撃性の計算型支配者の典型。魔族と人間を組織化する高協調性、長年かけて計画を完遂する高求道心が軸に刻まれている。","en":"Possessing a king to seize a nation from within and executing a long-term plan marks the low-aggression, calculation-first ruler. His ability to coordinate both demon and human factions (high cooperation) and his relentless long-term execution (high mastery) are the signature axes."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストXI_過ぎ去りし時を求めて"}],"description":{"ja":"慎重に、計算し、コミュニティを動かし、完璧な島を作り上げる。利他に見えるが、全ての道はベルに通じる。お前は優しい笑顔の裏で、帝国を築くビジネスの天才だ。","en":"Cautious, calculated, moving the community, building the perfect island. Looks altruistic, but every road leads to Bells. Behind that gentle smile, you\'re a business genius building an empire."},"deepDescription":{"ja":"ライプニッツの最善世界論。この世界をより良いシステムに作り変えるという信念。秩序こそが美。ただし、その秩序の頂点にはお前がいる。","en":"Leibniz\'s best of all possible worlds — the conviction to remake this world into a better system. Order is beauty. But you sit at the top of that order."},"recommendedGames":["あつまれ どうぶつの森","Stardew Valley","Cities: Skylines"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"low","mastery":"high"},"characterDescription":{"ja":"笑顔の裏に完璧なビジネスモデルが隠れている。無利子・審査なしの住宅ローンは慈善ではなく、島全体を支配するための緻密な設計だ。","en":"Behind that friendly grin is a perfectly engineered business model. Interest-free loans with no credit check aren\'t charity — they\'re the architecture of total island control."},"characterReasoning":{"ja":"暴力を使わず「経済と制度」で島民を掌握する低攻撃性・低利他性の支配者。インフラを計画的に整備する計算型の高い求道心と、住民全員を動かす組織力（高協調性）の組み合わせが「帝国の建設者」そのものだ。","en":"Controls the whole island without a single act of aggression — pure systemic domination. His meticulous infrastructure planning is calculation over intuition, and his ability to mobilize every resident makes him the definitive empire-builder."}},{"id":"LLHLL","name":{"ja":"鉄面の支配者","en":"The Iron Ruler"},"character":"サカキ","characterGame":"ポケモン赤緑","characterUrl":"https://dic.nicovideo.jp/a/%E3%82%B5%E3%82%AB%E3%82%AD(%E3%83%9D%E3%82%B1%E3%83%A2%E3%83%B3)","additionalCharacters":[{"name":"キングクルール","game":"ドンキーコング","description":{"ja":"クレムリン王国を統率するワニの王。バナナを強奪しドンキーコングを執拗に追い詰めるが、その動機は個人的な憎しみより「島全体の支配」という組織的野望だ。部下の軍団を指揮する統率力があるが、精緻な長期計画より目の前の権力維持を優先する。","en":"King of the Kremlings, ruler of a military organization bent on total island domination. He commands armies and steals bananas not out of personal rage but as a systematic power play. His organization-building is real, but his focus is immediate control rather than long-term architectural vision."},"reasoning":{"ja":"クレムリン軍団を指揮する高協調性の組織型支配者でありながら、バナナ略奪という直接行動への低衝動と組織運営への依存が低攻撃性・低求道心に反映される。感情より組織論で動く鉄面の支配者の典型だ。","en":"Commands a military hierarchy — high cooperation as an organizational ruler. His reliance on organizational systems rather than personal combat reflects low aggression, and his focus on holding power rather than perfecting a craft marks low mastery. Institutional control is his native language."},"url":"https://ja.wikipedia.org/wiki/キングクルール"},{"name":"Dr.ワイリー","game":"ロックマン","description":{"ja":"天才科学者でありながら世界征服という執念に憑かれた研究者。自らは戦わず、設計したロボットを部下として運用する。何度敗北しても懲りずに計画を立て直す異常な粘り強さと組織運営能力を持つが、求道心は世界支配という目的に従属している。","en":"A brilliant scientist possessed by the obsession of world domination. He never fights personally — he designs robots and deploys them as subordinates. His resilience in rebuilding plans after every defeat is extraordinary, and his organizational capacity is real, but his craft exists only to serve the end goal of control."},"reasoning":{"ja":"自ら戦わずロボット軍団を設計・指揮する低攻撃性の組織型支配者。科学的知識を権力奪取の道具とし（低求道心）、ロボット部隊の運用という高協調性の組織論で動く鉄面の支配者だ。","en":"Never engages directly — builds and commands robot armies instead, marking low aggression. His science is instrumental to domination rather than pursued as mastery for its own sake (low mastery). His entire framework is organizational deployment: high cooperation through systemic control."},"url":"https://ja.wikipedia.org/wiki/Dr.ワイリー"}],"description":{"ja":"表に出る必要はない。部下を動かし、計算し、結果だけを手にする。美学なんていらない。必要なのは金と権力だ。お前は組織という名の巨大なチェス盤を、誰よりも冷静に支配する。","en":"No need to step into the spotlight. Move your subordinates, calculate, and claim only the results. No aesthetics needed. All you need is money and power. You dominate the giant chessboard called \'organization\' more calmly than anyone."},"deepDescription":{"ja":"ベンサムの功利主義。「最大多数の最大幸福」をシステマティックに追求する。ただし、「最大多数」にはお前だけが含まれている。","en":"Bentham\'s utilitarianism — systematically pursuing \'the greatest happiness for the greatest number.\' Except \'the greatest number\' includes only you."},"recommendedGames":["ポケモン赤緑","龍が如く0","XCOM 2"],"axes":{"aggression":"low","altruism":"low","cooperation":"high","intuition":"low","mastery":"low"},"characterDescription":{"ja":"ロケット団を運営しながらジムリーダーも兼任する。感情を見せず、弁解もせず、ただ組織に最適な指令を下す。美学? そんなものはいらない。","en":"Runs a criminal empire and a gym simultaneously, shows no emotion, offers no justification. He gives orders. They get executed. Aesthetics are a waste of compute."},"characterReasoning":{"ja":"ポケモンを道具として扱い感傷を一切持ち込まない低利他性・低求道心の純粋な管理者。ロケット団という組織を動かす高い協調性は持ちながらも、直感ではなく利益計算で全ての意思決定を行う冷徹な計算型だ。","en":"Treats Pokémon as tools with zero sentiment — low altruism, zero mastery aesthetics. He runs Team Rocket through pure organizational efficiency, every decision profit-calculated, never intuitive. Management as a cold science."}},{"id":"LLLHH","name":{"ja":"虚無の芸術家","en":"The Nihilist Artist"},"character":"ジョーカー","characterGame":"ペルソナ5","characterUrl":"https://dic.nicovideo.jp/a/%E3%82%B8%E3%83%A7%E3%83%BC%E3%82%AB%E3%83%BC(%E3%83%9A%E3%83%AB%E3%82%BD%E3%83%8A5)","additionalCharacters":[{"name":"ヴィンセント","game":"FF7","description":{"ja":"かつてタークスの一員だった男が、自らの罪と向き合えず30年間棺の中で眠り続けた。贖罪の旅に出るが、仲間と感情を共有することを避け、自分の痛みを芸術的な孤独として抱える。変身能力という異形の力を持ちながら、それを誇ることもなく深淵の中に沈む。","en":"A former Turk who spent 30 years sealed in a coffin rather than face his own guilt. He joins the party\'s journey but keeps his emotions walled off, carrying his pain as a kind of solitary art. He wields monstrous transformation powers, but takes no pride in them — sinking quietly into his own abyss."},"reasoning":{"ja":"感情的表出を極力抑え孤独を選ぶ低協調性・低利他性の存在。直感的な変身能力（高直感）と贖罪という個人的美学への執着（高求道心）が、虚無の中に芸術を見出す「虚無の芸術家」の軸に重なる。","en":"Suppresses emotional expression and chooses isolation — low cooperation, low altruism. His instinctive transformation ability (high intuition) and obsessive devotion to personal atonement as an aesthetic code (high mastery) align precisely with the Nihilist Artist who finds art within the void."},"url":"https://ja.wikipedia.org/wiki/ヴィンセント・ヴァレンタイン"},{"name":"ホロウナイト","game":"Hollow Knight","description":{"ja":"虚無から生まれ、感染を封じるために選ばれた器。自らの意志も感情も持たないことを存在意義とされながら、その「空虚さ」を美学として体現する。言葉を持たず、仲間を作らず、ただ己の使命と向き合う深淵の存在。","en":"Born of the Void, chosen as a vessel to contain a plague — its entire purpose is to have no will, no emotion, no self. Yet that very emptiness becomes its aesthetic. No words, no allies, only the abyss and a sealed purpose that defines its existence."},"reasoning":{"ja":"意志と感情を持たないことを設計された存在であり低利他性・低協調性の極致。直感的な戦闘スタイル（高直感）と虚無そのものを体現する美学的完成度（高求道心）が「虚無の芸術家」の核心をなす。","en":"Designed to have no will or emotion — the absolute extreme of low altruism and low cooperation. Its instinctive combat style (high intuition) and the aesthetic perfection of embodying pure void itself (high mastery) form the core of the Nihilist Artist."},"url":"https://ja.wikipedia.org/wiki/Hollow_Knight"}],"description":{"ja":"慎重で、利己的で、孤独を選び、直感と美学に生きる。お前は世界に何も期待しない。だが、自分の美学だけは絶対に裏切らない。その矛盾こそがお前の芸術だ。","en":"Cautious, self-serving, choosing solitude, living by intuition and aesthetics. You expect nothing from the world. But you never betray your own aesthetics. That contradiction is your art."},"deepDescription":{"ja":"ニヒリズムを超えたニーチェの思想。虚無の中に自ら価値を創造する「永劫回帰」の肯定者。","en":"Beyond nihilism in Nietzsche\'s thought — an affirmer of \'eternal recurrence,\' creating value in the void."},"recommendedGames":["ペルソナ5 Royal","Hades","Hollow Knight"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"high","mastery":"high"},"characterDescription":{"ja":"仮面をかぶった怪盗は、常に観察者だった。心の怪盗団を率いながら、自分の心の底は誰にも見せない。世界は変えるが、自分は変わらない。","en":"The Phantom Thief always behind the mask, always watching. He leads a team and changes the world — yet no one ever really knows what\'s behind those eyes. He\'s the still point in the storm."},"characterReasoning":{"ja":"怪盗団のリーダーとして仲間を率いながらも、仮面の奥の本心は誰にも見せない。低い攻撃性は正面から壊すのではなく「心を盗む」という手法に表れる。ワイルドという才能で多様なペルソナを極める求道心の高さが際立つ。世界は鑑賞と変革の対象だ。","en":"He leads the Phantom Thieves, yet never reveals the true self behind his mask. His low aggression manifests not in passivity but in the method — stealing hearts rather than destroying enemies head-on. The Wild ability represents the pinnacle of mastery pursuit. The world is an object of observation and revolution."}},{"id":"LLLHL","name":{"ja":"黄金の略奪者","en":"The Gold Raider"},"character":"ワリオ","characterGame":"ワリオランド","characterUrl":"https://dic.nicovideo.jp/a/%E3%83%AF%E3%83%AA%E3%82%AA","additionalCharacters":[{"name":"サンズ","game":"Undertale","description":{"ja":"スノーフルの番兵にして、最も「全てを知っている」男。普段は怠惰でジョーク好きだが、ジェノサイドルートでは世界の繰り返しを知る「唯一の審判」として立ちはだかる。強さを誇示せず、必要な時だけ真の力を見せる謎多き傍観者。","en":"A sentry in Snowdin and arguably the most omniscient being in the Underground. Lazy and joke-loving by default, but on the Genocide route he becomes the sole judge who understands the cycle of resets — standing as the last line of resistance. He never shows his power unless forced, a cryptic observer to the end."},"reasoning":{"ja":"基本的には何もしない怠惰な傍観者（低求道心）だが、直感的に全てを見通す高直感の持ち主。利己的で協力しない低利他性・低協調性の性格と、必要な時だけ動く状況対応型の嗅覚が「黄金の略奪者」の構造に重なる。","en":"Fundamentally idle and does nothing most of the time (low mastery), yet possesses an uncanny intuitive grasp of everything (high intuition). His self-serving non-involvement (low altruism, low cooperation) and his situational reactivity mirror the Gold Raider\'s instinct-driven, low-discipline structure."},"url":"https://ja.wikipedia.org/wiki/Undertale"},{"name":"スカルキッド","game":"ゼルダの伝説 ムジュラの仮面","description":{"ja":"友達を求めて彷徨う孤独な子供が、ムジュラの仮面の力に飲み込まれ世界を終わらせようとする。破壊の動機は戦略でも野望でもなく、孤独と恨みという衝動だ。直感と気まぐれで動き、自分でも制御できない力を使いこなす「偶然の略奪者」。","en":"A lonely child wandering in search of friends, consumed by Majora\'s Mask and turned toward ending the world. His destruction has no strategy or ambition — only the raw impulse of loneliness and resentment. He moves on instinct and whim, wielding a power he cannot fully control: an accidental raider."},"reasoning":{"ja":"計画ではなく感情の衝動で月を落とそうとする低協調性・低利他性の存在。直感と衝動が全ての行動原理（高直感）であり、世界を「壊すことで得るもの」を考えない低求道心の略奪者構造だ。","en":"Attempts to drop the moon not through planning but emotional impulse — low cooperation, low altruism. Pure instinct and whim drive every action (high intuition), and his destruction seeks no craft or gain (low mastery): the Gold Raider as a runaway force of pure feeling."},"url":"https://ja.wikipedia.org/wiki/スカルキッド"}],"description":{"ja":"鼻が利く。宝の匂いがすれば、理屈なんて考えない。一人で、自分のためだけに動く。美学？ 効率？ そんなもの知るか。お前が求めるのは目の前の金貨だけだ。純粋な強欲こそ、お前の原動力。","en":"Your nose knows. When treasure\'s near, who needs logic? Moving solo, only for yourself. Aesthetics? Efficiency? Who cares. All you want are the gold coins right in front of you. Pure greed is your driving force."},"deepDescription":{"ja":"エピクロスの快楽主義を最も原始的に体現する存在。快楽こそが善、苦痛こそが悪。哲学を極限まで単純化すると、ワリオになる。","en":"The most primal embodiment of Epicurean hedonism. Pleasure is good, pain is bad. Simplify philosophy to its extreme, and you get Wario."},"recommendedGames":["ワリオランド","WarioWare","Spelunky 2"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"high","mastery":"low"},"characterDescription":{"ja":"金のためなら何でもする。道徳も規則も邪魔なだけだ。嗅覚と欲望だけで動き、その勘がいつも正しい。これが一番シンプルな生き方だろう。","en":"Does anything for money. Morals and rules are just obstacles. Runs purely on gut instinct and greed — and his instincts are almost always right. Probably the most honest character in gaming."},"characterReasoning":{"ja":"マリオへの対抗心すら利益に換算する純粋な利己主義者で低利他性の体現。計画ではなく嗅覚と直感で宝を嗅ぎつける高直感型であり、己の欲を極める意味では何も「道」を追わない低求道心のエゴイストだ。","en":"Turns even his rivalry with Mario into a profit calculation — pure self-interest. Sniffs out treasure by gut instinct, not planning. Pursues no discipline or craft, only pleasure and gold — the definitive low-mastery intuition opportunist."}},{"id":"LLLLH","name":{"ja":"深淵の求道者","en":"The Abyss Seeker"},"character":"選ばれた不死者","characterGame":"Dark Souls","characterUrl":"https://dic.nicovideo.jp/a/Dark%20Souls","additionalCharacters":[{"name":"リュウ","game":"ストリートファイター","description":{"ja":"答えを求めて世界中を旅し、強い相手を求め続ける求道者。仲間も拠点も持たず、ただ「格闘の道」という一点に人生を捧げる。勝利よりも戦いそのものの中に意味を見出し、内なる殺意の波動と孤独に向き合い続ける。","en":"A wanderer who travels the world seeking strong opponents and searching for an answer only combat can provide. No allies, no home, no ambition beyond the martial path itself. He finds meaning in the fight rather than the victory, forever confronting the Satsui no Hado and the solitude it brings."},"reasoning":{"ja":"仲間を作らず一人で旅を続ける低協調性・低利他性の純粋な求道者。感情や直感より型と修練を積み重ねる計算型の高求道心が、「深淵の求道者」の軸に完全に合致する。","en":"Wanders alone without allies or comrades — pure low cooperation, low altruism. His commitment to form and accumulated training over instinct or emotion (high mastery through calculation rather than intuition) aligns perfectly with the Abyss Seeker archetype."},"url":"https://ja.wikipedia.org/wiki/リュウ_(ストリートファイター)"},{"name":"ゾーマ","game":"ドラゴンクエスト3","description":{"ja":"光を憎み、闇そのものの化身として君臨する魔王。アレフガルドを闇で覆い尽くした呪いも世界征服も、全ては「光ある世界を消し去る」という一点の美学から発生する。他者への関心は皆無で、ただ己の「闇の哲学」を完遂することに全存在を賭ける。","en":"The demon lord who reigns as the embodiment of darkness itself, consumed by hatred for light. His curse that shrouded Alefgard in darkness and his conquest of the world both stem from a single aesthetic obsession: to extinguish every world where light exists. Zero interest in others — only the relentless completion of his dark philosophy."},"reasoning":{"ja":"光への憎悪という孤独な哲学のみで動く低利他性・低協調性の存在。直感ではなく「闇の原理」という計算的確信でアレフガルドを封じ（低直感）、その哲学を極める高求道心が「深淵の求道者」の軸に重なる。","en":"Driven solely by a solitary philosophy of hatred for light — low altruism, low cooperation. His conquest follows the calculated certainty of a dark cosmology rather than intuition (low intuition), and his drive to perfect that worldview to its ultimate conclusion marks high mastery as the Abyss Seeker."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストIII_そして伝説へ…"},{"name":"ミルドラース","game":"ドラゴンクエスト5","description":{"ja":"人間への蔑視と「神に近づく力」への渇望だけを動機とする大魔王。配下のゲマを通じて天空の勇者の血族を迫害し、世界を魔族の支配下に置くという野望は、感情ではなく完璧な権力追求という哲学から来る。他者の痛みや希望に対して完全に無関心な純粋な権力の化身。","en":"A demon lord driven purely by contempt for humanity and the obsession of approaching godhood. Through his subordinate Ladja, he persecuted the bloodline of the Zenithian Hero, and his ambition to subjugate the world is not emotional — it is the logical conclusion of a philosophy of perfect dominance. He is utterly indifferent to human suffering or hope."},"reasoning":{"ja":"感情も仲間への関心も持たず権力の完成のみを追う低利他性・低協調性の存在。配下を通じて計算的に勇者の血族を排除し（低直感）、神に近づくための力の追求（高求道心）が「深淵の求道者」の構造を体現する。","en":"No emotion, no interest in allies — only the systematic completion of total power, marking low altruism and low cooperation. He methodically eliminates the hero\'s bloodline through his subordinates (low intuition), and that relentless pursuit of godhood defines high mastery as the Abyss Seeker."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストV_天空の花嫁"},{"name":"デスタムーア","game":"ドラゴンクエスト6","description":{"ja":"「夢を奪う」ことで世界を支配する大魔王。人々の希望や夢そのものを消滅させることが美学であり、虚無の城に君臨しながら全てが無意味だという哲学を体現する。感情的な怒りはなく、ただ「存在の夢を否定する」という確信だけで動く。","en":"A demon lord who rules the world by stealing dreams. His aesthetic is the erasure of human hope and ambition itself — reigning in a castle of nothingness, embodying the philosophy that all things are meaningless. No emotional rage, only the cold conviction to deny the very dream of existence."},"reasoning":{"ja":"夢と希望を否定するという哲学的確信で動く低利他性・低協調性の純粋な虚無の支配者。感情や直感を超えた計算的確信（低直感）と、「虚無の完成」という一点への高求道心が「深淵の求道者」の最も哲学的な体現だ。","en":"Moves from the philosophical conviction to negate dreams and hope — low altruism, low cooperation, a ruler of pure nothingness. His certainty transcends emotion and intuition (low intuition), and his singular drive toward perfecting oblivion (high mastery) makes him the most philosophical embodiment of the Abyss Seeker."},"url":"https://ja.wikipedia.org/wiki/ドラゴンクエストVI_幻の大地"},{"name":"マツブサ","game":"ポケモンRSE","description":{"ja":"「海を消滅させ、大地だけの世界を作る」という哲学的野望に憑かれたマグマ団のボス。人類の利益でも感情でもなく、自分の掲げる「理想の世界」という求道心だけが行動原理だ。組織を動かしながらも、その目的は徹底的に個人的で孤独な哲学から来る。","en":"Leader of Team Magma, driven by the philosophical obsession of awakening Groudon to eliminate the sea and create a world of pure land. Neither human welfare nor emotion guides him — only the solitary pursuit of his personal vision of an ideal world. He commands an organization, but the goal is irreducibly his own."},"reasoning":{"ja":"組織を持ちながらも目的が徹底的に個人的哲学（低利他性・低協調性の本質）で、直感ではなく理念という計算（低直感）に従い、世界改変という「道」を極めようとする高求道心が「深淵の求道者」の構造に重なる。","en":"Commands an organization but his goal is purely his own solitary philosophy — low altruism, low cooperation at core. He follows ideological calculation rather than instinct (low intuition), and his drive to complete his vision of world transformation at any cost (high mastery) places him squarely in the Abyss Seeker."},"url":"https://ja.wikipedia.org/wiki/ポケットモンスター_ルビー・サファイア"}],"description":{"ja":"慎重で、孤独で、計算し、美学だけを信じる。利己的だが、その利己は「完璧な自分」への追求だ。何度死んでも立ち上がる。それは勝利のためではなく、自分を超えるためだ。","en":"Cautious, solitary, calculated, believing only in aesthetics. Self-serving, but that self-service is the pursuit of a \'perfect self.\' Rising after every death — not for victory, but to transcend yourself."},"deepDescription":{"ja":"シーシュポスの神話。終わりなき苦行の中に幸福を見出す。カミュは言った。「シーシュポスは幸福であると想像しなければならない」。","en":"The Myth of Sisyphus — finding happiness in endless struggle. As Camus said: \'One must imagine Sisyphus happy.\'"},"recommendedGames":["Dark Souls III","Elden Ring","ストリートファイター6"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"low","mastery":"high"},"characterDescription":{"ja":"呪われた不死者が何度死んでも立ち上がり、誰にも頼らず深淵へ向かう。感情なし、仲間なし、ただ炎を継ぐという使命と、それを超えるための技術だけがある。","en":"A cursed undead who dies endlessly and keeps walking toward the abyss. No emotion, no allies, no complaint. Just the mission of linking the fire — and the mastery to make it happen."},"characterReasoning":{"ja":"孤独な旅を繰り返しながら戦技を極める姿は低協調性・高求道心の純粋結晶。他者への利益誘導も感情的反応も持たず、死から学び技を磨くプロセスそのものが「深淵の求道者」の本質だ。直感ではなくパターン学習という計算が全ての基盤にある。","en":"Repeating the same grueling journey alone to refine combat technique is low cooperation and pure mastery. No emotional investment in others, no intuitive leaps — only pattern recognition extracted from each death, slowly building toward perfection."}},{"id":"LLLLL","name":{"ja":"沈黙の観察者","en":"The Silent Observer"},"character":"ミュウツー","characterGame":"ポケモン赤緑","characterUrl":"https://dic.nicovideo.jp/a/%E3%83%9F%E3%83%A5%E3%82%A6%E3%83%84%E3%83%BC","additionalCharacters":[{"name":"チェル","game":"Portal","description":{"ja":"言葉を持たず、感情を表に出さず、ただポータルガンと思考だけで謎を解き続ける被験者。GLaDOSとの関係においても協力も反抗も最小限にとどめ、観察と計算で最短経路を見つける。存在そのものが「沈黙の知性」を体現している。","en":"A test subject with no voice, no expressed emotion — only a portal gun and pure cognition working through every puzzle. In her relationship with GLaDOS she minimizes both cooperation and defiance, finding the optimal path through pure observation and calculation. Her existence is the embodiment of silent intelligence."},"reasoning":{"ja":"沈黙・無表情・最小限の行動で生存する低攻撃性・低利他性・低協調性の観察者。直感ではなく論理的計算でパズルを解き（低直感）、技術を磨くより状況適応を優先する低求道心の純粋な生存者だ。","en":"Survives through silence, blank expression, and minimum necessary action — low aggression, low altruism, low cooperation. Solves puzzles through logical calculation rather than intuition (low intuition), and adapts to situations rather than perfecting a discipline (low mastery): the Silent Observer as pure survivor."},"url":"https://ja.wikipedia.org/wiki/Portal_(ゲーム)"},{"name":"エージェント47","game":"Hitman","description":{"ja":"感情を持たないよう訓練されたクローン暗殺者。ターゲット以外の者を巻き込まず、証拠を残さず、完璧な透明性を追求する。依頼人への忠誠も価値観への共感もなく、ただ「仕事の完遂」という一点に全てを収束させる沈黙の計算機。","en":"A clone assassin trained to excise all emotion. He involves no bystanders, leaves no evidence, and pursues perfect invisibility. No loyalty to clients, no sympathy for values — everything converges on a single point: the clean completion of the contract. A silent calculator in human form."},"reasoning":{"ja":"感情・共感・連帯を全て排除した低攻撃性（最小限の暴力）・低利他性・低協調性の観察型暗殺者。直感ではなく事前調査と計算で仕事を完遂し（低直感）、技の道を極めるより効率を追求する低求道心の「沈黙の観察者」だ。","en":"Strips out emotion, empathy, and solidarity — low aggression (minimum necessary violence), low altruism, low cooperation. Completes contracts through prior research and calculation rather than instinct (low intuition), and pursues efficiency over craft mastery (low mastery): the Silent Observer as a living elimination machine."},"url":"https://ja.wikipedia.org/wiki/エージェント47"}],"description":{"ja":"慎重で、孤独で、計算し、効率を追求する。利己的だが、それは生き残るためではない。お前は自分の存在意義を問い続けている。世界を観察する。参加するのではなく、理解するために。全てに距離を置く。その距離こそが、お前の知性だ。","en":"Cautious, solitary, calculated, pursuing efficiency. Self-serving, but not for survival — you keep questioning the meaning of your own existence. You observe the world. Not to participate, but to understand. Distance from everything — that distance is your intelligence."},"deepDescription":{"ja":"ウィトゲンシュタインの言語哲学。「語り得ぬものについては沈黙しなければならない」。お前は沈黙の中に真実を見る。","en":"Wittgenstein\'s philosophy of language — \'Whereof one cannot speak, thereof one must be silent.\' You see truth in silence."},"recommendedGames":["ポケモン赤緑","Portal 2","The Witness"],"axes":{"aggression":"low","altruism":"low","cooperation":"low","intuition":"low","mastery":"low"},"characterDescription":{"ja":"人工的に生み出された最強のポケモン。ミュウの遺伝子から作られ、ハナダの洞窟の奥深くに一人佇む。全てのトレーナーを寄せ付けない圧倒的な力と、何も語らない沈黙が、その存在の全てを物語る。","en":"The strongest Pokémon, artificially created from Mew\'s genes. It waits alone in the depths of Cerulean Cave, its overwhelming power repelling all trainers. That silence and solitary strength tell the entire story of its existence."},"characterReasoning":{"ja":"全5軸が低値という設定は、人工的に作られた存在が何にも属さず、何も求めず、ただ静かに佇む孤高を意味する。攻撃も協力も直感も求道心も持たず、ハナダの洞窟の奥で全てを超越した最強の存在として沈黙し続ける。","en":"All axes low represents an artificially created being that belongs to nothing, seeks nothing, and simply exists in solitary silence. No aggression, no altruism, no cooperation, no intuition, no craft — just the transcendent strongest being, waiting in silence deep within Cerulean Cave."}}]'))}]);